window.HARDTRP.receive("101220",[[101221,"2026-07-09T13:02:13",9,"Начало темы.\n\n@Ashenchampion — Дм этой темы.",101220,null],[101222,"2026-07-09T13:03:14",11,"Сергей @elsio28 \n\nТеперь нужно только время подобрать вам подходящее🤠",101220,null],[101309,"2026-07-09T14:58:40",32,"//подождёте меня?",101220,null],[104031,"2026-07-09T21:48:38",42,"// так Арми свободен и Майло если будет добро на воссоединение братского дуэта?",101220,null],[104065,"2026-07-09T21:57:24",32,"//да но сначала к дракону. Покормить получить и скорее всего убрать за ним",104031,null],[105142,"2026-07-10T02:58:35",32,"Так я тут.",101220,null],[105143,"2026-07-10T03:05:18",11,"// в таверну сперва и завтра уже, Эл спит👌",105142,null],[105391,"2026-07-10T14:07:30",11,"Табакси избегая парочки телепортировалась к Гвиндшарху, и рванула с ним на половину своей скорости рывком скрываясь где-то в переулках \n\n@elsio28 давай здесь продолжим",101220,null],[105392,"2026-07-10T14:08:35",5,"Ничего не понимающий дракон побежал вместе с ней. \n\nТроглодит проводил его немного хитрым взглядом, ещё постоял, а потом ушёл в таверну. Пить.",101220,null],[105396,"2026-07-10T14:13:05",11,"— Уж извини двоих не потащу, да и от друга твоего дурно пахнет, одеколоном такой запашок от моего чуткого обоняния не скрыть — кошачья ловкость дала знать и табакси даже не запыхалась от такого рывка",101220,null],[105397,"2026-07-10T14:13:31",11,"Она протянула драконорожденному лапу для знакомства\n\n— Луна",101220,null],[105404,"2026-07-10T14:14:32",5,"Дракон осторожно пожал руку.\n\n— Нориксиус Гвиндшарх!",105397,null],[105405,"2026-07-10T14:14:52",5,"— Куда мы бежали? И зачем?",101220,null],[105406,"2026-07-10T14:15:58",5,"— Не беспокойся, Гниляк посидит в таверне, делать ему нечего. Может знаешь одеколон, чтобы совсем запах скрыть? Я уже всё испробовал!",105396,null],[105414,"2026-07-10T14:20:26",11,"— Мне показалось что оставаться в таверне настроя ни у кого из нас уже не было?",105405,null],[105416,"2026-07-10T14:21:06",11,"— Зелье маскировки запаха только и поможет — она поморщилась вспомнив запах троглодита и показательно закрыла нос свободной лапкой",105406,null],[105419,"2026-07-10T14:23:43",5,"— Это правда, не было. Значит, просто небольшой кросс. Что ж, я не против",105414,null],[105421,"2026-07-10T14:24:37",5,"Дракон кивнул на жест кошки.\n\n— Да, запах невыносимый. Насчёт зелья запомнил, приобрету, как деньги появятся",105416,null],[105428,"2026-07-10T14:27:15",11,"Табакси направилась на выход из переулка поманив тебя за собой лапой\n\n— Пошли, я знаю тут спокойное местечко",101220,null],[105429,"2026-07-10T14:28:16",5,"Гвинди двинулся за ней, по пути осматривая её хвост",101220,null],[105430,"2026-07-10T14:28:45",11,"— Будто у тебя своего нет, не вежливо так пялится — хвост скрылся за плащом",101220,null],[105432,"2026-07-10T14:30:02",5,"Гвиндшарх смущённо отвел взгляд.\n\n— Извини, Луна. Больше не буду!\n\nОн посмотрел на свой хвост и пошел дальше за кошкой",101220,null],[105436,"2026-07-10T14:34:13",11,"— А на счёт твоего друга тебе поможет заклинание безликий след или его аналог в зелье/свитке, маскирует запахи и не только \n\nОна вывела тебя в дворик-колодец. Удачное время, именно сейчас почти полная луна была посредине небосвода и освещала это место холодным, но довольно ярким светом. Белый мех табакси-альбиноса что вышла из тени как будто стал сиять  \n\n— Карабкаться умеешь? Или здесь посидим?",101220,null],[105439,"2026-07-10T14:37:47",5,"— Заклинание? Спасибо за совет, но я не волшебник...\n\nДракон осмотрел дворик, ища какие-то признаки жилья.\n\n— Карабкаться умею. Но куда мы вообще идём? Я думал, тут тихая таверна поблизости",105436,null],[105440,"2026-07-10T14:39:16",11,"— У меня с собой есть — она похлопала по сумке, а затем ловкие кошачьи лапки вцепились за ближайший балкончик",101220,null],[105441,"2026-07-10T14:39:20",11,"/r d20",101220,null],[105443,"2026-07-10T14:40:22",5,"Гвиндшарх следит взглядом за действиям кошки. Затем достает из рюкзака крюк кошку и закидывает на тот же балкончик.",101220,null],[105444,"2026-07-10T14:40:38",11,"Возможно предыдущие напитки все ещё не выветрились с ее крови. Не сумев зацепится кошка упала, но ловко приземлилась на лапки",101220,null],[105445,"2026-07-10T14:40:45",11,"— Ты не видел этот позор..",101220,null],[105446,"2026-07-10T14:41:17",5,"/r +6 акробатика",101220,null],[105448,"2026-07-10T14:41:19",11,"— Ну давай, твоя попытка, покажи драконью ловкость — она отряхивается",105443,null],[105449,"2026-07-10T14:41:58",11,"Ты стоишь на чем-то балкончике и пока тебя не заметили спящие хозяева лучше бы тебе взбираться на следующий, спутница как раз указывает куда",105447,null],[105450,"2026-07-10T14:42:02",11,"/r d20",101220,null],[105452,"2026-07-10T14:42:54",11,"Второй раз лапы кошки ее не подвели и она абсолютно спокойно запрыгнула к тебе",101220,null],[105453,"2026-07-10T14:43:11",5,"Гвинди смотрит с балкончика на кошку внизу.\n\n Телепатией:\n\"Не видел. Может и ты не увидишь что-то в будущем?\"",105449,null],[105454,"2026-07-10T14:43:23",11,"— Давай дальше, только не разбей людям окно своим приспособлением — произнесла она улыбаясь",101220,null],[105455,"2026-07-10T14:44:11",5,"Гвиндшарх тихо отвечает и вытаскивает крюк к себе.\n\n— Всё под контролем! Сейчас залезу",105454,null],[105456,"2026-07-10T14:44:41",5,"// типа он сегодня закрыл глаза на одно, а завтра она  также закроет на что он сделает",105453,null],[105457,"2026-07-10T14:44:54",5,"/r +6",101220,null],[105459,"2026-07-10T14:45:06",5,"// лезем лезем в соседнее село",101220,null],[105460,"2026-07-10T14:46:52",11,"Раздаётся треск стекла, как и предсказала кошка твой крюк влетел в чужое окно",101220,null],[105461,"2026-07-10T14:46:56",11,"/r d20",101220,null],[105467,"2026-07-10T14:47:40",11,"Она забирается выше и подаёт тебе лапу, из стороны разбитого окна слышны недовольные возгласы \n\n— Давай быстрее пока нас не заметили — она протягивает тебе лапу",101220,null],[105468,"2026-07-10T14:47:47",11,"// давай с преимуществом",101220,null],[105470,"2026-07-10T14:48:00",5,"— Этого не было...",101220,null],[105471,"2026-07-10T14:48:09",5,"/r +d20+6",101220,null],[105473,"2026-07-10T14:48:41",11,"/r d20",101220,null],[105475,"2026-07-10T14:48:55",5,"Дракон схватился за её лапу и неуклюже попытался залезть",101220,null],[105476,"2026-07-10T14:49:30",11,"Чешуя скользит в лапе кошки, но она обхватывает ее и тянет на себя, с трудом вытягивая твою тушку",101220,null],[105477,"2026-07-10T14:49:46",11,"— Теперь на крышу, давай-давай!",101220,null],[105478,"2026-07-10T14:49:49",11,"/r d20",101220,null],[105480,"2026-07-10T14:49:58",11,"// ахаха да что это такое",101220,null],[105481,"2026-07-10T14:50:07",11,"// давай ты",101220,null],[105483,"2026-07-10T14:50:37",5,"// инвалиды лезут",101220,null],[105484,"2026-07-10T14:50:50",11,"В спешке кошка хватается за черепицу, но та ещё более скользкая чем чешуя драконорожденного, впрочем тебе везёт больше и удается зацепиться когтями",101220,null],[105486,"2026-07-10T14:51:44",11,"— Какой стыд, помоги мне — шепотом шипит она снизу, пока на балкон с разбитым окном выходят хозяева\n\nЗаметив это кошка вновь натягивает плащ",101220,null],[105488,"2026-07-10T14:51:46",5,"— Я вроде не пил. Клянусь, обычно я залезаю в недоступные без проблем. А вообще, куда мы лезем?",101220,null],[105489,"2026-07-10T14:51:51",11,"/r d20",101220,null],[105492,"2026-07-10T14:52:14",11,"И плащ помогает ей скрыться от взгляда",101220,null],[105494,"2026-07-10T14:52:17",5,"Дракон протягивает ей лапу, энергично размахивая хвостом для баланса",105486,null],[105495,"2026-07-10T14:52:36",11,"/r +d20",101220,null],[105501,"2026-07-10T14:53:26",11,"Табакси хватается за твою лапу и наконец-то выбирается на крышу \n\n— Фух, прокатило, чуть не заметили — она ложится на крышу слегка посмеиваясь — разве это не весело? Просто хочу выпить здесь любуясь луной",101220,null],[105503,"2026-07-10T14:54:21",11,"— Ой! — она резко спохватилась проверяя не разбились ли бутылки в ее сумке пока она забиралась сюда — фух.. в порядке",101220,null],[105506,"2026-07-10T14:55:34",11,"// какое у тебя восприятие ?",101220,null],[105508,"2026-07-10T14:56:20",5,"Дракон обеспокоено выглянул вниз с крыши.\n\n— Место и правда красивое. Но надеюсь нас и правда не заметили. Мне сейчас даже нечем заплатить за разбитое окно",101220,null],[105512,"2026-07-10T14:56:52",5,"// 14 пассивное",105506,null],[105513,"2026-07-10T14:56:54",11,"— Не переживай, всегда можно убежать, хехе. Так на чем я остановилась.. что предпочитаешь пить?",101220,null],[105516,"2026-07-10T14:58:17",5,"Гвиндшарх задержал взгляд на несколько секунд, а затем кивнул.\n\n— Предпочитаю вино. И ликёр. Или молоко, но ты вряд ли носишь его с собой...",105513,null],[105522,"2026-07-10T14:59:42",11,"— Два из трёх с собой! — она достала две бутылки вина из сумки, одну протянула тебе, вторую оставила возле себя — молоко тоже нужно?",101220,null],[105527,"2026-07-10T15:01:08",11,"// ты же только драконий и общий знаешь или ещё какие языки?",101220,null],[105529,"2026-07-10T15:01:38",5,"— У тебя и правда есть молоко? — Дракон похлопал глазами. — Нет, не нужно, спасибо. К этому месту больше идёт вино",101220,null],[105530,"2026-07-10T15:01:43",5,"// только эти два",105527,null],[105535,"2026-07-10T15:02:56",5,"Гвиндшарх сидит на крыше и тянется к своей бутылке вина.\n\n— Полагаю, здесь не до бокалов. Зато место романтичное. Красивая луна!",101220,null],[105537,"2026-07-10T15:03:48",11,"Держа бутылку в руках ты пытаешься прочесть этикетку, но понимаешь что язык на ней ты не понимаешь",101220,null],[105538,"2026-07-10T15:03:52",11,"// история",101220,null],[105539,"2026-07-10T15:04:18",5,"/r +2",101220,null],[105545,"2026-07-10T15:05:02",11,"Зато ты узнаешь что это эльфийский, очевидно что вино на эльфийской - эльфийское. Теперь ты понимаешь что от него ожидать \n\n(Пьянеешь не сразу, но когда до этого дойдет спас будет высокий и за провал эффект у эльфийского будет свой)",101220,null],[105547,"2026-07-10T15:05:40",11,"/r d20",105512,null],[105550,"2026-07-10T15:06:16",5,"— Эльфийское вино. Редкий экземпляр!",105545,null],[105551,"2026-07-10T15:06:16",11,"Впрочем ты не заметил как записка, что кошка оставила ранее в твоём кармане, незаметно оттуда исчезла",101220,null],[105555,"2026-07-10T15:06:57",11,"— А то! В таверне лучше конечно подают, но зато какая атмосфера — она ловко открыла свою бутылку и сделала глоток",101220,null],[105556,"2026-07-10T15:07:17",11,"— Вы не знакомы были ранее с теми двумя да?",101220,null],[105558,"2026-07-10T15:07:56",11,"— У тебя с тем драконорожденным схожий цвет чешуек, я думала вы поладите",101220,null],[105561,"2026-07-10T15:09:50",5,"— В обычной таверне и такого не найти. Там одно пиво\n\nДракон сделал небольшой глоток из своей бутылки.\n\n— Нет, впервые их увидел. Гниляк что-то к ним пристал, вот я и подошёл разобраться",105555,null],[105566,"2026-07-10T15:13:21",11,"— Я от сородичей давно ничего хорошего не жду — с этими словами она сделала ещё глоток, а затем сморщившись продолжила — а ты?",101220,null],[105568,"2026-07-10T15:16:16",5,"— Смотря от каких. Драконорожденный бывают всех мастей, на них надеяться не стоит. Но сородичам из моего клана я верю. Они не подведут.",101220,null],[105574,"2026-07-10T15:18:55",11,"— Хотела бы я сказать тоже самое — кошка замолчала погрузившись в мысли",101220,null],[105575,"2026-07-10T15:19:39",5,"— А что случилось?",101220,null],[105576,"2026-07-10T15:20:23",11,"— Ну ты же сам пялился на мой хвост, не потому ли что я альбинос?",101220,null],[105584,"2026-07-10T15:23:30",5,"— Нет, твой хвост такой... — Гвиндшарх смутился\n\n— Твои сородичи отвергли тебя из-за окраса? Какие глупые предрассудки!",101220,null],[105590,"2026-07-10T15:27:44",11,"— \"Белая шерсть - дурное знамя для племени\". Так они говорили",101220,null],[105605,"2026-07-10T15:30:03",11,"К этому моменту бутылка Луны стала легче. Она время от времени лакала эльфийский, сладкий алкоголь облизываясь как после молока",101220,null],[105606,"2026-07-10T15:30:04",5,"Дракон покачал головой.\n\n— Не тот цвет шерсти — угроза для племени? Ну и идиоты",101220,null],[105608,"2026-07-10T15:30:26",11,"— А твой клан принял бы дракона с другой чешуей?",101220,null],[105609,"2026-07-10T15:30:27",5,"Гвиндшарх выпил лишь половину бутылки, делая маленькие глотки.",101220,null],[105610,"2026-07-10T15:32:06",5,"— Усыновление — редкая вещь. Но, полагаю, приняли бы. Маленькому дракону нужна семья, независимо от цвета чешуи",105608,null],[105613,"2026-07-10T15:33:34",11,"— Вот и меня \"усыновили\" — последнее слово она намеренно произнесла другой интонацией что бы ты понял что значение у него не буквальное — а я подвожу свою семью",101220,null],[105616,"2026-07-10T15:35:21",5,"— Подводишь семью? Как?",101220,null],[105618,"2026-07-10T15:35:59",11,"— В этом и проблема, Гвинди, я не знаю",101220,null],[105622,"2026-07-10T15:36:22",11,"— Они просто не довольны мной? Я делаю что меня просят, но.. кажется что что-то не так..",101220,null],[105634,"2026-07-10T15:38:03",5,"Гвиндшарх смотрит на табакси и пытается понять.\n\n— Почему ты решила, что они недовольны? Что ты делаешь для них?\n\n— Ты назвала меня Гвинди, Луна?",101220,null],[105637,"2026-07-10T15:38:31",11,"— А? Не стоило сокращать твое имя? Прости, полное слишком длинное",101220,null],[105643,"2026-07-10T15:39:38",5,"— Можешь сокращать. Один друг называет меня также",105637,null],[105644,"2026-07-10T15:40:38",11,"Она болтает полупустую бутылку эльфийского лапкой всматриваясь в пурпурный оттенок напитка\n\n— Потому что они явно были не довольны.. если хочешь можешь сам в этом убедиться. Вскоре мне нужно будет встретиться недалеко с моим \"братом\" и ещё кое-кем кто должен мне помочь",101220,null],[105650,"2026-07-10T15:42:15",5,"— Ты предлагаешь мне встретиться с твоим братом?  А что это за встреча?",105644,null],[105652,"2026-07-10T15:43:20",11,"— Встречаться с ним тебе не стоит, лучше останься на крыше и сам убедись в том что я их разочаровала.. мне предстоит новое задание и я надеюсь не подвести их в этот раз.. — произнесла кошка допивая остатки напитка",101220,null],[105662,"2026-07-10T15:46:41",5,"— О, понаблюдать я могу! Что за новое задание? Какое-то славное дело? Знаешь, я ищу дела, которыми смогу прославить себя и свой клан!\n\nБутылка дракона почти пустая, по мере разговора он по чуть-чуть выпил вино. Теперь он не крепко держится на ногах и разговорчивее",101220,null],[105664,"2026-07-10T15:49:30",11,"Она отрицательно качает головой \n\n— Нет, мои дела должны оставаться в секрете, так что славы я тебе не дам, но — алые глаза опустились к твоему поясу с дротиками — у меня есть кое-что что могло бы тебе пригодиться, но только если ты поможешь мне не разочаровать мою семью снова",101220,null],[105669,"2026-07-10T15:52:24",5,"— Помогу! Твоя семья будет довольна. Правда, я пока совершенно не понимаю, о чём речь. Но надеюсь дело не грязное? Я не буду порочить честь клана",101220,null],[105670,"2026-07-10T15:54:24",11,"— Ты в праве отказаться, а можешь просто быть достаточно расторопным что бы не попасться — она пожала плечами, кажется эффект вина наконец-то давал о себе знать вам обоим",101220,null],[105672,"2026-07-10T15:55:38",5,"— Конечно, я откажусь, если дело будет не по мне. Но сначала должен узнать условия! Когда будет встреча?",101220,null],[105676,"2026-07-10T16:01:33",11,"— Задание озвучит мой брат, но я уверена что задача будет сделать что-то скрытно — голос табакси стал строже — поэтому я предлагаю тебе доступный мне инструмент что поможет тебе в твоих будущих приключениях, но если ты откажешься то я не хочу подставлять себя перед братом и давать тебе подслушать наш разговор.",101220,null],[105677,"2026-07-10T16:04:40",5,"— Скрываться я умею. Хорошо! Что за инструмент?",101220,null],[105679,"2026-07-10T16:07:25",11,"— Я вижу тебе нравятся джавелины, есть у меня кое-что получше простых, само собой не с собой \n\n// Надо будет с Хардом обговорить, но если он согласится, то тебе должно понравиться",101220,null],[105680,"2026-07-10T16:08:32",5,"— Джавелины? Ты имеешь в виду дротики? \n\nДракон достал один и повертел в руках.",105679,null],[105681,"2026-07-10T16:11:15",11,"Кошка кивнула\n\n// И пришло время спасброска тела со сложностью 15 или эльфийские галлюны",101220,null],[105682,"2026-07-10T16:11:43",5,"/r +2",101220,null],[105684,"2026-07-10T16:11:45",11,"/r d20",101220,null],[105686,"2026-07-10T16:12:02",11,"Два алкаша на крыше..",101220,null],[105687,"2026-07-10T16:12:04",5,"// походу щас пьяные на крыше валяться будем",101220,null],[105689,"2026-07-10T16:15:26",11,"— Ох, пробрало похоже.. не знаю как тебя, но мне знаком этот ложный прилив бодрости и уверенности — кошка лезет за напитками от \"мамочки\" в сумку и протягивает тебе один — в другой день я бы повеселилась, но сегодня нельзя, выпей если почувствуешь что вот-вот отрубишься или слишком смелый \n\nОна одним заходом выпивает свою склянку и прячет ее обратно в сумку, а затем идёт вперёд по крыше определяя нужное ей место",101220,null],[105690,"2026-07-10T16:16:52",11,"Определив необходимое направление она готовится перепрыгнуть на другую крышу",101220,null],[105691,"2026-07-10T16:16:56",11,"/r d20",101220,null],[105693,"2026-07-10T16:17:23",11,"И у нее это успешно получается, она встаёт на две лапы и оглядывается ожидая твоих действий",101220,null],[105694,"2026-07-10T16:18:43",5,"Гвиндшарх взял склянку и осмотрел. \"Что же это?\" — подумал он",105689,null],[105695,"2026-07-10T16:18:58",11,"Судя по тому что кошка сама смело выпила это вряд-ли что-то опасное",101220,null],[105696,"2026-07-10T16:19:06",11,"// можешь кинуть проницательность что бы понять:3",101220,null],[105697,"2026-07-10T16:19:11",5,"/r +4",101220,null],[105700,"2026-07-10T16:19:59",11,"Вы только что налакались эльфийского вина и кошка предложила выпить это что бы не вырубиться, похоже это отрезвляющее зелье",101220,null],[105701,"2026-07-10T16:20:57",5,"— Да, иду за тобой!\n\nДракон открыл склянку и выпил. А затем пошёл по крыше за кошкой.",105690,null],[105702,"2026-07-10T16:21:17",5,"/r +6 акробатика",101220,null],[105704,"2026-07-10T16:21:27",11,"/r d20",101220,null],[105708,"2026-07-10T16:21:48",11,"Ты чуть было не упал, но кошка ловко схватила тебя как настоящий джентельмен",101220,null],[105709,"2026-07-10T16:22:09",5,"— Вино действует... Спасибо!",105708,null],[105710,"2026-07-10T16:22:25",11,"— Я должна встретиться с братом и ещё кое-кем в соседнем переулке.. тебе лучше остаться на крыше и надеяться что брат тебя не заметит",101220,null],[105711,"2026-07-10T16:22:46",5,"— С этой крыши будет видно и слышно?",105710,null],[105712,"2026-07-10T16:23:27",11,"— Видно? Может не полностью, но слышно вон на том балконе точно, только спрячься хорошо — произносит она понемногу спускаясь",101220,null],[105714,"2026-07-10T16:24:04",5,"— Понял. Тогда спрячусь там.",105712,null],[105715,"2026-07-10T16:24:53",5,"Дракон осторожно спрыгивает на балкон и укрывается своим плащом. Только глаза блестят",101220,null],[105716,"2026-07-10T16:28:16",11,"// Теперь нужен Сергей \n\nКакое-то время назад Джонатана посетил знакомый на вид белый филин. Птица отдала ему письмо с отпечатком кошачьей лапы, в нем был указан адрес озвученного выше переулка и текст: \"Я обещала подумать о следующей встрече.. так вот мне бы не помешала твоя помощь\"",101220,null],[105717,"2026-07-10T16:28:43",5,"// делаем ритуал призыва",101220,null],[105719,"2026-07-10T16:30:09",11,"// троглодита? Или Сереги",105717,null],[105720,"2026-07-10T16:30:52",5,"// если призвать троглодита, то он сделает большой бум в переулке",105719,null],[105721,"2026-07-10T16:30:57",5,"// и все разбегутся",101220,null],[105722,"2026-07-10T16:31:02",11,"// не надо)",101220,null],[105723,"2026-07-10T16:50:29",53,"//а теперь экстренно вспоминаю кто я и как отыгрываюсь..",105716,null],[105724,"2026-07-10T16:50:55",5,"// если кратко",105723,null],[105725,"2026-07-10T16:51:01",5,"// видишь кошку идёшь за кошкой",101220,null],[105726,"2026-07-10T16:51:53",53,"*кивнув своим мыслям отправляюсь в назначенное место играя тихую мелодию (какое время суток, что за периулок?)*",105716,null],[105727,"2026-07-10T16:52:10",11,"// скоро рассвет, но пока ночь",101220,null],[105728,"2026-07-10T16:55:52",53,"*где то в четверти пути от нцжного места музыка затихает*",105727,null],[105729,"2026-07-10T16:56:11",5,"Гвиндшарх решил заранее подготовить запасной вариант, потому достал отмычки и тихо отпирает дверь балкона.",101220,null],[105730,"2026-07-10T16:56:34",11,"// бросай ловкость рук",101220,null],[105731,"2026-07-10T16:57:07",5,"/r +6 ловкость рук и владение",101220,null],[105733,"2026-07-10T16:57:59",11,"Замок поддается тебе слишком легко, ты заканчиваешь взлом не издав ни звука, но не забывай что внутри могут быть хозяева",101220,null],[105734,"2026-07-10T16:58:11",11,"А тревога здесь явно никому не нужна",101220,null],[105735,"2026-07-10T16:58:42",5,"Дверь взломана, но Гвиндшарх и не думает лезть внутрь",101220,null],[105736,"2026-07-10T16:58:53",5,"// дальше ждёт",101220,null],[105737,"2026-07-10T16:59:35",11,"Со стороны улицы раздаются тихие, едва слышные шаги",101220,null],[105738,"2026-07-10T17:00:27",11,"// теперь скрытность",101220,null],[105739,"2026-07-10T17:00:42",5,"/r +6",101220,null],[105741,"2026-07-10T17:01:11",11,"// озвучивай что делаешь пока",101220,null],[105742,"2026-07-10T17:02:26",5,"Гвинди сидит как мышка, накрывшись плащом",101220,null],[105747,"2026-07-10T17:04:53",11,"Сделав ещё несколько шагов что раздавались уже ближе Гвиндшарх слышит что они затихли, а затем чувствует на себе пронзительный взгляд",101220,null],[105749,"2026-07-10T17:06:29",11,"— Дин, я здесь — голос табакси раздается в тишине и Гвинди больше не чувствует взгляда на себе",101220,null],[105750,"2026-07-10T17:08:21",5,"\"Наверное, показалось\" — подумал Гвинди и сидит, анвострив уши",101220,null],[105751,"2026-07-10T17:08:46",11,"Джонатан приходит в условленное место немного побродив лабиринтом улиц, но все ещё раньше назначенного времени. Это тихий переулок в одном из старых кварталов города, зажатый между каменными домами. Шум центральных улиц сюда доносится лишь приглушённым эхом: где-то вдалеке слышен скрип проезжающей телеги.\n\nНе успев сделать и нескольких шагов вглубь переулка, ты слышишь знакомый женский голос. Обычно уверенный и насмешливый, сейчас он звучит непривычно тихо и виновато.",105728,null],[105752,"2026-07-10T17:08:53",11,"// тоже скрытность",101220,null],[105753,"2026-07-10T17:09:06",11,"// хотя можешь и не скрываться :3",101220,null],[105754,"2026-07-10T17:09:27",53,"ну мне никто не говорил что надо скрыватся, так что покачто без скрытности пойду :3//",105753,null],[105755,"2026-07-10T17:09:42",11,"// иди:3",101220,null],[105756,"2026-07-10T17:09:51",53,"//щас дочитаю",105755,null],[105760,"2026-07-10T17:11:04",53,"*прислушиваюсь к голосу слегка замедляя шаг, дабы услышать в чем там дело*\n//могу прокинуть на восприятие?",105751,null],[105762,"2026-07-10T17:12:12",11,"// ты и так понимаешь чей это голос что ещё хочешь понять?",101220,null],[105763,"2026-07-10T17:12:19",53,"//слова",105762,null],[105765,"2026-07-10T17:12:29",53,"//разобрать что именно говорят",101220,null],[105766,"2026-07-10T17:12:36",11,"// а, ты их слышишь",101220,null],[105770,"2026-07-10T17:13:46",11,"— Госпожа говорила о складе, помнишь? — мужской голос звучал низко и строго, он будто пришел отчитывать ребенка, а не давать задание",101220,null],[105775,"2026-07-10T17:16:35",53,"//голос молодой?",105770,null],[105776,"2026-07-10T17:16:49",11,"— Да, я достаточно узнала о нём в последнее время — Луна храбрилась, будучи уверенной в своем расследование \n\n— И что будет твоим заданием, как думаешь?",101220,null],[105777,"2026-07-10T17:17:12",11,"// взрослого мужчины",105775,null],[105778,"2026-07-10T17:17:21",53,"*сразу после слов табакси, выходя на прямую линию видимости от них, произношу*\n\nмисье, отчего же вы так грубы со столь милой дамой?",101220,null],[105779,"2026-07-10T17:21:06",53,"//ни я, ни мой персонаж не ебем что значит мисье, но по ощущениям оно тут подходит",101220,null],[105780,"2026-07-10T17:24:47",11,"Мужчина в плаще оборачивается хватаясь за меч в ножнах, но оценив тебя пронзительным холодным взглядом пылающих алых глаз отпускает рукоять оружия. Между вами с табакси стоит высокий крепкий дроу, плащ одет поверх панцирной брони, а его лицо покрыто мелкими шрамами. \n\nСтоящая позади табакси испуганно замерла на мгновение, но затем робко произнесла \n\n— Я позвала его, все в порядке",101220,null],[105781,"2026-07-10T17:26:39",11,"— Только ли его? — он отвернулся от Джонатана, понимая что тот не представляет угрозы и вновь смотрел на собеседницу",101220,null],[105782,"2026-07-10T17:27:26",11,"— Не только — она виновато опустила взгляд на землю — драконорожденный тоже со мной",101220,null],[105783,"2026-07-10T17:27:29",53,"*вежливо приветственно и крайне артистично клаяюсь и подхожу ближе*\nрад снова встретится с вами, леди.",105780,null],[105785,"2026-07-10T17:29:27",11,"Луна кивает в ответ, пока дроу смотрит в сторону Гвиндшарха\n\n— Что-ж, тебе стоит потренировать его в том как стоит прятаться если даже я его заметил.",105783,null],[105786,"2026-07-10T17:29:40",53,"//что луна не буду говорить, а то еещ пизды дадут ей за раскрытие имени..",105783,null],[105787,"2026-07-10T17:29:58",11,"// Будет, но не сейчас",101220,null],[105789,"2026-07-10T17:31:08",5,"Гвиндшарх встал на балконе с каменным лицом. А потом ловким движением спрыгнул вниз.",105785,null],[105790,"2026-07-10T17:31:08",11,"Дроу все ещё смотрит на фигуру на балконе, но продолжает говорить \n\n— Так что, знаешь что тебе придётся делать?",101220,null],[105791,"2026-07-10T17:31:48",11,"— Хорошая попытка, другого кого бы провел легко",105789,null],[105792,"2026-07-10T17:32:04",5,"— Меня зовут Нориксиус Гвиндшарх!\n\nДракон сделал небольшой поклон присутствующим. На дроу он поглядывает с опаской.",101220,null],[105793,"2026-07-10T17:32:45",53,"*стою ожидая, пока нам расскажут суть необходимых дел*",101220,null],[105794,"2026-07-10T17:33:20",11,"— Моё полное имя вам знать пока не положено. Но раз уж здесь все такие вежливые — дроу улыбнулся, но казалось будто оскалился — Я Дин.",101220,null],[105798,"2026-07-10T17:34:32",11,"Кошка достаёт записной блокнот из сумки\n\n— Я узнала про артефакт который привезли недавно!",105790,null],[105799,"2026-07-10T17:35:01",53,"*задумчиво киваю и решив тоже представится произношу хриплым голосом древнего старика*\nможете звать меня джоном.",101220,null],[105803,"2026-07-10T17:35:40",53,"//легкий намек на умение изменять голос :3",105799,null],[105805,"2026-07-10T17:35:46",5,"— Приятно познакомиться! — говорит Гвиндшарх и с интересом смотрит на Джона",101220,null],[105806,"2026-07-10T17:36:02",11,"— И мне его нужно будет выкрасть? — добавляет Луна понимая что \"брат\" не реагирует на предыдущие слова",101220,null],[105808,"2026-07-10T17:36:32",53,"//шас арт кину :3\n\n*оглядываю шарха с нескрываемым любопытством*",105805,null],[105816,"2026-07-10T17:38:23",11,"Дроу не впечатлил голос Джонатана, но вот слова табакси его явно разочаровали что отразилось на его лице \n\n— Ты опять сосредоточена не на том. Похоже Госпожа ошибается доверяя тебе.",101220,null],[105818,"2026-07-10T17:38:48",5,"*ты видишь драконорождённого в лёгкой броне и колчан с дротиками на поясе*",105808,null],[105819,"2026-07-10T17:39:18",11,"— Но я ведь выполнила задание! Сделала все что меня просили.. — виновато отвечает Луна.\n\n— Верно, все что тебя просили — он цокнул языком — Но с чего ты решила что задание ограничивается лишь этим? \n\nПоследние слова дроу произнес оглядываясь на вас двоих",101220,null],[105820,"2026-07-10T17:39:22",5,"// не шарха, а шейха. Также можешь называть его папочкой",105808,null],[105823,"2026-07-10T17:39:33",11,"// азахахахв что",105820,null],[105824,"2026-07-10T17:40:04",53,"ну тут он шарх :3//",105805,null],[105825,"2026-07-10T17:40:12",5,"// проницательно смотрю на него, пытаясь понять о чем речь",105819,null],[105826,"2026-07-10T17:40:43",11,"// ну давай",101220,null],[105829,"2026-07-10T17:40:58",53,"*вопросительно смотрю на дроу*",105819,null],[105830,"2026-07-10T17:41:02",5,"/r +4",101220,null],[105833,"2026-07-10T17:43:00",11,"Гвиндшарх понимает что Луна не совсем поняла смысл задания, дроу явно не понравилась формулировка \"украсть артефакт\"",101220,null],[105834,"2026-07-10T17:44:43",5,"— Так что нам надо сделать с артефактом, Дин?",101220,null],[105837,"2026-07-10T17:46:20",11,"— Возможно у вас и получится — дроу кладёт руку в панцирных латах тебе на плечо — вопрос действительно в артефакте, но больше я и сам не знаю, вам предстоит разобраться в этом",101220,null],[105838,"2026-07-10T17:46:54",11,"Отпуская тебя он делает шаг в сторону выхода из переулка.\n\n— Не подведи её... снова и удачи",101220,null],[105839,"2026-07-10T17:47:03",11,"// ага щас так я вам и расскажу все:3",101220,null],[105840,"2026-07-10T17:47:06",53,"*ещк более задумчиво смотрю на него, затем пепевржу взгляд на табакси*",105837,null],[105841,"2026-07-10T17:47:11",11,"// 20 бы выкинул может бы и рассказала",101220,null],[105842,"2026-07-10T17:47:46",53,"//мне б понять хоть что то из происходящего :D",105839,null],[105843,"2026-07-10T17:47:49",11,"Луна несколько секунд молча смотрит ему вслед и как только ее коллега исчезает она обращает свое внимание на Джонатана, натягивает привычную улыбку и слегка разводит руками.\n\n— Здравствуй снова, Джонатан. Спасибо, что пришёл.",105840,null],[105847,"2026-07-10T17:48:22",5,"— Звучит как \"есть артефакт, сделай то, не знаю что\". Странные у вас поручения дают",101220,null],[105848,"2026-07-10T17:48:29",53,"*киваю*\nкак поживаете, леди луна?",105843,null],[105851,"2026-07-10T17:48:46",5,"// каким голосом?",105848,null],[105852,"2026-07-10T17:48:54",53,"//обычным",105851,null],[105853,"2026-07-10T17:49:06",53,"//голосом молодого парня лет 20 :3",101220,null],[105857,"2026-07-10T17:50:29",5,"Гвиндшарх смотрит на парня сверху вниз (он выше)\n\n— Интересные у тебя фокусы, Джон. Ты актёр?",101220,null],[105858,"2026-07-10T17:50:47",11,"— Как видишь так себе. Я понятия не имею что он от меня хочет, это как будто бы испытание? Которое я уже раз провалила и больше провалить не могу — она все ещё улыбается, но вы знаете что точно не искренне",101220,null],[105860,"2026-07-10T17:51:40",53,"артист, музыкант и путешественник \n*слегка болтаю босой ногой*",105857,null],[105861,"2026-07-10T17:51:45",5,"— Да он сам не знает, что хочет. Надо лишь сделать, чтобы Госпожа была довольна. А кто она, позволь спросить?",105858,null],[105862,"2026-07-10T17:52:05",11,"// а Джонатан ее видел кстати",101220,null],[105864,"2026-07-10T17:52:49",53,"не беспокойся так сильно. все наладится, ведь мы с тобой \n\n\n*искренне по доброму улыбаюсь*",105858,null],[105865,"2026-07-10T17:53:07",53,"//я думал ее юра видел",105862,null],[105866,"2026-07-10T17:53:08",5,"— Мгм, у тебя в арсенале есть фокусы и посильнее, так ведь?",105860,null],[105867,"2026-07-10T17:53:19",11,"// а если я тебя раньше утащила то да сори сама уже забыла",105865,null],[105868,"2026-07-10T17:54:07",53,"//XD неа.\n\n*отвечаю голосом драконорожденного*\nвозможно.",105866,null],[105869,"2026-07-10T17:54:58",11,"Слова Джонатана слегка приободрили ее и она перестала улыбаться, но говорила менее напряженно \n\n— Госпожа Ди? Она для меня мама, единственная кто приютил меня и верит в меня, я не могу разочаровать её ещё сильнее",101220,null],[105870,"2026-07-10T17:55:32",11,"// а кстати забыла..",101220,null],[105871,"2026-07-10T17:55:37",5,"Телепатически Джону, пародируя его голос:\n\"Возможно\"",105868,null],[105872,"2026-07-10T17:56:12",11,"Вы так же видели щит дроу со странным рубином в форме аспида в качестве священного символа.",101220,null],[105873,"2026-07-10T17:57:17",11,"— Я позвала вас так как надеюсь что одна голова хорошо, а три лучше.. дело точно в артефакте, но как вы видите просто украсть Дина не устраивает — она пожимает плечами",105869,null],[105874,"2026-07-10T17:57:20",53,"и что же вы планируете делать с артефактом? да и что это за артефакт?",105869,null],[105875,"2026-07-10T17:57:20",5,"— Она верит в тебя, значит ты сможешь разобраться. Или мы, правда я всё ещё не понимаю, в чем суть дела.",105869,null],[105876,"2026-07-10T17:57:47",5,"— А почему у твоего брата змея на щите?",105872,null],[105877,"2026-07-10T17:57:50",53,"//группа поддержки кошкодевочки :3",101220,null],[105878,"2026-07-10T17:59:29",11,"— Мне лишь сказали следить за складом и узнать когда прибудет артефакт — она вновь погрустнела — я так и сделала, так что увы больше ничего не знаю",105874,null],[105879,"2026-07-10T18:00:30",11,"— Аспид? Это символ хозяйки, брошку она ему тоже подарила",105876,null],[105880,"2026-07-10T18:00:38",53,"быть может мы попробуем разузнать побольше об артефакте?",105878,null],[105881,"2026-07-10T18:00:53",5,"— И с такими инструкциями от тебя ожидают результата? \n\nДракон развел руками.",105878,null],[105882,"2026-07-10T18:00:54",11,"// а говорите не знаете что делать:3",101220,null],[105883,"2026-07-10T18:01:04",11,"*Луна кивает*",105880,null],[105884,"2026-07-10T18:01:31",53,"//я вообще думал притворится кем то другим и купить арт, но как то мало данных для такого. так что надо разузнать",105882,null],[105885,"2026-07-10T18:02:08",11,"// не купить не получится, скрытая вещица, поэтому она и разнюхивала где он",101220,null],[105887,"2026-07-10T18:02:51",5,"— Ладно, задание правда странное, но я помогу. Расскажешь, что за склад? Какая охрана? Нам придется подобраться ближе, чтобы понять что-нибудь",105880,null],[105888,"2026-07-10T18:03:23",53,"я всегда к вашим услугам леди.",105883,null],[105889,"2026-07-10T18:03:30",53,"*снова поклон*",105888,null],[105890,"2026-07-10T18:03:41",11,"— Мы всегда так действуем. Нужно не просто выполнить задание, а уметь разбираться самостоятельно и действовать по ситуации так как это будет выгодно \"клану\" — очевидно она не имела ввиду клан, просто сказала это что бы тебе было понятнее",105881,null],[105891,"2026-07-10T18:04:06",11,"— О, вот это я знаю!",105887,null],[105892,"2026-07-10T18:04:19",5,"Дракон хитро улыбается парню, услышав его тон",105888,null],[105893,"2026-07-10T18:04:35",53,"//тон?",105892,null],[105895,"2026-07-10T18:04:44",11,"— Но для начала давайте доберёмся к самому складу.. я расскажу всё там, а рассказать мне есть что! — она явно гордится тем что накопала",101220,null],[105896,"2026-07-10T18:04:44",5,"// стиль речи окей",101220,null],[105897,"2026-07-10T18:05:40",5,"— Мой клан не требует отчётов. Хорошо, пойдем разбираться на месте",105890,null],[105898,"2026-07-10T18:06:04",53,"*киваю и следую за ней обдумывая следующие шаги*",105895,null],[105901,"2026-07-10T18:10:23",11,"Пока вы разговаривали солнце начало выглядывать из-за горизонта. Где-то в соседнем дворе стража разговаривала с хозяином разбитого окна пытаясь разобраться в произошедшем и поторапливая Луну и Гвинди покинуть место.\n\nПокинув дворы кошка вывела вас на главную улицу. Горожане суетились вокруг вас в утренней рутине. Ещё немного погодя вы вышли к улице возле пирса.",101220,null],[105902,"2026-07-10T18:11:12",5,"// незнакомый голос произнес в голове хозяина разбитого окна \"Это был я, Дио\"",105901,null],[105903,"2026-07-10T18:11:25",53,"*запоминаю голоса стражников по пути*",105901,null],[105905,"2026-07-10T18:11:55",11,"Людей сильно меньше не становится, работяги уже таскают ящики с прибывших кораблей и никто не обращает на вас внимания",101220,null],[105906,"2026-07-10T18:12:21",11,"— Пришли — кошка показывает лапой на нужнее здание",101220,null],[105908,"2026-07-10T18:12:38",5,"*Осматриваю здание*",101220,null],[105909,"2026-07-10T18:12:48",53,"*осматриваю это здание и пытаюсь найти места через которые можно попасть внутрь*",105906,null],[105911,"2026-07-10T18:13:18",11,"— Вижу ваш энтузиазм, но поверьте я уже сделала всё за вас",101220,null],[105912,"2026-07-10T18:13:44",53,"//лишним все равно не будет :3",105911,null],[105913,"2026-07-10T18:15:03",11,"Перед вами двухэтажный, приличных размеров, склад. Вокруг него высокий забор, но второй этаж хорошо за ним видно. Входные ворота открыты так как рабочий день как раз начался. Если присмотреться можно заметить что у склада есть свой причал",101220,null],[105914,"2026-07-10T18:15:11",5,"— У тебя есть план проникновения?",105911,null],[105915,"2026-07-10T18:15:13",53,"2 глаза хорошо, а 6 лучше",105911,null],[105916,"2026-07-10T18:15:46",5,"— Причал! Как насчёт зайти с воды?",101220,null],[105921,"2026-07-10T18:16:35",11,"— Не один, друг мой, не один — Луна достаёт небольшой, слегка помятый, блокнот, который вы уже видели ранее — желаете послушать?",105914,null],[105922,"2026-07-10T18:16:45",11,"— Вполне вероятно",105916,null],[105923,"2026-07-10T18:17:17",5,"— Конечно, расскажи!",105921,null],[105924,"2026-07-10T18:17:29",53,"*киваю*",105921,null],[105925,"2026-07-10T18:17:33",11,"— Слушайте — она указывает когтем свободной лапы на склад — Сейчас здесь почти проходной двор: местные работники и дельцы то и дело входят и выходят создавая естественный поток людей.",101220,null],[105931,"2026-07-10T18:19:24",11,"— На счёт причала.. — она облизывает палец и перелистывает страницу — Примерно через час сюда должен прийти торговый корабль. Они разгружают товар прямо внутрь склада. Ящики почти никто не проверяет — главное, чтобы печати совпадали. По крайней мере так выглядит со стороны, но я бы опасалась шпионов, всё же глава гильдии не совсем дурак.",101220,null],[105932,"2026-07-10T18:19:27",5,"— Не уверен, что мы сойдем за работников",105925,null],[105933,"2026-07-10T18:20:24",11,"— Как я уже сказала здесь ходят дельцы, не только работники..",101220,null],[105934,"2026-07-10T18:20:58",53,"у работников есть какая то определенная отличительная черта одежды?",105933,null],[105935,"2026-07-10T18:21:02",5,"— Ты предлагаешь залезть внутрь ящиков? Звучит рискованно, я бы предпочел подплыть на лодке",105931,null],[105938,"2026-07-10T18:21:58",5,"— За дельца я сойду. Даже костюм есть для такого случая",105933,null],[105940,"2026-07-10T18:22:46",11,"— На самом деле не особо, просто непримечательная удобная одежда, но и на работяг мы не сильно смахиваем, Гвинди прав, слишком примечательные",105934,null],[105941,"2026-07-10T18:23:26",11,"— Плыть куда? Лодка причаливает у склада, нужно же как-то попасть внутрь затем, да и вход там тоже сторожат",105935,null],[105942,"2026-07-10T18:24:48",5,"— Могу дать тебе молоток и инструменты. Одежда у тебя подходящая и так, за рабочего сойдёшь",105934,null],[105943,"2026-07-10T18:25:22",11,"— А что на счёт нас?",101220,null],[105944,"2026-07-10T18:25:25",5,"— Да, план с маскировкой выглядит лучше",105940,null],[105945,"2026-07-10T18:25:41",53,"*указываю на волосы и глаза*\n\nбудь у меня набор для гримма, я мог бы попробовать. но волосы и глаза слишком примечательны. к тому же нас трое.",105942,null],[105946,"2026-07-10T18:25:43",11,"— У меня есть ещё что сказать, не торопись",105944,null],[105947,"2026-07-10T18:26:27",11,"Табакси ненадолго затихает сосредотачиваясь на содержании своих заметок, вы видите что целый разворот потрачен на зарисовку двух зданий \n\n— Слева стоит заброшенный зерновой склад в который не составит труда пробраться. Здания немного на разных уровнях высоты, но достаточно близко друг к другу.",101220,null],[105948,"2026-07-10T18:26:33",5,"— У меня есть отличный костюм и кольцо-печатка. А тебе могу дать большой свиток, Луна. Замаскируешься как моя ассистентка",105943,null],[105951,"2026-07-10T18:27:24",11,"— Звучит как вариант, на счёт Джонатана я бы не переживала.. умеет он языком чесать",101220,null],[105955,"2026-07-10T18:28:15",53,"звучит неплохо. осталось узнать что надо достать и я смогу вам это передать. при должном уровне удачи и доверчивости рабочих.",105948,null],[105958,"2026-07-10T18:29:18",5,"— Да, меня тоже волнует, что мы будем делать, когда попадём внутрь",105955,null],[105959,"2026-07-10T18:29:39",11,"— Здесь много народу ходит, если мы не будем лезть куда не работягам не положено, то и спрашивать нас никто не будет — кошка снова указала на поток людей — но дальше нужно будет думать что делать, уверена артефакт будет где-то спрятан",101220,null],[105960,"2026-07-10T18:30:44",11,"— На самом деле нам не обязательно идти днём",101220,null],[105961,"2026-07-10T18:30:47",5,"— Мы как раз собираемся залезть в такое место. Есть ли внутри здания уголок, чтобы мы вышли из толпы и дальше действовали скрытно?",105959,null],[105962,"2026-07-10T18:30:58",53,"пологаю артефакт следует заменить чем то схожим. иначе его могут начать искать.",105959,null],[105963,"2026-07-10T18:31:30",11,"— Сперва нужно узнать что это за артефакт что бы понять чем его заменить",105962,null],[105964,"2026-07-10T18:31:41",11,"— Уверена",105961,null],[105965,"2026-07-10T18:32:03",11,"Кошка пробежалась глазами по последним страницам, а затем закрыла блокнот и спрятала его в сумку. Заметки закончились, но у неё ещё остался последний совет:\n\n— Ночью грузы по складу никто не носит, так что там только охранники которых на порядок меньше чем днём, но они патрулируют с мастифами. А ещё видела я местных головорезов, неприятные на вид типы, не советовала бы с ними связываться.",105960,null],[105966,"2026-07-10T18:32:17",5,"Дракон качает головой.\n\n— Заменить артефакт? Для такго нужна магическая иллюзия",105962,null],[105967,"2026-07-10T18:32:31",53,"//ищем то не знаю что. для того не знаем что, за тем не знаем зачем",105963,null],[105968,"2026-07-10T18:33:15",53,"*достаю из мешка с вещами брусок дерева*",105966,null],[105969,"2026-07-10T18:33:32",11,"— Это я знаю, хватит что бы нам уйти",105966,null],[105970,"2026-07-10T18:33:45",53,"зачем нам использовать калдунства, если можно просто сделать реплику?",105968,null],[105971,"2026-07-10T18:33:53",5,"— Мастиффы и головорезы? Не нравится мне это. Я предпочту идти днём и без жертв.",105965,null],[105972,"2026-07-10T18:34:10",5,"*достаю из рюкзака железный горшок*",105968,null],[105973,"2026-07-10T18:34:13",11,"— Головорезы там и днём, ещё и стражи больше",101220,null],[105974,"2026-07-10T18:34:15",5,"— Вот основа для реплики",101220,null],[105975,"2026-07-10T18:34:35",11,"— А прокрасться незаметно можно попробовать и ночью через крышу",101220,null],[105976,"2026-07-10T18:35:28",11,"Кошка просто состоит на ваши вещи взглядом типа: 😁👍",105974,null],[105977,"2026-07-10T18:36:01",11,"Пока вы говорили солнце понемногу начало прятаться за свинцовые тучи, если прислушаться то можно услышать что где-то вдалеке гремит гром. Ушки Луны немного дернулись улавливая это.\n\n— Похоже будет гроза — озвучила она свои очередные наблюдения, а затем воскликнула — О! Чуть не забыла! Я слышала что недавно они наняли ученика мага. Не знаю уж зачем им это, но возможно мы встретим его так что вам стоит быть готовыми к этому и магическим трюкам внутри. Как бы то ни было, я закончила с советами, что думаете?",101220,null],[105978,"2026-07-10T18:36:21",5,"— Можно. Я всё ещё за дневное проникновение. В случае чего скажем, что зашли не туда.",105975,null],[105979,"2026-07-10T18:36:23",53,"мастифы? \n(мысли: это те которые песики?)",105971,null],[105980,"2026-07-10T18:37:07",11,"— Имеешь ввиду что заблудились?",105978,null],[105981,"2026-07-10T18:37:20",5,"__ Да, именно так",105980,null],[105982,"2026-07-10T18:37:45",5,"— А ты что думаешь?",105979,null],[105983,"2026-07-10T18:37:55",53,"мой дед рассказывал что маги умеют помечать вещи своим колдавством. может и они так сделали?",105977,null],[105984,"2026-07-10T18:37:56",11,"— Лучше бы нам на глаза не попадаться в любом случае иначе выпроводят..",101220,null],[105985,"2026-07-10T18:38:24",11,"Луна наклонив голову смотрит на тебя не совсем понимая что ты имеешь ввиду",105983,null],[105986,"2026-07-10T18:38:38",53,"согласен. днем работник на складе вызовет меньше подозрений.",105978,null],[105987,"2026-07-10T18:39:04",53,"мммм...",105985,null],[105989,"2026-07-10T18:39:32",53,"кажется он называл их охранными знаками.",101220,null],[105990,"2026-07-10T18:40:08",11,"— Хорошее замечание, осторожность не повредит",101220,null],[105991,"2026-07-10T18:40:16",53,"такие знаки наносятся на предмет и могут следить за ним\nа некоторые даже взрываются или издают громкие звуки",105989,null],[105992,"2026-07-10T18:41:10",5,"*кивает*\n\n— Тогда предлагаю готовиться. Кстати, держите. Хочу обойтись без жертв, так что используйте, когда нужно.\n\n*дракон дал каждому 1 штуку кандалов*",105984,null],[105993,"2026-07-10T18:41:55",11,"— Я бы тоже предпочла обойтись без жертв, а лучше всего ещё и без свидетелей — табакси взяла кандалы с твоих лап",101220,null],[105994,"2026-07-10T18:41:59",5,"— Магическая защита! Да, надо глядеть в оба. Как их обнаружить?",105991,null],[105996,"2026-07-10T18:42:43",53,"у тебя нет краски или чего то что может окрасить волосы в другой цвет?",105980,null],[105997,"2026-07-10T18:43:11",53,"ещеб я знал. это все что рассказывал мне дед.",105994,null],[105998,"2026-07-10T18:43:13",5,"// это типа зелёные у тебя?",105996,null],[105999,"2026-07-10T18:43:31",5,"— Надо было лучше слушать!",105997,null],[106000,"2026-07-10T18:43:31",11,"— Обнаружением магии, есть у меня такие свитки.. но ограниченное количество",101220,null],[106002,"2026-07-10T18:43:56",53,"//седые переходящие в зелееый если верно помню.",105998,null],[106005,"2026-07-10T18:44:06",5,"— Можно мне один?",106000,null],[106006,"2026-07-10T18:44:59",11,"// а не дофига хочешь) если надо будет дам",101220,null],[106007,"2026-07-10T18:45:12",11,"// давай убеждение",101220,null],[106008,"2026-07-10T18:45:18",5,"/r +0",101220,null],[106010,"2026-07-10T18:45:32",11,"— Если пригодится дам — ответила табакси",101220,null],[106011,"2026-07-10T18:45:51",5,"— Хорошо. Давайте готовиться",101220,null],[106012,"2026-07-10T18:46:27",11,"— Нет, себя я обычно заклинанием маскирую.. но оно только на меня работает — она задумавшись посмотрела на тебя",105996,null],[106013,"2026-07-10T18:46:41",5,"Гвиндшарх вытащил красивое кольцо с драконьей головой и надел на указательный палец",101220,null],[106014,"2026-07-10T18:47:17",11,"— Иди ка сюда, Джонатан — кошка села на досках предлагая тебе сесть чуть ниже, параллельно она искала что-то в своей сумке",101220,null],[106015,"2026-07-10T18:47:28",5,"— У меня есть мел. Если хочешь белые волосы.",105996,null],[106017,"2026-07-10T18:48:25",53,"дед рассказывал много историй. \nеще он рассказывал о проклятьях. не уверен верно ли я помню, но возможно эти знаки могут еще и их наложить. \n\nкак же там было...\n\n*голос переходит на шепот себе под нос*\n\n\"и вот когда роберто вытащил этот ключ, на двери загорелись яркие знаки, что начали вливать в его тело проклятую силу, а потом он\".. точно... \" а потом он начал гнить прямо на глазах и пал от этого чудовищьного проклятия. но дементий вылечил его даже из состояния трупа. хороший был врач\"\n\n*голос вернулся в обычное состояние*\n\nитак, направимся сразу на место илипродолжим обсуждение?\n\n*подошел чуть ближе к луне*",105999,null],[106018,"2026-07-10T18:48:38",53,"подойдет.",106015,null],[106019,"2026-07-10T18:49:13",53,"*подошел к кошке*",106014,null],[106020,"2026-07-10T18:49:23",53,"*и сел рядом*\n\n\n//не совсем понял что за доски",106014,null],[106021,"2026-07-10T18:49:27",5,"— Захватывающе. Много зарабатываешь на выступлениях?",106017,null],[106022,"2026-07-10T18:49:52",5,"Кажется, дракон теперь не очень верит словам Джона",101220,null],[106023,"2026-07-10T18:50:25",11,"Луна берёт твои волосы и начинает расчёсывать гребнем что был у нее в сумке\n\n— Мудрый твой дед был, но мне кажется что ученик мага на такие вещи как серьезные проклятия вряд-ли способен",106017,null],[106024,"2026-07-10T18:50:27",53,"я редко попадаю в города.",106021,null],[106025,"2026-07-10T18:51:03",53,"//а джон просто вспоминал историю что рассказывал дед :3",106022,null],[106027,"2026-07-10T18:51:42",53,"*джонатан елезаметно покраснел*",106023,null],[106028,"2026-07-10T18:52:04",5,"Гвиндшарх тем временем отправился за угол, где переоделся в красивый костюм",101220,null],[106029,"2026-07-10T18:53:00",11,"Гвиндшарх видит что волосы артиста меняют цвет под его настроение, теперь кошка закрепляет лентой в аккуратный хвост рыжие волосы",106027,null],[106030,"2026-07-10T18:53:08",11,"— Ленту можешь оставить себе",101220,null],[106031,"2026-07-10T18:53:20",53,"а как действует это чудотворство?",106012,null],[106032,"2026-07-10T18:53:59",11,"// хоумбрю гребень, я вам его не дам так что думаю всем будет похер",101220,null],[106033,"2026-07-10T18:54:07",11,"— Это временно, не переживай",101220,null],[106034,"2026-07-10T18:54:33",11,"— Хозяйка любит когда я заплетаю ее волосы с этой штукой",101220,null],[106036,"2026-07-10T18:54:55",53,"*с интересом рассматриваю гребень*",106034,null],[106037,"2026-07-10T18:55:07",5,"Дракон в костюме вышел из-за угла.\n\n— И какого цвета становятся её волосы?",106034,null],[106039,"2026-07-10T18:55:40",11,"— В зависимости от ее настроения, ты давай тут не светись, зайди пока за угол хоть",106037,null],[106040,"2026-07-10T18:56:09",53,"эх.. а ведь когда то мои волосы были цвета соломы...\n\n*в голосе некоторая печаль*\n\n\n//щас волосы будут в цвет диско с такой бурей эмоций :D",106033,null],[106041,"2026-07-10T18:56:15",5,"*накинул на себя дорожный плащ и стою рядом*",106039,null],[106042,"2026-07-10T18:56:25",11,"— А что с ними случилось?",106040,null],[106044,"2026-07-10T18:57:22",53,"был я в одном лесу.\nа там чудовище с множеством лиц. \nкрайне голодное чудовище.\nпосле встречи с ним мои глаза поменяли цвет, а волосы поседели.",106042,null],[106045,"2026-07-10T18:58:20",11,"Закончив с волосами Джонатана табакси заходит за забор что бы ее фокусы кому не надо не видели и что-то шепча меняет облик на человеческий: белые волосы вместо белой шерсти, но прежние алые глаза",106041,null],[106046,"2026-07-10T18:59:13",53,"что ты знаешь об артефакте, луна? \nи может быть сменим имена на время поисков?",106045,null],[106047,"2026-07-10T18:59:25",11,"— И как ты ушел оттуда? — Она отряхнула иллюзорный деловой костюм",106044,null],[106048,"2026-07-10T19:00:09",53,"то что заперло нас в том лесу нас и отпустило. мы пробыли в том лесу около полутора суток.",106047,null],[106049,"2026-07-10T19:00:21",11,"— Идея с именами мне нравится. Про артефакт знаю лишь то что кому-то он сильно нужен так что его очень стараются скрыть",106046,null],[106050,"2026-07-10T19:00:41",5,"— У людей таких глаз не бывает. Но думаю, никто не обратит внимания.",106045,null],[106051,"2026-07-10T19:00:46",53,"*достаю из мешка несколько длинных кусков ткани и обматываю ими ноги (+- как бинты выглядит)*",101220,null],[106052,"2026-07-10T19:00:47",11,"— Не хочется вернуться туда и отомстить как нибудь?",106048,null],[106053,"2026-07-10T19:01:08",5,"— Да, придумайте мне имя! А то  я забуду и представлюсь по привычке",106046,null],[106054,"2026-07-10T19:01:13",11,"— Альбиносы есть среди всех, драконорожденный, даже среди вас — обиженно произнесла она",106050,null],[106055,"2026-07-10T19:01:14",53,"не думаю что переживу такую попытку.",106052,null],[106056,"2026-07-10T19:01:56",5,"— Хмм, может и правда есть исключения. Но я таких не встречал",106054,null],[106057,"2026-07-10T19:02:16",11,"— Сперва стать сильнее? Судя по тому что ты говорил твой дед был тем ещё авантюристом, думаю тебе стоит брать с него пример",106055,null],[106058,"2026-07-10T19:04:14",11,"— Я плохо разбираюсь в том как драконов называют, Гвинди, лучше тебе самому придумать..",101220,null],[106059,"2026-07-10T19:05:02",11,"— А у людей какие имена самые популярные? Думаю Томас и Мэри хорошо подойдут?",101220,null],[106060,"2026-07-10T19:05:21",53,"верно. пусть это и займет много времени, но стать сильнее я постараюсь. не зря же меня направили быть героем...\nхотя в деревне было намного приятнее чем в том лесу.  \n*печальный вздох*\nи кто ж решил что именно я должен им стать? \nвпрочем не важно.",106057,null],[106061,"2026-07-10T19:05:42",53,"тогда я буду томасом.",106059,null],[106062,"2026-07-10T19:05:51",11,"— Если ты отправился в путь, то ты чего-то ищешь",106060,null],[106063,"2026-07-10T19:06:44",53,"я ищу цель в жизни. и то как стать героем.",106062,null],[106064,"2026-07-10T19:07:18",11,"— Надеюсь вы оба найдете то чего ищете.. а я вот просто хочу помогать Госпоже, ну что-ж, пойдем?",101220,null],[106065,"2026-07-10T19:07:21",53,"жа и на красоты мира посмотреть неплохо бы.",106063,null],[106066,"2026-07-10T19:07:33",11,"— Гвинди, дай ботинки нашему другу..",101220,null],[106067,"2026-07-10T19:07:42",5,"— Ладно, назовусь Барминиром из клана Телирон",106058,null],[106068,"2026-07-10T19:07:45",53,"каков наш план?",106064,null],[106069,"2026-07-10T19:08:04",11,"// это вы план озвучивайте, мое дело подсказки дать и помогать:3",101220,null],[106070,"2026-07-10T19:08:24",53,"//эт я к тому что пока не идем а план обсуждаем :3",101220,null],[106071,"2026-07-10T19:09:11",5,"Дракон отдал пыльные дорожные боты парню. Внутри они изрезаны чешуйками на стопах дракона.\n\n— Ты всегда ходишь босым?",106066,null],[106072,"2026-07-10T19:09:21",11,"Пока вы прохлаждаетесь небо продолжает заполняться грозовыми тучами",101220,null],[106073,"2026-07-10T19:09:45",53,"я могу притворится рабочим и разузнать больше об артефакте. \nзатем передать вам все что узнаю при \"случайной\" встрече",106072,null],[106074,"2026-07-10T19:10:07",53,"да.\n*надеваю дорожные боты*",106071,null],[106075,"2026-07-10T19:10:23",11,"— Ты уверен что простые рабочие знают что-то про артефакт?",101220,null],[106076,"2026-07-10T19:10:27",5,"— Как насчёт зайти всем вместе, Джон — работник, Луна — ассистентка. Там находим укромное место и дальше подбираемся скрытно",101220,null],[106077,"2026-07-10T19:10:31",11,"// спойлер нет",101220,null],[106078,"2026-07-10T19:11:00",53,"наврядли. но рабочие могут попасть в намного более широкий список мест, нежели посетители.",106075,null],[106079,"2026-07-10T19:11:05",5,"— Молоток нужен? И инструменты?",106074,null],[106080,"2026-07-10T19:11:39",11,"— Тут не поспоришь",106078,null],[106081,"2026-07-10T19:12:12",53,"нетс у меня есть свои.\n*убираю брусок на место*",106079,null],[106082,"2026-07-10T19:13:34",11,"— Таки что? Мы идём как дельцы, а ты как рабочий?",101220,null],[106083,"2026-07-10T19:13:42",5,"— Я готов",101220,null],[106084,"2026-07-10T19:13:45",53,"*киваю*",106082,null],[106085,"2026-07-10T19:15:16",53,"*слегка мараю кожу и ождужду, так что бы быть больше похожим на рабочего и говорю усталым голосом относительно похожим на голоса рабочих в моем представлении*\n\nя тоже готов.",106083,null],[106086,"2026-07-10T19:15:43",11,"— Твое письмо не обычное, это иллюзорный скрипт, поглядывай на него периодически. Так у нас будет связь пусть и односторонняя.. так же я могла бы дать тебе своего фамильяра..",101220,null],[106087,"2026-07-10T19:16:07",5,"— Письмо? *дракон полез в карман, но ничего не нашел*",106086,null],[106088,"2026-07-10T19:16:23",11,"// Это Джонатану",101220,null],[106089,"2026-07-10T19:16:27",11,"// мы и так вместе",101220,null],[106090,"2026-07-10T19:16:31",53,"наврядли она останется незамеченной. \nили же она умеет скрыватся?",106086,null],[106091,"2026-07-10T19:16:45",5,"// да, но теперь дракон понял что записки нет",106089,null],[106092,"2026-07-10T19:17:27",11,"— У тебя в сумке..?",106090,null],[106093,"2026-07-10T19:17:57",11,"— В случае чего я могу его отозвать, но назад потом так же не верну..",101220,null],[106094,"2026-07-10T19:18:27",53,"я смогу передать через него сообщение?",106093,null],[106095,"2026-07-10T19:20:46",11,"— Я могу видеть глазами фамильяра, но это будет тяжело реализовать если мы будем чем-то заняты..",101220,null],[106096,"2026-07-10T19:22:02",53,"если я дам фамильяру вещь, он сможет донести ее до вас?",106095,null],[106097,"2026-07-10T19:22:34",11,"*кивок*",106096,null],[106098,"2026-07-10T19:23:10",53,"хорошо, тогда если это не вызовет лишних сложностей, я бы не отказался от помощи фамильяра.",101220,null],[106099,"2026-07-10T19:25:06",11,"кошка девушка призывает дофига умного на вид филина который явно не в восторге от дневного света, но садится тебе на руку",101220,null],[106100,"2026-07-10T19:26:02",53,"*раскрываю мешок(не самое комфортное место но там темно) и приглошаеющим жестом указываю филину путь внутрь*",106099,null],[106101,"2026-07-10T19:26:35",11,"Птица явно недовольна, но лезет",101220,null],[106102,"2026-07-10T19:27:08",5,"— Несешь им птицу в мешке",101220,null],[106103,"2026-07-10T19:27:10",53,"*закрыв мешок вешаю его на место и жду остальных*",101220,null],[106104,"2026-07-10T19:27:24",11,"— Осторожнее с ним, у него всего 1 хит..",101220,null],[106105,"2026-07-10T19:27:46",53,"мощьно//",106104,null],[106106,"2026-07-10T19:28:21",5,"— Да, я готов",106103,null],[106107,"2026-07-10T19:28:33",53,"понял.",106104,null],[106108,"2026-07-10T19:28:40",53,"я тоже.",106106,null],[106109,"2026-07-10T19:28:48",11,"— Идём ко входу? Отдельно я полагаю?",101220,null],[106110,"2026-07-10T19:29:13",53,"*киваю и иду чуть в стороне от них с небольшим запозданием*",106109,null],[106111,"2026-07-10T19:29:49",11,"— Пошли, Барминир из клана Телирон",101220,null],[106112,"2026-07-10T19:30:24",5,"Гвиндшарх идёт развалистой походкой, с гордо поднятой головой. На нём отилчно сидит костюм, а на пальце заметное кольцо",101220,null],[106113,"2026-07-10T19:31:19",53,"*спина легка присгорюлена, я стараюсь не выделятся и рассматриваю что делают другие рабочие которых я могу видеть*",106110,null],[106114,"2026-07-10T19:32:18",11,"Луна Мэри держит сумку деловой чемодан и следует за драконорожденным",106112,null],[106115,"2026-07-10T19:34:53",11,"Как только Гвинди и Луна проходят внутрь два стражника подходят к ним. Очевидно внешний вид путников совсем не напоминал обычных работяг, о целях визита иных на склад принято было спрашивать",101220,null],[106116,"2026-07-10T19:35:33",5,"— Барминир из клана Телирон. И моя ассистентка Мэри.",101220,null],[106117,"2026-07-10T19:35:58",11,"— По какому делу здесь, сэр Барминир?",101220,null],[106118,"2026-07-10T19:36:29",53,"*видя что стражники зажержали мэри и барминира прохожу неподалеку на склад, так будто я каждый день здесь нахожусь и вообще работа не ждет, время раблтать работу*",101220,null],[106119,"2026-07-10T19:36:31",5,"*дракон напряженно думает, зачем дельцы посещают склады*",101220,null],[106120,"2026-07-10T19:37:14",11,"Безмятежный и простой вид Джонатана напротив никого не смутил и он спокойно прошёл внутрь",106118,null],[106121,"2026-07-10T19:40:13",53,"*спокойно пройдя внутрь продолжаю так же спокойно идти и искать путь в менее доступные для мимопроходящих людей зоны, но в которые могут попасть рабочие. там ищу места где можно поработать или же поимитировать работу, а так же ищу что либо что покажется мне интересным. (ну и естественно прислушиваюсь к звукам дабы обнаружить угрозы и разговоры. авось повезет и услвшу чегось об артефакте)*",106120,null],[106122,"2026-07-10T19:41:23",11,"Вокруг тебя только огромные стеллажи на которых множество коробок, большинство из которых запечатаны \n\n// Жду заявки Гвинди сперва",101220,null],[106123,"2026-07-10T19:42:05",5,"— Пришёл досмотреть прибывший товар",101220,null],[106124,"2026-07-10T19:46:34",11,"// слабовато, больше деталей",101220,null],[106125,"2026-07-10T19:46:57",5,"// я не знаю, зачем они приходят, поэтому и думал",106119,null],[106126,"2026-07-10T19:47:28",11,"Стражник вопросительно продолжает смотреть на тебя \n\n— У нас тут много товаров ходит, какой вам нужен?",101220,null],[106127,"2026-07-10T19:47:48",11,"// импровизируй, причина норм, но подробностей мало",101220,null],[106128,"2026-07-10T19:48:08",11,"// там так же есть кабинеты для того что бы сделки подписывать так что варианты есть",101220,null],[106129,"2026-07-10T19:49:07",53,"//а ведь если бы не моя миссия можно было бы спиздить артефакт себе 🤔 но цель превыше всего 😁",101220,null],[106130,"2026-07-10T19:49:35",11,"// ты даже не знаешь что за арт, но можешь) никто не запрещает",106129,null],[106131,"2026-07-10T19:50:04",5,"— Охотничье снаряжение. Для крупной дичи",106126,null],[106132,"2026-07-10T19:50:24",53,"//могу но не буду. как уже сказал, цель привыше всего. а я здесь ради кошкожены. она такому точно не обрадуется.",106130,null],[106133,"2026-07-10T19:51:15",11,"// кидай убеждение",106131,null],[106134,"2026-07-10T19:51:21",11,"// или обман",101220,null],[106135,"2026-07-10T19:51:34",5,"/r +0 убеждение",101220,null],[106137,"2026-07-10T19:54:24",11,"Охранник смотрит на тебя с подозрением, костюмы конечно выглядят дорого, но как-то не складно ты стелишь",101220,null],[106138,"2026-07-10T19:54:43",11,"// давай ещё попробуй, я помочь могу конечно, но так же не интересно",101220,null],[106139,"2026-07-10T19:55:04",11,"// я имею ввиду объясниться продолжить",101220,null],[106140,"2026-07-10T19:57:37",5,"— Мой товар задерживается. Должен был прибыть неделю назад. Но его нет, и я решил лично разобраться, не потеряли ли его",101220,null],[106141,"2026-07-10T19:57:46",53,"//та все тут ясно. китобои-браконьеры. на крюк таких повесить и дело с концами",106137,null],[106142,"2026-07-10T19:58:01",53,"//(юмор)",106141,null],[106143,"2026-07-10T19:58:24",53,"//хуевый я юморист",106142,null],[106144,"2026-07-10T20:00:52",11,"— Я слышала сегодня как раз прибыл корабль с охотничьим снаряжением, вот пришли разбираться",106140,null],[106145,"2026-07-10T20:00:55",11,"// давай с помощью",101220,null],[106148,"2026-07-10T20:04:58",11,"— Да был сегодня корабль, с снастями ли я не знаю, не положено, но могу проводить к заведующему складом, если с ним не разберётесь то в кабинет главы гильдии — он вздохнул чувствуя проблемы",101220,null],[106149,"2026-07-10T20:05:46",5,"— Да, пожалуйста",106148,null],[106150,"2026-07-10T20:07:45",11,"Из примечательного здесь Джонатан видит только лестницу вниз и на верх. Рядом с ступеньками выход на улицу, видимо оттуда принимают корабли.",101220,null],[106151,"2026-07-10T20:08:27",11,"// готовься врать много.. надо было по скрытности идти раз не готов был к такому)",106149,null],[106152,"2026-07-10T20:08:29",44,"// вообще нахуя добоалять ноль ,",106147,null],[106153,"2026-07-10T20:08:57",5,"// я не понимаю ситуацию, мне нужна помощь за проницательность или анализ",106151,null],[106154,"2026-07-10T20:09:33",11,"// ну кидай проницательность, но объясни что ты хочешь понять",101220,null],[106155,"2026-07-10T20:09:50",5,"// уже прошли дальше",101220,null],[106156,"2026-07-10T20:10:32",11,"Вы все вошли внутрь склада. Гвинди и Луну стражник ведёт к мастеру смены разбираться с не прибывшим кораблём, а Джонатан спокойно сам решает куда пойти (пока что)",101220,null],[106157,"2026-07-10T20:10:36",53,"*пробую пройти вниз по лестнице*",106150,null],[106158,"2026-07-10T20:11:10",5,"— Где этот ваш мастер сидит?",106156,null],[106159,"2026-07-10T20:12:31",5,"*смотрю по сторонам, что там на полках лежит*",101220,null],[106160,"2026-07-10T20:13:35",11,"— Он либо на пирсе ведёт учёт, либо в своем кабинете на втором этаже — стражник задумался ненадолго куда вас сперва вести",101220,null],[106161,"2026-07-10T20:13:49",11,"// ну тут можно восприятие/проницательность",106159,null],[106162,"2026-07-10T20:14:31",5,"/r +4 восприятие",106161,null],[106164,"2026-07-10T20:16:12",11,"Рядом снуют люди и Джонатан быстро теряешь из виду говорящих со стражником спутников. По пути к лестнице он видит как снизу подымается громила не особо похожий на работника или стражника",106157,null],[106165,"2026-07-10T20:17:59",53,"*найдя ближайшее место где можно относительно хорошо имитировать работу начинаю делать именно это и дожидасюь пока громила пройдет, слушая о чем он будет говорить(если будет)*",106164,null],[106166,"2026-07-10T20:19:34",11,"Пока стражник задумался у тебя было время осмотреть ближайший стеллаж. Ящики, ящики и ещё ящики. Работяги ставят их на стеллажи и забирают. На самих ящиках ты замечаешь надписи, разглядеть удается парочку: \"хрупкий товар\" и \"жидкости\"",106163,null],[106167,"2026-07-10T20:20:18",5,"— Идём в кабинет, мне требуется нормальное место для разговора",106166,null],[106168,"2026-07-10T20:20:46",11,"Следом выходит ещё один и что-то говорит предыдущему вслед, но здесь довольно шумно..\n\n// Тоже кидай:3",106165,null],[106170,"2026-07-10T20:22:01",11,"— Надеюсь он будет там, тогда вам на второй этаж — он кивает своему напарнику что бы тот оставался у входа, а сам указывает вам на лестницу вверх. Гвинди и Луна так же видят громилу что опирается на лестницу",106167,null],[106173,"2026-07-10T20:24:03",5,"— Что за люди у вас тут ходят? Что это за вид?",106170,null],[106174,"2026-07-10T20:24:10",5,"// стражнику",101220,null],[106175,"2026-07-10T20:24:58",11,"— Возьми ещё Эля по дороге обратно, все равно нам ещё долго здесь сидеть! — говорит тот что поднялся последним \n\nСтражник тоже услышав это вопросительно приподнимает бровь",101220,null],[106176,"2026-07-10T20:25:19",53,"//ну вроде неплохо :3",106169,null],[106177,"2026-07-10T20:26:25",11,"Джонатан слышит разговор и вспоминает как Луна предупреждала про нанятых головорезов. Судя по разговору внизу есть ещё и идти туда без плана не стоит",106176,null],[106178,"2026-07-10T20:27:24",11,"— Ну чего мы тут без дела сидим, не смотри на меня так\n\n— Вам за это деньги платят — стражник подымается по лестнице вверх приглашая за собой \"дельцов\"",106175,null],[106179,"2026-07-10T20:27:36",53,"*пытаюсь понять, если я направлю туда на разведку птичку, какие у нее будут шансы*",106177,null],[106181,"2026-07-10T20:27:53",11,"— Наняли этих бездельников.. сидят прохлаждаются ещё и не довольны, мы в отличие от них вынуждены работать, но получаем поровну.. — недовольно ворчит стражник",101220,null],[106182,"2026-07-10T20:28:20",5,"— Зачем они тут нужны тогда?",106181,null],[106183,"2026-07-10T20:28:24",11,"// птица не говорит, а кошка сейчас слишком занята что бы стоять втыкать и следить глазами птицы",106179,null],[106184,"2026-07-10T20:28:37",11,"// да и ее заметят слишком людно тут днём",101220,null],[106185,"2026-07-10T20:29:45",5,"Дракон ворчит и идёт за стражником",101220,null],[106186,"2026-07-10T20:29:45",11,"— Нанял их Глава после того как день назад груз один привезли.. но это не ваше дело",106182,null],[106187,"2026-07-10T20:29:54",53,"вот я как раз об этом//\n\n\n\n\n*продолжаю осмотр помещения и прибиваюсь к группе рабочих что подальше от входа*",106184,null],[106189,"2026-07-10T20:30:39",5,"— Да мне не интересно, что за грузы у вас там. Главное, чтобы эти обалдуи моё не растащили. За такими следить надо, я тебе скажу",106186,null],[106190,"2026-07-10T20:31:36",11,"Оглядывая весь первый этаж ты не видишь ничего важного кроме ещё кучи стеллажей с товарами, среди которых безусловно есть полезные вещи, но днём здесь слишком людно что бы шариться в них",101220,null],[106191,"2026-07-10T20:31:44",11,"// тебе",106187,null],[106192,"2026-07-10T20:33:11",11,"— Я согласен, нашли кому доверять.. впрочем, кто же меня слушать будет — он поддержал твое ворчание — вот пришли \n\nВы стоите у двери кабинета на втором этаже",106189,null],[106193,"2026-07-10T20:33:51",11,"// ща карту",101220,null],[106194,"2026-07-10T20:34:10",5,"Гвиндшарх оглянулся вокруг, ищет укромные уголки, чтобы спрятаться в случае проблем. А затем решительно стучит в дверь.",101220,null],[106195,"2026-07-10T20:35:07",11,"// так извините мне надо отойти на минут 10, потом вернусь карту кину",101220,null],[106196,"2026-07-10T20:38:41",53,"что рабочие в целом делают?//",106190,null],[106198,"2026-07-10T20:49:25",11,"Стражник провел Гвинди и Луну по второму этажу. Здесь прекрасно видно что происходит внизу и на противоположной стороне. Ничего примечательного кроме закрытой двери кабинета к которому вас привели.",101220,null],[106199,"2026-07-10T20:54:15",11,"Многие суетятся, но ты присоединился к группе которая явно отлынивала от дел и что-то бурно обсуждала при этом:\n\n— Нам и так платят меньше чем стражникам, хотя работаем мы больше, а тут эти лентяи — возмущенно говорит один \n\n— Вот-вот, они ещё и эль с дварфийских поставок таскают! А как только мастер проверит боченки и найдет пустые виноваты будем мы! — добавляет второй",106196,null],[106200,"2026-07-10T20:56:13",53,"*продолжаю слушать*",106199,null],[106201,"2026-07-10T20:57:51",11,"— Так и что мы сделаем с этим, вы их видели? Скажешь слово против зубы выбьет — отвечает третий",101220,null],[106202,"2026-07-10T20:59:44",11,"Запал других после этих слов тоже начал угасать, очевидно что никто не хочет спорить с нанятыми главой головорезами",101220,null],[106203,"2026-07-10T20:59:47",5,"*тук тук тук*",106198,null],[106204,"2026-07-10T21:01:15",11,"*ответа нет*",101220,null],[106205,"2026-07-10T21:01:30",53,"даа... вот сейчас один из этих вышел, видели какой довольный шел? какого черта они вообще там внизу сидят? \n*голос крайне возмущенный*",106201,null],[106206,"2026-07-10T21:02:58",11,"— Начальник, это Сеймур! Тут к вам какие-то купцы по делу просятся — говорит стражник \n\n— Чего орёшь? Вышел он — отвечает ему другой что стоит на противоположной стороне этажа — и там внизу мужики от работы отлынивают, не надо ли тебе об этом побеспокоиться?",101220,null],[106207,"2026-07-10T21:03:19",53,"а мы тут горбатимся, спины надрываем.",106205,null],[106208,"2026-07-10T21:03:37",11,"Первый мужик смотрит на тебя \n\n— А ты кто собственно? Первый раз тебя вижу",106205,null],[106209,"2026-07-10T21:05:06",53,"так томас я. уже недели две тут батрачу. не пересекались видимо.",106208,null],[106210,"2026-07-10T21:05:09",5,"— Мы подождем в кабинете. — не терпящим возражений голосом сказал дракон",106206,null],[106211,"2026-07-10T21:05:21",53,"хотя черт его знает как. а вы сами то давно тут?",106209,null],[106213,"2026-07-10T21:05:36",11,"— Да иду я.. — Сеймур крикнул в ответ коллеге и закатил глаза — ждите здесь, мастер скоро придёт",106206,null],[106214,"2026-07-10T21:05:49",11,"// угроза убеждение?",106210,null],[106215,"2026-07-10T21:07:23",11,"— Мы все тут старички, только Реймонд — они указали на самого молодого и тихого — недавно устроился, но его то мы знаем, а тебя две недели не видели?",106211,null],[106216,"2026-07-10T21:08:13",5,"/r +2 угроза",106214,null],[106220,"2026-07-10T21:09:10",11,"Стоя на втором этаже Луна и Гвиндшарх первые услышали нарастающий стук капель дождя по потолку, а затем и до Джонатана доноситься гром. Началась гроза",101220,null],[106222,"2026-07-10T21:10:11",11,"— Что мы тут стоять ждать будем? Ваш глава строгий мужчина, явно будет недоволен если потеряет таких клиентов как мы — добавила Луна",106217,null],[106223,"2026-07-10T21:10:23",11,"/r d20",101220,null],[106225,"2026-07-10T21:11:28",53,"да видать не примечали просто. я как видишь не такой уж сильный. тяжеловаты для меня местные грузы. да вот сестра со дня на день помереть грозится.\nеще и гроза эта. но ничего. скоро насобираю ей на дохтура. он говорит из далека приехал да знает лекарства хорошие от болезни той. но глядишь не успею скопить.\n\n*приуныл и принялся за работу с мыслями о больно сестре*\n\nладно, бывайте, мужики. мне работать надобно.",106215,null],[106226,"2026-07-10T21:11:52",11,"Стелила девушка сладко, но почему-то совсем не убедительно, Сеймур покачал головой и настоял на том что бы вы ждали здесь. Впрочем его коллега из-за дождя разговора вашего не слышал, а сам Сеймур пошёл делать свою работу",101220,null],[106227,"2026-07-10T21:13:27",53,"//две недели тут работаю. ражи исцеления сестры у дохтура из далека. если и припезднул то самую капельку :3",106225,null],[106228,"2026-07-10T21:14:07",11,"Мужики подуспокоились и провели тебя сочувственным взглядом \n\n— Во дела, даже молодёжь в наши времена так вкалывать должна.. — продолжили они причитать. \n\nСпустя короткое время вниз спускается Сеймур и идёт отчитывать и разгонять этих бездельников",106225,null],[106230,"2026-07-10T21:15:10",5,"Как только Сеймур отошёл, дракон расчехлил отмычки и приступил к убеждению двери",106226,null],[106231,"2026-07-10T21:15:11",53,"*работая вслущиваясь в разговоры*",106228,null],[106232,"2026-07-10T21:16:02",53,"//хоть кто то из рабочих спускается вниз?",101220,null],[106233,"2026-07-10T21:16:29",5,"/r +6 убеждаю дверь?",101220,null],[106235,"2026-07-10T21:17:12",5,"— Постой на страже, Луна. Я быстро гляну, что внутри",101220,null],[106236,"2026-07-10T21:17:17",11,"Дверь убеждается успешно, правда стражник на той стороне может не убедиться не идти проверять что ты делаешь, так что давай скрытность",101220,null],[106237,"2026-07-10T21:17:19",9,"//Какая убедительная дверь ❤️",101220,null],[106238,"2026-07-10T21:17:40",5,"/r +6 какой стражник",101220,null],[106240,"2026-07-10T21:19:11",11,"Внимание стражника привлекло то что ты делал подозрительные действия с дверью и он направляется к вам проверить что происходит",101220,null],[106241,"2026-07-10T21:19:22",53,"*смотрю насколько много людей ходит на верх*",106232,null],[106243,"2026-07-10T21:19:47",5,"//Сеймура? Или какой стражник нас увидел?",106240,null],[106245,"2026-07-10T21:19:55",11,"// ни в верх, ни в низ пока никто не идёт. Только стражник спустился, мы поднялись, а вниз вернулись оба головореза",106241,null],[106247,"2026-07-10T21:20:16",11,"// тут на втором этаже другой стражник",106243,null],[106248,"2026-07-10T21:20:23",5,"// окак",106247,null],[106251,"2026-07-10T21:21:21",11,"— Что ты смотришь, сделай вид что ничего не трогал и отмычку убери — Луна прикрывает тебя собой",101220,null],[106252,"2026-07-10T21:21:41",11,"— Впрочем он тут сейчас всего один — цедит девушка сквозь зубы",101220,null],[106255,"2026-07-10T21:22:21",5,"Гвинди быстро убирает отмычку в жилетку, а сам стоит с видом, будто поправлял галстук",101220,null],[106260,"2026-07-10T21:23:16",11,"// снова скрытность давай",101220,null],[106263,"2026-07-10T21:23:25",53,"*высматриваю людей которые выглядят как начальственные лица или стражники и стараюсь запомнить их голоса в процессе работы*",106245,null],[106264,"2026-07-10T21:23:26",11,"Стражник смотрит на вас, затем на дверь и снова на вас",101220,null],[106265,"2026-07-10T21:23:31",5,"/r +6",101220,null],[106269,"2026-07-10T21:24:16",11,"— Ждите мастера смирно, я буду следить за вами — кажется он успокоился и отошёл, но теперь будет следить бдительнее",106266,null],[106270,"2026-07-10T21:24:27",53,"//щас блэт смену отработаю, женях получу а потом настанет время задуматся по причине: так блэт, что то злесь не так.. а зачем мы сюда призодили?",101220,null],[106271,"2026-07-10T21:24:55",11,"// давай заявку эл, если что помогу",101220,null],[106272,"2026-07-10T21:25:23",5,"— Надо его отвлечь!\n\nДракон подходит к краю и смотрит вниз, ища взглядом Джона",101220,null],[106276,"2026-07-10T21:27:26",11,"— Чего встали здесь без дела? — говорит Сеймур внизу бездельникам. Гвинди видит, но не слышит разговор \n\n— Дак обсуждаем головорезов этих, Сеймур, ну ты же давно нас знаешь, врать не будем, вон Роберт говорит — на этих словах Роберт, тот который жаловался на это ранее, кивает — что они эль казённый распивают",101220,null],[106277,"2026-07-10T21:27:45",11,"Сеймур задумался",101220,null],[106278,"2026-07-10T21:27:53",11,"// Джонатан слышит и может вмешаться:3",101220,null],[106279,"2026-07-10T21:28:30",11,"Роберту Сеймур верил, но всего один свидетель.. да и лень ещё идти эль проверять, а потом и мастеру жаловаться..",101220,null],[106280,"2026-07-10T21:29:33",11,"— Помощь нужна? — девушка встала позади тебя и тихо сказала — Я могу создать иллюзию нас двоих что бы мы настоящие зашли в дверь",106272,null],[106281,"2026-07-10T21:29:39",53,"*подхожу чуть ближе к ним и запоминаю голос сеймура*\nвот вот. сидят, ничего не делают, да хлещут козеное. \nа что нам работягам делать с этим?",106278,null],[106282,"2026-07-10T21:29:53",11,"// я надеялась что ты сам вспомнишь я же говорила про то что могу иллюзию создавать:(",101220,null],[106283,"2026-07-10T21:30:25",11,"— А ты сам то это видел?",106281,null],[106290,"2026-07-10T21:32:59",5,"// не помню. Мой перс видел?",106282,null],[106292,"2026-07-10T21:33:14",53,"да видал раз когда проходил у лесницы. \nда и даже так видно ж по ним. \n\nи не думаю что это один только был. \n\n\n//извиняюсь что медленно и нескладно.\nя хаваю горелую курицу со вчерашним пловом. тяжело писать одной рукой",106283,null],[106294,"2026-07-10T21:33:32",11,"// приятного",101220,null],[106295,"2026-07-10T21:33:33",5,"— Да, давай",106280,null],[106298,"2026-07-10T21:33:47",53,"спасиьо//",106294,null],[106301,"2026-07-10T21:34:52",11,"— Раз две жалобы уже.. надо бы что-то с этим делать — Сеймур устало помассировал брови — И что прикажете делать? Мастеру жаловаться или самому к ним спуститься?",101220,null],[106307,"2026-07-10T21:36:57",11,"Луна смотрит сквозь окна на потолке\n\n— Ждём момента — говорит она — а затем сразу следуй за мной\n\nВ момент когда гроза бьёт особенно ярко кошка юрко проскальзывает во взломанную дверь создавая иллюзию",106295,null],[106308,"2026-07-10T21:37:20",53,"*ожидаю ответа от более опытной морды*",106301,null],[106309,"2026-07-10T21:37:32",11,"// не, тут ты решаешь)",101220,null],[106312,"2026-07-10T21:37:59",53,"//на кого ж вы выбор оставили :D",101220,null],[106313,"2026-07-10T21:38:03",5,"*зашёл следом*",106307,null],[106315,"2026-07-10T21:38:19",11,"Мужики посовещались и высказали свое мнение Сеймуру, их четверо, голоса разделились поровну. Все смотрят на \"Томаса\" ожидая его ответа",101220,null],[106318,"2026-07-10T21:39:08",53,"*заметив разделение решаю высказатся за спуск*\nу начальника небось дел полно, а эти там неизвестно чего еще сотворить успеют.",106309,null],[106325,"2026-07-10T21:40:57",11,"Гвиндшарх и Луна попадают в кабинет Мастера. Рабочий стол, стол для гостей. Окно для осмотра происходящего на втором и первом этаже, а так же два окна наружу. Позади стола мастера две тумбочки, в самом столе тоже есть шухлядки",101220,null],[106333,"2026-07-10T21:42:40",5,"Подхожу и смотрю записи на рабочем столе",101220,null],[106334,"2026-07-10T21:42:58",11,"— Хорошо, мужики, я вас услышал. Вы меня не обессудьте, но давайте сперва проверим боченки, а затем пойдем к тем громилам? Что бы я не зря шум подымал — после слов стражника мужики недовольно заворчали, но возмущаться не стали и вся компания двинулась к полкам с горячительными напитками",106318,null],[106336,"2026-07-10T21:43:44",11,"// проницательность",101220,null],[106347,"2026-07-10T21:46:27",53,"оке//",106336,null],[106349,"2026-07-10T21:46:48",11,"// не ты",101220,null],[106351,"2026-07-10T21:46:54",53,"оке//",106349,null],[106352,"2026-07-10T21:47:00",11,"// давай",106333,null],[106354,"2026-07-10T21:47:05",5,"/r +4",101220,null],[106365,"2026-07-10T21:50:14",11,"\"Журнал учёта товаров\" \"Журнал поставок\" две книги лежат на столе, остальные бумажки здесь из того же разряда. Бегая глазами по тексту на всеобщем языке твои глаза не цепляются за что-то примечательное, только \"охотничьи снасти для крупной дичи\"",101220,null],[106366,"2026-07-10T21:50:49",5,"Открываю журнал поставок и ищу записи за последние дни. А именно необычную поставку",101220,null],[106368,"2026-07-10T21:51:17",11,"Луна тем временем поглядывает в окно что бы убедиться что никто не идёт",101220,null],[106371,"2026-07-10T21:52:04",11,"*Пара листов за вчерашний день вырваны*",106366,null],[106373,"2026-07-10T21:52:19",11,"— Никто не будет хранить важное в открытом месте",101220,null],[106374,"2026-07-10T21:52:22",53,"* в момент когда лишниз глаз не будет гляжу в письмо с печальным видом, после убирая его обратно*",101220,null],[106375,"2026-07-10T21:52:28",5,"— Так и запишем, контрабанда!",101220,null],[106376,"2026-07-10T21:53:06",5,"Открываю тумбочки и ящики и очень бегло просматриваю",101220,null],[106381,"2026-07-10T21:54:39",11,"Одна тумбочка закрыта на замок",106376,null],[106383,"2026-07-10T21:54:48",11,"Остальные открываются",101220,null],[106384,"2026-07-10T21:55:21",11,"// давай с помощью снова внимательность",101220,null],[106386,"2026-07-10T21:55:40",5,"/r +4",101220,null],[106388,"2026-07-10T21:55:56",11,"// если я говорю с помощью кидай сразу +д20",101220,null],[106390,"2026-07-10T21:56:10",53,"//не изменилось? :3",106374,null],[106391,"2026-07-10T21:56:19",11,"// да щас он найдет",101220,null],[106392,"2026-07-10T21:56:40",11,"Между старых книг учёта ты находишь карту здания",106389,null],[106393,"2026-07-10T21:57:15",5,"Отдаю карту Луне, а сам достаю отмычки, и приступаю к запертой тумбочке",101220,null],[106394,"2026-07-10T21:57:20",53,"меня пиздец смущает этот проход на карте//",106198,null],[106395,"2026-07-10T21:57:26",11,"В целом все то же что вы видели, но ещё и подвал",101220,null],[106396,"2026-07-10T21:58:02",53,"//но перс о нем ни слухом ни духом",106394,null],[106397,"2026-07-10T21:58:10",5,"— Ладно, всё понятно.\n\n*Взял карту и положил ровно на то же место, где она была*",106395,null],[106398,"2026-07-10T21:58:28",11,"А на верху ничего и неть:3",101220,null],[106399,"2026-07-10T21:59:15",11,"— Тебя ничего не смущает? — ты даже не заметил как девушка появилась позади тебя и рассматривала карту вместе с тобой",106397,null],[106400,"2026-07-10T21:59:38",5,"// я сразу ей отдал, сам не смотрел",106399,null],[106401,"2026-07-10T22:00:10",53,"//там ни ничего нет, там КОРАБЛЬ 👁👁",106398,null],[106402,"2026-07-10T22:00:28",5,"— Тайный ход в подвале?",106399,null],[106405,"2026-07-10T22:00:56",11,"— Именно! Видно же что он спрятан за стеной",106402,null],[106406,"2026-07-10T22:01:07",11,"// нет поставь карту обратно и забей))",101220,null],[106408,"2026-07-10T22:02:17",11,"И именно об этом Луна пишет Джонатану",106402,null],[106410,"2026-07-10T22:02:38",53,"//я успеваю увидеть?",106408,null],[106411,"2026-07-10T22:03:05",5,"— Да, за стеной. Нам туда, я так думаю",106405,null],[106413,"2026-07-10T22:05:09",11,"Сеймур как раз проверил боченки и обнаружил пару пустых, возмущённо идёт вниз, по дороге встречая мокрого от дождя мастера который вел учёт с нового корабля и сейчас готовится возвращаться в свой кабинет",106410,null],[106414,"2026-07-10T22:06:03",11,"// что дальше делаем?",106411,null],[106416,"2026-07-10T22:07:29",53,"//мы всей пятеркой идем за ним?",106413,null],[106417,"2026-07-10T22:08:12",5,"// можно?",106393,null],[106418,"2026-07-10T22:08:33",11,"// а сори проскипала, да давай, но там сложно",101220,null],[106419,"2026-07-10T22:08:44",5,"/r +6",101220,null],[106423,"2026-07-10T22:08:51",11,"// ладно",101220,null],[106424,"2026-07-10T22:09:01",11,"// вот когда не надо оно норм бросок даёт)",101220,null],[106425,"2026-07-10T22:09:13",5,"// если не надо пусть не открывается",101220,null],[106427,"2026-07-10T22:09:28",11,"Замок вновь слишком легко поддается Гвиндшарху намекая ему о том что вот оно где было его призвание",101220,null],[106428,"2026-07-10T22:09:57",5,"*смотрю внутрь*",106427,null],[106433,"2026-07-10T22:10:59",11,"В закрытой тумбочке драконорожденный находит письма от главы гильдии разных дат, блокнот самого мастера и два скомканных листа бумаги",101220,null],[106435,"2026-07-10T22:11:32",5,"Беру листы бумаги и распрямляю",101220,null],[106450,"2026-07-10T22:18:28",11,"\" Лист датирован вчерашним днём\n\n\"Груз\" прибудет вечером. Глава гильдии готовится заранее, были наняты головорезы и ученик мага за *бух учёт расходов что очевидно влетел гильдии в копеечку*. Магу была оплачена услуга сигнализации на вскрытие тайного прохода *снова цены*, глава стражи был переведен на охрану \"груза\" с доплатой, его место временно занимает Сеймур, так же с доплатой\"\n\nДалее идут расчёты трат",101220,null],[106452,"2026-07-10T22:19:53",5,"Даю посмотреть Луне",106450,null],[106453,"2026-07-10T22:19:56",53,"//ожидаемо :3",106450,null],[106454,"2026-07-10T22:20:12",53,"//как знал что маг поставил сигналку :3",101220,null],[106457,"2026-07-10T22:20:39",5,"А Гвиндшарх хочет быстро глянуть последние записи в дневнике мастера",101220,null],[106459,"2026-07-10T22:21:06",11,"\" После прибытия \"груза\" глава охраны, ветеран Аарон жаловался на подозрительный интерес мага к \"грузу\", более подозрительных событий не было \"",101220,null],[106461,"2026-07-10T22:21:57",5,"Убираю дневник на место, сминаю бумажки и тоже кладу туда. Закрываю тумбочку. Все остальные тоже закрываю и поправляю как было",101220,null],[106462,"2026-07-10T22:22:36",11,"Луна конспектирует всё и передаёт Джонатану",101220,null],[106463,"2026-07-10T22:22:57",11,"— \"Груз\" внизу, теперь вопрос как туда попасть и вообще выбраться отсюда",101220,null],[106464,"2026-07-10T22:23:25",5,"— Сейчас надо выйти и заменить иллюзии на нас. Дальше будем думать",101220,null],[106465,"2026-07-10T22:24:04",11,"— Ты хочешь говорить с мастером? Он же точно нас раскроет, в отличие от стражника он знает какой груз и от кого приходит — ответила она",101220,null],[106466,"2026-07-10T22:26:06",53,"*джонатан тем временем идет за стражником вместе с рабочими*",106462,null],[106467,"2026-07-10T22:26:16",53,"//так и хочется сказать бундбля",106466,null],[106470,"2026-07-10T22:27:35",11,"Мастер смены строгий взрослый мужик выслушал работяг и стражника и устало вздохнул \n\n— Сеймур, они нам нужны, пока что, но передай им от меня что всё выпитое ими будет вычтено из их же зарплаты — покомандовал он стражнику, а затем обратился к работягам — а вы чего без дела тут шляетесь? Идите работайте, пожаловались и пошли\n\nМужики без возмущений начали расходиться довольные решением мастера",106416,null],[106472,"2026-07-10T22:28:19",5,"— Не хочу, но что ещё делать? Надо как-то попасть в подвал. *Вспомнил карту* Там есть вход через люк с улицы. Можно здесь выйти в окно и пойти через него.",106465,null],[106473,"2026-07-10T22:28:28",5,"// я пойду спать, извините что туплю",101220,null],[106474,"2026-07-10T22:29:12",53,"*такой же довольный киваю и иду работать*",106470,null],[106475,"2026-07-10T22:29:24",53,"//работа сама себя не отработает, уж звиняйте",106474,null],[106476,"2026-07-10T22:29:31",11,"// да давай, люка там нет, не вариант",106473,null],[106477,"2026-07-10T22:29:43",11,"// лады завтра тогда закончим",101220,null],[106478,"2026-07-10T22:29:45",53,"//бля, вжился в роль работяги",106475,null],[106480,"2026-07-10T22:30:00",53,"//спокойной ночи",106473,null],[106481,"2026-07-10T22:30:52",53,"//аура пиздобола (+7 на обман убеждение и выступление) работает отлично",101220,null],[106490,"2026-07-10T22:35:47",53,"//даже без бросков",106481,null],[106520,"2026-07-11T07:04:09",5,"// окей",106476,null],[106546,"2026-07-11T13:24:33",5,"Гвиндшарх выглядывает в окно в стороне выхода со склада и ищет возможность незаметно спрыгнуть",101220,null],[106547,"2026-07-11T13:34:48",5,"// Сергей ритуал призыва",101220,null],[106549,"2026-07-11T14:15:38",53,"//я тута",106547,null],[106595,"2026-07-11T14:32:56",11,"// на улицу?",106546,null],[106627,"2026-07-11T14:41:39",11,"// сижу тут слова подбираю текст пишу телега зависла перезапустила текста нет думайте",101220,null],[106629,"2026-07-11T14:41:53",5,"// ужасно(",101220,null],[106653,"2026-07-11T14:50:13",11,"Драконорожденный выглядывает в окно, прямо под ним находится маленький \"бортик\" второго этажа, а из-за угла виднеются ручки телеги.\n\nДвор склада пуст, работяги попрятались от непогоды в здание и занимаются более уместной для такой погоды работой. Из движений на улице видна лишь подъезжающая карета, кони что везут сей транспорт не сильно торопятся идти, их глаза округлились, а уши прижались к затылку, возчик сердито бьёт их поводьями подгоняя.",106546,null],[106663,"2026-07-11T14:52:49",5,"// куда смотрит возчик?",106653,null],[106667,"2026-07-11T14:53:37",11,"// хочешь что-то узнать пиши что и давай проверку подходящую",106663,null],[106668,"2026-07-11T14:54:00",5,"/r +4 анализ думаю как незаметно для возчика спрыгнуть",101220,null],[106679,"2026-07-11T14:56:32",11,"Гвиндшарх видит что возчик слишком занят неуправляемыми животными, ещё и гроза — его внимание будет тяжело привлечь если только ты не плюхнешься плашмя вниз. Впрочем, ты внезапно вспоминаешь что хоть Сеймур и ушёл, но его коллега по смене остался сторожить у входа и в отсутствии людей на улице заметить тебя ему не составит труда, если конечно его перед этим не отвлечь.",101220,null],[106682,"2026-07-11T14:56:55",11,"// Сергей ты где там?",101220,null],[106689,"2026-07-11T14:58:19",5,"— Луна? Ты можешь создать иллюзию на улице? Или какой-нибудь звук! Чтобы стражник в другую сторону посмотрел",101220,null],[106731,"2026-07-11T15:04:35",11,"— Хм.. Например?",106689,null],[106735,"2026-07-11T15:05:16",5,"— Крик о помощи в отдалении",106731,null],[106736,"2026-07-11T15:06:13",11,"— Ты же понимаешь что стражников на складе много, а этот занят на посту? — Луна немного задумалась — Звуки так же глушит гроза",101220,null],[106737,"2026-07-11T15:06:49",11,"// вообще вариантов у вас три есть уже",101220,null],[106738,"2026-07-11T15:07:00",11,"// ну твой на самом деле тоже рабочий, но оформить надо",101220,null],[106740,"2026-07-11T15:07:20",53,"//таки переписали вузы. я принял участие. я снова тута.",106682,null],[106741,"2026-07-11T15:07:32",5,"// я глупый и не знаю варианты",106737,null],[106742,"2026-07-11T15:08:05",53,"//что я успел пропустить?",101220,null],[106744,"2026-07-11T15:08:21",11,"— Джонатан может нам помочь если его попросить, но мне нужен план — добавляет девушка",101220,null],[106746,"2026-07-11T15:08:34",11,"// пока Гвинди думает о плане, ты не с нами так что не поможешь",106742,null],[106748,"2026-07-11T15:09:02",53,"//а я роботою на складе в это время похоже :3",101220,null],[106749,"2026-07-11T15:09:28",53,"//могу прокинуть на внимательность дабы выяснить что нибудь за это время?",106748,null],[106750,"2026-07-11T15:09:46",5,"— Тогда он не пойдёт за нами, даже если заметит. Мы отбежим и дождёмся конца рабочего дня. Всё равно я не знаю, как проникнуть внутрь без переполоха. Тем более в подвал",106736,null],[106751,"2026-07-11T15:10:17",11,"Склад стал порядком теснее. Все местные работники собрались в здании из-за непогоды, теперь здесь довольно шумно, но так же и проще смешаться с толпой",106749,null],[106752,"2026-07-11T15:11:33",53,"*постепенно изучаю маркировку ящиков и продвигпюсь ближе к леснице*",106751,null],[106754,"2026-07-11T15:12:12",11,"// давай проницательность/восприятие",106752,null],[106762,"2026-07-11T15:21:12",11,"Джонатан понимает что каждая полка подписана, там есть надписи, возле тебя это: \"ткани и шкуры\", \"рабочие инструменты\" и на нижней полке: \"горючие материалы\", на некоторых ящиках написано \"опасно, держать подальше от огня\"",101220,null],[106770,"2026-07-11T15:25:05",53,"//а есть на этом складе отхожее место?",106762,null],[106773,"2026-07-11T15:25:36",11,"Луна подняла руку что бы что-то сказать, но сразу же отпустила",101220,null],[106774,"2026-07-11T15:26:08",11,"— Хорошо, как ты планируешь спускаться?",101220,null],[106776,"2026-07-11T15:26:26",53,"//а я тут какраз переполох планирую :D",106750,null],[106777,"2026-07-11T15:26:30",11,"// я сама себе в ногу выстрелила сказать что он так просто не отвлечется, но это не значит что нам можно привлекать внимание",101220,null],[106778,"2026-07-11T15:26:59",11,"// это был один из вариантов, но Гвинди про это не подумал так что и Луна тебе не пишет, но можешь импровизировать",106776,null],[106780,"2026-07-11T15:27:13",53,"// @Ashenchampion",106770,null],[106782,"2026-07-11T15:27:39",11,"// на улице",101220,null],[106783,"2026-07-11T15:28:27",5,"— Спрыгнуть. Тут невысоко.",106774,null],[106786,"2026-07-11T15:29:15",53,"*быстро иду туда. уже там дотсаю совушку и прошу ее передать мое сообщение быстро вырезангое на кусочке дерева луне*\n\n(сообщение: в подвале головорезы. я их отвлеку устроив небольшой переполох. у вас 5 минут до начала.)",106782,null],[106787,"2026-07-11T15:29:17",11,"// прочитай ещё..",106653,null],[106788,"2026-07-11T15:29:42",5,"// а да",106787,null],[106789,"2026-07-11T15:29:53",11,"// ахаха мне страшно, но давай))",106786,null],[106792,"2026-07-11T15:31:18",11,"/r d20",101220,null],[106795,"2026-07-11T15:32:21",11,"Птица вылетает из задней двери, не привлекая внимание стражей, но её видело достаточное количество рабочих которые явно не поняли что здесь забыла сова. Голуби и воробьи конечно залетали, но совы.. чудеса",101220,null],[106796,"2026-07-11T15:33:16",11,"Гвиндшарх видит знакомого филлина что летит к его окну",101220,null],[106798,"2026-07-11T15:33:31",5,"— О, твоя птица вернулась!",101220,null],[106802,"2026-07-11T15:33:38",11,"// окно открыто?",101220,null],[106804,"2026-07-11T15:33:51",5,"// мы выглянули, полагаб что да",101220,null],[106805,"2026-07-11T15:34:18",11,"Филин даёт тебе послание от Джонатана и возвращается к хозяйке",101220,null],[106807,"2026-07-11T15:34:56",11,"— Что-то случилось? — обеспокоенно звучит она",101220,null],[106808,"2026-07-11T15:35:06",53,"*после отправки сообщения возвращаюсь с видимым облегчением на лице и аккуратно в процессе работы складываю горбчие материалы и то что опасно подносить к огню в закутке склада подальше от спуска. смотрю что бы рядом было что то ценное при этом. сложив все это в нужном месте дожидаюсь истечения срока данного товарищам и аккуратно поджигаю ящик с горючими веществами используя целый коробок спичек и ухожу подальше. (все это лежит на полках, опасное лежит прямо на ящике с горючими веществами, рядом еще пара ящиков с ценными вещами. сам я после поджега скрываюсь в толпе)*",101220,null],[106809,"2026-07-11T15:35:11",5,"Дракон разворачивает записку и читает.\n\n— Хочет устроить переполох внизу. Через 5 минут.",101220,null],[106813,"2026-07-11T15:36:43",5,"— Полагаю, это будет удобный момент чтобы сбежать. Или чтобы пробраться в подвал! Но 5 минут... Надеюсь, мастер не успеет вернуться.\n\nГвинди смотрит в окно, выходящее на склад",101220,null],[106814,"2026-07-11T15:36:59",11,"// А говорил что масло не любишь..",106808,null],[106815,"2026-07-11T15:37:17",53,"//? да вроде не говорил такого",106814,null],[106816,"2026-07-11T15:37:53",53,"//просто часто отмечаю что вы пироманы :3  меня это устраивает",106815,null],[106817,"2026-07-11T15:38:02",11,"// скрытность теперь давай, посмотрим как никто не заметил твоих действий))",101220,null],[106818,"2026-07-11T15:38:19",11,"// ты щас тем же занимаешься))",106816,null],[106821,"2026-07-11T15:38:32",53,"//надо было закрепить лист в твоем лс..",106818,null],[106845,"2026-07-11T15:41:31",11,"Удивительно как никто не обратил внимание на наглую рыжую морду что таскал \"опасные ящики\", а затем поджигал. Кажется ты слишком хорошо влился в роль рабочего и твоя уверенность в твоих действиях заставила верить и окружающих. Прирожденный артист. Тебе удаётся уйти назначенным..",101220,null],[106846,"2026-07-11T15:41:50",11,"Куда идёшь?",101220,null],[106853,"2026-07-11T15:42:51",53,"//при попытках кем то притворится я кидаю с модификатором +7 и с преимуществом :3",106845,null],[106857,"2026-07-11T15:43:24",53,"//хуевый из меня вор. зато артист от бога",101220,null],[106860,"2026-07-11T15:44:17",53,"*сливаюсь с толпой и ухожу подальше от места происшествия. когда начнется переполох буду всеми силами помогать остальным решить проблему с нехилым матом в процессе и паникой в глазах*",106846,null],[106863,"2026-07-11T15:44:45",53,"//мне сестру надо лечить и кормить. вы там ахуели склад где я работаю поджигать?",106860,null],[106866,"2026-07-11T15:45:01",11,"Тем временем тканевые мешки быстро загораются, а затем, медленно, но верно, начинают гореть деревянные ящики. Запах дыма быстро учуяла местная бабуля-уборщица и тут же начала сзывать окружающих на помощь",101220,null],[106868,"2026-07-11T15:46:04",5,"Дракон внимательно следит за положением стражи из окна",101220,null],[106877,"2026-07-11T15:47:26",11,"— Чего вам, бабуля Матильда? — прозвучал знакомый голос одного из работяг что Джонатан видел ранее. Но не дожидаясь ответа он обнаружил поджёг и вскрикнул сам — пожар!",101220,null],[106880,"2026-07-11T15:48:45",11,"— Надеюсь он там себя не подставит и нас вместе с ним.. впрочем его помощь сейчас бы не помешала — ответила Луна",106813,null],[106887,"2026-07-11T15:49:42",11,"Ты слышишь голос из-за двери\n\n— Эй, там внизу пожар, спускайтесь, здесь не безопасно оставаться! — стражник услышал крики снизу и пришел сопроводить гостей в безопасное место. Жаль что иллюзии не умеют говорить",106868,null],[106888,"2026-07-11T15:49:59",5,"— Рргх, надеюсь, они потушат пожар. Я сюда пришёл не сжигать чужое имущество! Но переполохом воспользуемся",106880,null],[106889,"2026-07-11T15:50:09",53,"*обернувшись на голос проследил за его взглядом поворачиваюсь на пожар*\n\nпож... что?!\nпожар!? \n*взгляд метается то к пожару то к мужику, на лице выражение: блять что ж теперь будет? что делать? \n(в общем лицо полное растерянности и паники)*",106877,null],[106892,"2026-07-11T15:50:38",11,"\"На складе начался сущий кошмар\"",101220,null],[106895,"2026-07-11T15:51:08",5,"// стражник где стоит?",106887,null],[106897,"2026-07-11T15:51:25",11,"// он подходит к иллюзиям, ты не видишь, но голос слышится ближе",106895,null],[106898,"2026-07-11T15:51:56",5,"// там же окно в сторону склада есть",101220,null],[106900,"2026-07-11T15:52:21",11,"— Похоже у нас не так много времени, прежде чем он поймет что это всего лишь иллюзии.. и свяжет нас с пожаром скорее всего — Вздыхает кошка",101220,null],[106901,"2026-07-11T15:52:41",11,"// ну если ты смотрел то видишь, но ты же в другое окно смотрел",106898,null],[106902,"2026-07-11T15:52:59",5,"/",106813,null],[106905,"2026-07-11T15:53:52",11,"— Мы можем бежать, но стражник помнит как ты выглядишь и свяжет тебя с происшествием — Луна так же выглянула в окно — Здесь есть бортики по которым можно пройтись, а за углом телега в которую можно спрыгнуть",101220,null],[106906,"2026-07-11T15:54:03",11,"// не люблю повторяться..",101220,null],[106907,"2026-07-11T15:54:40",11,"— Мне то ничего, но тебя объявят в розыск пусть и не с настоящим именем",106905,null],[106909,"2026-07-11T15:56:15",11,"Девушка замялась, было заметно что она не хочет говорить об этом\n\n— У меня есть зелье что стирает память.. это может решить этот вопрос, но нам нужно его поймать сперва — алые глаза смотрели на Гвинди немного виновато",101220,null],[106911,"2026-07-11T15:58:41",5,"— Меня видел уже не один стражник. Всем память не сотрешь. Надо выходить на место иллюзий",106907,null],[106912,"2026-07-11T16:00:10",11,"Ящики постепенно начали разгораться. Температуры горения было достаточно что бы расплавить тонкие жестяные банки, масло из них полилось подпитывая огонь, что перешёл и на стены. \n\nСуета привлекла внимание Мастера что уже и забыл о том что бы подняться вверх и раздавал команды. Стражник у входа тоже покинул пост. Все рабочие руки были заняты тушением пожара",106892,null],[106913,"2026-07-11T16:01:19",5,"// можно мы выскочим на место иллюзий?",101220,null],[106914,"2026-07-11T16:01:40",11,"// если повезёт, давай скрытность",101220,null],[106916,"2026-07-11T16:02:19",11,"Луна недовольно шипит, но согласна следовать",101220,null],[106917,"2026-07-11T16:02:23",5,"/r +6",101220,null],[106922,"2026-07-11T16:03:00",11,"/r d20",101220,null],[106971,"2026-07-11T16:16:40",11,"// у меня жопа сгорела",101220,null],[106976,"2026-07-11T16:16:55",11,"// написала описание почти закончила и опять тоже самое и все исчезло 😡",101220,null],[106984,"2026-07-11T16:18:16",53,"//биля, помню эту боль.",106976,null],[107007,"2026-07-11T16:23:24",11,"Бесновался глухой, непроглядный ливень. Промокшее до нитки дерево снаружи держало оборону против огня: потоки воды моментально студили бревна, не давая пожару вырваться на свободу. \n\nОднако, внутри склада разворачивался рукотворный ад. В дальнем углу с треском разгорался пожар, начавшийся с чьей-то злой воли. Огонь жадно пожирал намеренно подожженные мешки и ящики. Тонкая древесина быстро обугливалась, открывая скрытое внутри — плотные ряды жестянок с горючим маслом. Под воздействием бешеного жара металл банок уже начинал зловеще деформироваться, а закипающее внутри масло не сулило ничего хорошего. \n\nПространство внутри здания заполнилось панической, хаотичной суетой. Люди бегали туда-сюда пытаясь потушить пожар, а снаружи мерцали желто-белые вспышки. Одна из которых послужила хорошую службу драконорожденному и табакси. На мгновенье, стражнику показалось что драконов стало двое, но после раската грома он снова видел лишь одного.",101220,null],[107008,"2026-07-11T16:23:33",11,"// все буду писать не в телеге сразу..",101220,null],[107026,"2026-07-11T16:25:50",5,"Дракон бежит к лестнице на первый этаж, увлекая за собой табакси.\n\n— Помогите! Где выход!?\n\nОн не останавливается, чтобы выслушать ответ, а бежит дальше.\n\nТелепатически:\n\"Луна, можешь передать Джону, чтобы шёл к подвалу? Мы идём туда, это лучший момент\"",101220,null],[107035,"2026-07-11T16:26:21",11,"// письмо ритуалом 11 минут,  ячейкой 1",101220,null],[107038,"2026-07-11T16:27:03",5,"Дракон бежит, по пути высматривая Джона внизу. Если тот окажется в зоне видимости, сразу передаёт телепатическое послание. \n\n// 30 футов дистанция",101220,null],[107039,"2026-07-11T16:27:14",11,"— Нет времени — отвечает она оглядываясь на растерянного стражника и следует за тобой",101220,null],[107042,"2026-07-11T16:29:16",11,"Недовольные и бдительные от того что не пьяные головорезы так же вышли тушить пожар ещё вместе с Сеймуром, внизу должно быть чисто",101220,null],[107049,"2026-07-11T16:30:27",53,"*пробегая с водой и умлышав знакомый голос в голове на мгновение останавливаюсь а после добавив еще немного воды бегу доливать еще, но в мгновение слившись с толпой оказываюсь рядом с подвалом выискивая глазами товарищей. затем иду вместе с ними*",107038,null],[107053,"2026-07-11T16:31:02",53,"//потом надо будет еще алкоголь поджечь :3",101220,null],[107056,"2026-07-11T16:32:03",5,"— Давайте, быстро прошмыгнём вниз. Джон, иди первый. Если там кто-то будет, кричи, что пожар. Пускай помогут тушить!",107049,null],[107060,"2026-07-11T16:32:48",11,"// идем вниз вместе?",101220,null],[107066,"2026-07-11T16:33:28",5,"// да, первый идёт работяга джон",107060,null],[107070,"2026-07-11T16:34:18",53,"*кивнув иду вперед товарищей, на лице паника, волосы взьерошены, руки мокрые, одежда тоже*",107056,null],[107071,"2026-07-11T16:34:28",11,"// карта напоминаю",101220,null],[107072,"2026-07-11T16:34:28",11,"В целом все то же что вы видели, но ещё и подвал",101220,null],[107075,"2026-07-11T16:35:18",11,"// скрытность с преимуществом всем:3",101220,null],[107077,"2026-07-11T16:35:30",11,"/r d20",101220,null],[107079,"2026-07-11T16:35:39",5,"/r +d20+6",101220,null],[107082,"2026-07-11T16:36:00",5,"Гвиндшарх внимательно смотрит, кто там внутри",101220,null],[107090,"2026-07-11T16:37:00",11,"// ну у нас же первый Джон",107070,null],[107092,"2026-07-11T16:37:14",11,"// я так и не поняла с каких пор Джонатан стал Джоном это разные имена🤔",101220,null],[107095,"2026-07-11T16:37:38",11,"https://youtube.com/shorts/fyxN6RKwZw4?si=CAfqqZjJFsefZAqV",101220,null],[107108,"2026-07-11T16:38:58",11,"Ни на Джонатана, ни на парочку совершенно никто не обратил внимание.\n\nПервый спустившийся видит всё то же что и на карте, за одним исключением: у одного из ящиков спит громила. Сюда доносятся крики с первого этажа, но не настолько громкие что бы разбудить от нетрезвого сна",101220,null],[107110,"2026-07-11T16:39:06",53,"//я представился так перед эльфом и драконом",107092,null],[107121,"2026-07-11T16:40:32",53,"*гляжу не заперт ли проход наверх, затем аккуратно возвращаюсь чуть назад и жетсами показываю товарищам быть тихими* (типо: \"тссс\" *приложил палец к губам*)",107108,null],[107123,"2026-07-11T16:41:02",53,"// этот проход имею ввиду",107072,null],[107126,"2026-07-11T16:41:07",11,"Луна тихо спускается следом и оглядывается",101220,null],[107127,"2026-07-11T16:41:11",53,"//где лежит громила?",101220,null],[107130,"2026-07-11T16:41:33",5,"*киваю*\n\nТелепатией:\n\"Нам к скрытому проходу в стене. И там заклинание сигнализации, так что маг точно будет наготове\"",107121,null],[107132,"2026-07-11T16:41:50",11,"Мужик спит здесь",107072,null],[107135,"2026-07-11T16:41:56",53,"*киваю ибо эту информацию мне передали уже*",107130,null],[107138,"2026-07-11T16:42:09",11,"Заперт с твоей стороны, впрочем в команде есть отмычки",107121,null],[107146,"2026-07-11T16:43:17",5,"// всм проход наверх?",107138,null],[107147,"2026-07-11T16:43:26",53,"может зажжем лестницу? \n*шепотом*",101220,null],[107148,"2026-07-11T16:43:41",11,"Табакси возвращает себе стандартный вид и лапой указывает на громилу вопросительно смотря на вас двоих",101220,null],[107149,"2026-07-11T16:44:16",11,"// Серёга отметил, там люк, он заперт замком снизу (где мы)",107146,null],[107150,"2026-07-11T16:44:19",5,"— Я надену кандалы. Если проснётся, ты вставь кляп",107148,null],[107151,"2026-07-11T16:44:23",53,"*вопросительно смотрю на табакси*",107148,null],[107152,"2026-07-11T16:44:26",5,"// а, мне ты сказал что люка нет(",107149,null],[107154,"2026-07-11T16:44:54",11,"// я думала ты прям в комнату секретную хотел, а вниз да есть, но без пожара вы бы спустились сюда в лапки к головорезам:3",107152,null],[107155,"2026-07-11T16:45:21",53,"//а еще он закрыт с нашей стороны так что это было бы  явно не тихо",107154,null],[107156,"2026-07-11T16:45:35",5,"Дракон тихо подходит к громиле, нежно приподнимает руки и надевает кандалы. Всё без резких движений. Но если тот  пошевелится, то сразу захлопнет замок на оковах",101220,null],[107158,"2026-07-11T16:46:03",53,"*я стою рядом что бы если что усыпить грамилу лютней по ипалу*",107156,null],[107160,"2026-07-11T16:46:35",11,"Табакси кивает и отрезает кусок ткани от мешковины что накрывает ящики \n\n— Действуй \n\n// И выпиши у себя кандалы если не заберёшь их потом:3",107150,null],[107162,"2026-07-11T16:47:06",11,"/r d2",101220,null],[107164,"2026-07-11T16:47:13",11,"// не мужик спит как убитый",101220,null],[107165,"2026-07-11T16:47:23",53,"//ну чисто я :D",107164,null],[107166,"2026-07-11T16:47:33",5,"// надел без проверки скрытности?",101220,null],[107168,"2026-07-11T16:47:38",11,"Головорез настолько напился что даже не заметил что ему на руки надели кандалы",101220,null],[107169,"2026-07-11T16:47:51",11,"// ну это рандом был энивей;3",101220,null],[107171,"2026-07-11T16:48:09",53,"ты хорош в ловушках?",107166,null],[107172,"2026-07-11T16:48:26",5,"// у меня полные карманы твоих любимых шариков",107171,null],[107173,"2026-07-11T16:48:50",11,"// главное чтоб не моих сфер, не воруйте мои сферы",101220,null],[107174,"2026-07-11T16:48:55",53,"// как кстати ящера зовут?  я помню что я томас, а луна мэри",101220,null],[107175,"2026-07-11T16:49:06",5,"Нориксиус Гвиндшарх",101220,null],[107176,"2026-07-11T16:49:09",11,"// можешь настоящим именем звать щас",101220,null],[107178,"2026-07-11T16:49:14",53,"(шепотом)",107171,null],[107179,"2026-07-11T16:49:26",53,"//не, а вдруг запись. а вдруг услышит кто.",107176,null],[107180,"2026-07-11T16:49:31",5,"Дракон осторожно двигается дальше, выглядывает в соседнее помещение.",101220,null],[107181,"2026-07-11T16:49:43",5,"// Барминар Телирон",107179,null],[107182,"2026-07-11T16:49:54",53,"//заипал игнорить вопросы джонатана",107180,null],[107184,"2026-07-11T16:50:18",5,"// а, сорри, забываю что ты речь без тире и кавычек пишншь",107171,null],[107187,"2026-07-11T16:50:50",5,"— Я хорошо умею их обходить. И обнаруживать.",107171,null],[107188,"2026-07-11T16:51:04",53,"*поворачиваюсь к луне*\nа ты?",107187,null],[107189,"2026-07-11T16:51:12",11,"— Проблема устранена полагаю — кошка открывает сумку. Фамильяр освобождаясь от оков тесноты чувствует себя куда комфортнее, пока хозяйка что-то ищет",101220,null],[107190,"2026-07-11T16:51:43",53,"*достаю спички*\nна случай если кто то все же спустится можем зажечь вход. думаю лучше будет устроить это с помощью ловушки. дабы не заполыхало раньше времени.",101220,null],[107191,"2026-07-11T16:52:00",11,"— Хорошо, но не так хорошо с магическими — шепчет она протягивая вам два свитка обнаружения магии \n\n// Вам сказать ее пассивное восприятие?",107188,null],[107194,"2026-07-11T16:52:28",53,"//мне надо не обойти ловушку а установить :3",107191,null],[107195,"2026-07-11T16:52:31",11,"// больше чем у паладина в начале квесте которое Гвинди так и не прошёл",101220,null],[107199,"2026-07-11T16:52:52",11,"// давай",107194,null],[107200,"2026-07-11T16:52:58",53,"//",107190,null],[107203,"2026-07-11T16:53:14",11,"// а сори не увидела",101220,null],[107206,"2026-07-11T16:53:42",11,"— И как ты собираешься это сделать?",107190,null],[107211,"2026-07-11T16:54:29",5,"— В случае чего я поймаю первого врага в сеть. Чтобы он занял лестницу. Но нам надо идти дальше",101220,null],[107212,"2026-07-11T16:54:42",11,"// у вас два свитка, юзать их можете, но сл проверки 11 по инте",101220,null],[107214,"2026-07-11T16:55:10",5,"Всё же достал дракон достал шарики и калтропы и рассыпал их в проходе у спуска",101220,null],[107215,"2026-07-11T16:55:43",11,"— Нужно, но мы ведь знаем что где-то здесь сигнализация.. — кошка оглядывается на лестницу — там конечно и так шумно, но кажется мне не все заняты",107211,null],[107216,"2026-07-11T16:55:49",53,"разлить масло, прицепить леску и спичечный короьок со спичкой\nили иной предмет что сможет зажечь масло.",107206,null],[107217,"2026-07-11T16:55:53",5,"/r +2 свиток",101220,null],[107219,"2026-07-11T16:56:14",11,"// было бы смешно если бы не повезло",101220,null],[107222,"2026-07-11T16:56:24",11,"// пришлось бы рваться силой))",101220,null],[107229,"2026-07-11T16:57:09",11,"Гвиндшарх чувствует два заклинания школы ограждения вокруг вас",101220,null],[107230,"2026-07-11T16:57:31",53,"//вокруг?",107229,null],[107231,"2026-07-11T16:57:33",11,"А точнее один из следующей комнаты, а один на люке который вы ещё не касались ведь так?)",101220,null],[107232,"2026-07-11T16:57:46",11,"Второй источник не на входе в комнату",101220,null],[107233,"2026-07-11T16:57:49",5,"— Два источника магии. Один на люке, другой в следующей комнате",101220,null],[107235,"2026-07-11T16:57:56",53,"я не трогал люк//",107231,null],[107236,"2026-07-11T16:58:14",11,"// поймёшь откуда конкретно когда войдёшь туда",107233,null],[107237,"2026-07-11T16:58:17",5,"— Мы и так знали, что тут магия. Кто-то знает способы снять её?",101220,null],[107238,"2026-07-11T16:58:22",5,"// вхожу",107236,null],[107240,"2026-07-11T16:58:55",53,"мэри, а у тебя есть что то, чем можно убрать магию?",107233,null],[107243,"2026-07-11T16:59:21",11,"Гвиндшарх пытается открыть дверь, но обнаруживает что она заперта.",107238,null],[107248,"2026-07-11T17:00:05",11,"— Неа — табакси улыбнулась показывая тебе клычки — я обычно избегаю её, а не снимаю — а затем подмигнула",107240,null],[107255,"2026-07-11T17:00:54",11,"— А знал ли ты где конкретно? Знание этого помогает избежать её",107237,null],[107259,"2026-07-11T17:01:15",53,"*осматриваю спящего человека*",101220,null],[107263,"2026-07-11T17:01:36",5,"// какую дверь?",107243,null],[107266,"2026-07-11T17:01:55",5,"— Где-то дальше в комнате",107255,null],[107269,"2026-07-11T17:02:15",11,"// в след комнату",107263,null],[107273,"2026-07-11T17:02:54",5,"— Сейчас открою\n\nДостал отмычки и прильнул к замку",101220,null],[107274,"2026-07-11T17:02:57",5,"/r +6",101220,null],[107277,"2026-07-11T17:03:09",11,"— Видимо они не особо хотели что бы там шастали головорезы — прокомментировала кошка увидев что дверь была закрытой",101220,null],[107279,"2026-07-11T17:03:13",53,"//как игрок я проверку проницательности явно не прошел, так что могу прокинуть на проницательность персонажа дабы понять?",107248,null],[107280,"2026-07-11T17:03:54",11,"Замок снова поддаётся драконорожденному слишком легко. Начинает казаться что замки здесь не особо качественные, им стоит покупать их у другого производителя",107275,null],[107282,"2026-07-11T17:04:03",53,"(спящий поход на головореха или на главу стражи? или вообще на мага? и есть ли у него ключи или что то подобное?)",107259,null],[107284,"2026-07-11T17:04:25",11,"// это просто действие персонажа. Игривая кошка, без намеков, просто твою фантазию балую",107279,null],[107285,"2026-07-11T17:04:55",53,"//я поросто вообще нихуа не поняф :D как связано подмигивание и избегание магии?",107284,null],[107286,"2026-07-11T17:05:04",11,"Это головорез наемник абсолютно точно.",107282,null],[107289,"2026-07-11T17:05:25",11,"// щас довыделываешься и кошка не будет тебе подмигивать.",107285,null],[107290,"2026-07-11T17:06:15",5,"— Так-так. Что же там дальше?",107280,null],[107291,"2026-07-11T17:06:17",53,"*осматриваю и остальную комнату в поисках чего либо что поможет открыть тайный проход*",101220,null],[107292,"2026-07-11T17:06:20",5,"*захожу*",101220,null],[107293,"2026-07-11T17:06:29",5,"*и смотрю где магия*",101220,null],[107294,"2026-07-11T17:06:39",5,"— Стой! Тут сигнализация где-то",107291,null],[107295,"2026-07-11T17:06:44",11,"За дверью оказывается небольшая комната. Судя по всему, ею давно не пользовались: мебель покрылась пылью, а воздух пропитался запахом сырости и старого дерева. Свет сюда попадает только из предыдущей комнаты, так что вы не очень хорошо видите в полумраке.\n\nПосредине стоит массивный письменный стол, заваленный пожелтевшими журналами и пустыми чернильницами. Возле стен — Полки с чем-то в паутине и шкаф с открытыми дверцами, внутри которого стоят потрёпанные книги. \n\nНа открытом участке стены висят старые механические часы, которые, судя по всему, давно перестали идти. Под ними прибита деревянная доска с несколькими пустыми крючками для ключей — на одном из них до сих пор висит единственный ржавый ключ.\n\nВ углу комнаты стоят два старых деревянных ящика и потёртая скамья. На первый взгляд помещение выглядит заброшенной комнатой охраны и не представляет никакого интереса.",101220,null],[107296,"2026-07-11T17:07:26",5,"/roll@roll_bot",107293,null],[107298,"2026-07-11T17:07:42",5,"// эмм просто на сообщение отвечал, где магия)",107293,null],[107302,"2026-07-11T17:07:57",11,"// сперва пусть Джонатан озвучит что тут привлекло его внимание, раз влез первый)",101220,null],[107308,"2026-07-11T17:08:31",53,"//так я позади вас оглядываю комнату с лежащим :3",107302,null],[107309,"2026-07-11T17:08:58",11,"// а, оке",107308,null],[107311,"2026-07-11T17:09:22",53,"эту//",107132,null],[107315,"2026-07-11T17:10:07",11,"// давай на проницательность пока, а я ща дракону отвечу",101220,null],[107316,"2026-07-11T17:10:15",53,"//но вот это явно очень привлекает внимание :3",107295,null],[107318,"2026-07-11T17:10:27",53,"+2//",107317,null],[107319,"2026-07-11T17:10:36",53,"19//",101220,null],[107322,"2026-07-11T17:11:12",53,"//заипався писать @rollrobot 1 20 2, так что буду по старинке писать чистую к20 и кидать модификатор после",101220,null],[107335,"2026-07-11T17:13:30",11,"Драконорожденный при воздействии свитка чувствует магию ограждения на открытом шкафу с книгами. Он стоит прямо у того места за которым должна быть скрытая дверь",101220,null],[107343,"2026-07-11T17:15:05",11,"// Что-то да найдешь и залутаешь с таким броском, я позже придумаю)",107319,null],[107345,"2026-07-11T17:15:33",11,"// просто хочу что бы оно полезно тебе было и приемлимо в качестве Лута так что в конце напишу напомни если забуду",101220,null],[107348,"2026-07-11T17:15:50",11,"// давайте дальше действия",107335,null],[107349,"2026-07-11T17:16:11",5,"— Шкаф с книгами защищён. Надо найти другой способ. Тайный рычаг?",107335,null],[107351,"2026-07-11T17:16:47",53,"*после обыска  иду к товарищам*",101220,null],[107352,"2026-07-11T17:16:49",5,"— Ключ.. Не знаю, зачем он нужен. Часы?\n\nДракон стучит по часам и дёргает что там дергается",101220,null],[107356,"2026-07-11T17:17:27",53,"//в помещении есть предметы с карты?",107311,null],[107358,"2026-07-11T17:17:49",11,"— Да, не хотели что бы силой ломились, но если бы нельзя было войти иначе то сигнализация работала бы и на них самих",107349,null],[107363,"2026-07-11T17:18:16",11,"// я кидала описание комнаты, оно примерно похоже на то что тут есть, а остальное если не учла то не примечательно",107356,null],[107366,"2026-07-11T17:18:52",53,"//просто хочу спиздить топор со стола. очень уж мне понравилось как он выглядит",107363,null],[107367,"2026-07-11T17:18:55",11,"Часовые стрелки подвижны",107352,null],[107368,"2026-07-11T17:19:03",11,"// что ты с ними сделал?)",101220,null],[107369,"2026-07-11T17:19:15",5,"// просто трогаю всё что нельзя",101220,null],[107370,"2026-07-11T17:19:32",11,"// это кирка",107366,null],[107372,"2026-07-11T17:19:48",11,"Часовая стрелка до твоего вмешательства была на 23:58",107369,null],[107373,"2026-07-11T17:19:48",53,"*взяв со столика топор убераю его в сумку и иду осматривать деревянные ящики в углу комнаты*",101220,null],[107377,"2026-07-11T17:20:07",11,"Кирку.",107373,null],[107381,"2026-07-11T17:20:12",53,"//я про этот",107380,null],[107382,"2026-07-11T17:20:23",11,"// ой ладно топор так топор.. ржавый",101220,null],[107384,"2026-07-11T17:20:44",53,"//зато топор. с ахуенной ручкой.",107382,null],[107385,"2026-07-11T17:20:47",5,"— 23:58...\n\nГвинди вспоминает механизм работы заклинания тревоги",107372,null],[107386,"2026-07-11T17:20:50",5,"/r +2 магия",101220,null],[107388,"2026-07-11T17:21:08",11,"Магии на часах нет",101220,null],[107391,"2026-07-11T17:21:29",5,"// вспомнил что заклинание надо обновлять каждые 8 часов?",101220,null],[107398,"2026-07-11T17:22:21",11,"А ещё вспомнил что оно действует в определенном радиусе так что подходить к шкафу плохая идея",101220,null],[107401,"2026-07-11T17:23:00",11,"Просто ржавый ключ на вид",107352,null],[107404,"2026-07-11T17:23:27",11,"— Что-то здесь должно открывать секретную дверь — подсказывает Луна",101220,null],[107405,"2026-07-11T17:23:55",53,"*пытсь открыть ящики*",107373,null],[107406,"2026-07-11T17:23:58",5,"— Надо крутить стрелки.\n\n Перевожу на 8 часов вперёд. Если не работает, то ещё на 8. И ещё один раз",107404,null],[107407,"2026-07-11T17:24:21",5,"*смотрю откроется ли шкаф*",101220,null],[107408,"2026-07-11T17:24:29",11,"*реакции нет*",101220,null],[107409,"2026-07-11T17:24:46",11,"// где?",107405,null],[107410,"2026-07-11T17:24:56",11,"// используй описание комнаты, а не карту, баловень",101220,null],[107412,"2026-07-11T17:25:44",53,"//я из описания комнаты ящики взял :3",107410,null],[107413,"2026-07-11T17:25:57",11,"// вы можете осмотреть все что я описывала с проницательностью",101220,null],[107414,"2026-07-11T17:26:02",53,"//",107295,null],[107416,"2026-07-11T17:26:07",11,"// но на каждый предмет отдельный бросок",101220,null],[107417,"2026-07-11T17:26:12",5,"— Хмм. Что с ключами?\n\nБеру их",107401,null],[107419,"2026-07-11T17:26:58",11,"С соседней комнаты доносится храп головореза",101220,null],[107420,"2026-07-11T17:27:17",11,"// а у драконов есть ночное зрение кста?",101220,null],[107421,"2026-07-11T17:27:27",5,"// нет",101220,null],[107423,"2026-07-11T17:27:45",53,"*если ящики открыты то внимательно осматриваю их пытаясь понять как их все же открыть без использования топора*",101220,null],[107424,"2026-07-11T17:27:58",11,".",107416,null],[107428,"2026-07-11T17:28:21",53,"XD//",107427,null],[107429,"2026-07-11T17:28:28",53,"+2//",101220,null],[107431,"2026-07-11T17:28:54",5,"Дракон смотрит на следы на полу. Около шкафа. Куда они ведут. Где меньше пыли?",101220,null],[107432,"2026-07-11T17:28:54",11,"Ящики оказались оба закрыты, а один ещё и пылью тебя осыпал да так что ты закашлялся",101220,null],[107433,"2026-07-11T17:28:56",5,"/r +2",101220,null],[107435,"2026-07-11T17:29:06",11,"// теперь давай скрытность",107432,null],[107438,"2026-07-11T17:29:19",53,"+2//",101220,null],[107440,"2026-07-11T17:29:44",11,"Мужик в соседней комнате проснулся от твоего кашля..",101220,null],[107441,"2026-07-11T17:29:54",5,"//я слышу?",107440,null],[107443,"2026-07-11T17:30:04",11,"Пока что бормотание",101220,null],[107445,"2026-07-11T17:30:11",53,"//у него во рту кляп и руки в наручниках, так?",107440,null],[107446,"2026-07-11T17:30:17",11,"// он в кандалах, но без кляпа",101220,null],[107449,"2026-07-11T17:30:38",11,"У вас по заявке иначе он начинает орать",101220,null],[107453,"2026-07-11T17:31:11",53,"*заметив остановившийся храп оборачиваюсь на головореза и достав лютню и к нему аккуратно привлекая внимание товаришей. затем заю ему по морде лютней, что бы поспал подольше*",107440,null],[107456,"2026-07-11T17:31:28",11,"// на лежачих в мили авто Крит да?",101220,null],[107459,"2026-07-11T17:31:52",53,"//преимущество на попадание в юлижнем бою точно помню, насчет крита щас гляну",107456,null],[107461,"2026-07-11T17:32:19",5,"// на бессознательных да",107456,null],[107463,"2026-07-11T17:33:02",5,"Дракон бежит к нему и помогает, всадив дротик в плечо",107453,null],[107464,"2026-07-11T17:33:16",5,"// нелетальная атака",101220,null],[107465,"2026-07-11T17:33:23",11,"// бедный мужик",101220,null],[107466,"2026-07-11T17:33:48",5,"// урон крита?",101220,null],[107467,"2026-07-11T17:33:58",11,"— Могли просто кляп в рот вставить.. — говорит кошка наблюдая за тем как с ран головореза капает кровь образовывая лужицу на полу",101220,null],[107468,"2026-07-11T17:34:33",5,"— Такого амбала надолго не задержит. Он порвёт кандалы",107467,null],[107469,"2026-07-11T17:34:35",11,"// хороший ход кстати",107434,null],[107470,"2026-07-11T17:34:40",5,"— Пусть полежит без сознания",101220,null],[107471,"2026-07-11T17:34:54",11,"Даже в полутьме дракон замечает что возле часов меньше пыли, из-за него ли..?",101220,null],[107473,"2026-07-11T17:35:14",53,"//я его просто по голове лютней уебал что б спал :3 мы добрые :3",107465,null],[107475,"2026-07-11T17:35:26",11,"// он лежачий, так что урон это нанесет)",107473,null],[107476,"2026-07-11T17:35:53",11,"// впрочем я не думаю что он будет в состоянии драться теперь, так что забейте, без бросков",101220,null],[107477,"2026-07-11T17:36:02",11,"Кошка вернулась в темную комнату",101220,null],[107478,"2026-07-11T17:36:06",53,"//а это уже его проблемы что лютня бьет на к6+1",107475,null],[107480,"2026-07-11T17:36:27",11,"// ты даже не бард",101220,null],[107484,"2026-07-11T17:36:43",53,"//зато музыкант и актер",107480,null],[107485,"2026-07-11T17:36:53",11,"// ждём реакции Дракоши",101220,null],[107487,"2026-07-11T17:37:14",5,"— Меньше пыли вокруг часов. Дело в них!",107471,null],[107489,"2026-07-11T17:37:29",53,"*закрыв раны головореза как могу закрываю и его рот кляпом из брезента на ящиках*",107467,null],[107490,"2026-07-11T17:37:30",11,"— Есть идеи что с ними делать?",101220,null],[107491,"2026-07-11T17:37:33",5,"Пытаюсь отломать часы от стены",101220,null],[107493,"2026-07-11T17:37:48",11,"// ахвхахахвх к этому я не была готова",101220,null],[107495,"2026-07-11T17:38:03",11,"// ну давай силу",101220,null],[107497,"2026-07-11T17:38:07",53,"//а у меня такое действие было в мыслях, но я пока часы не лапал",107493,null],[107498,"2026-07-11T17:38:23",5,"/r -1",101220,null],[107504,"2026-07-11T17:39:21",53,"а если перевести время на полночь?",107487,null],[107508,"2026-07-11T17:39:36",11,"Часы ломаются, ничего не происходит",101220,null],[107509,"2026-07-11T17:39:45",53,"*сказав это подхожу ближе к товарищам осматривая часы после обработки громтлы*",101220,null],[107512,"2026-07-11T17:40:12",11,"— Я думаю что нужно было делать не это.. — Луна вздыхает опускаясь на пол осмотреть осколки сломанных часов",101220,null],[107514,"2026-07-11T17:40:31",11,"— Можно было попробовать, но часы сломаны",107504,null],[107515,"2026-07-11T17:40:49",5,"Смотрю, есть ли механизм в стене за часми",101220,null],[107516,"2026-07-11T17:40:59",11,"// кидай",101220,null],[107518,"2026-07-11T17:41:12",5,"/r +4",101220,null],[107520,"2026-07-11T17:41:18",53,"*смотрю есть ли какой либо механизм в часах и заодно пытаюсь их соеденить и таки перевести стрелки на нужное время. что бы было лучше видно подсвечиваю спичкой*",101220,null],[107527,"2026-07-11T17:41:45",11,"// с помехой, ты в полумраке",107519,null],[107541,"2026-07-11T17:43:24",11,"Гвиндшарх находит металлическую нить что была как-то связана с часами она сторчит из стены. Джонатан так же видит часть лески среди осколков. Она привязана к минутной стрелке",101220,null],[107543,"2026-07-11T17:43:32",11,"// вообще да..",107504,null],[107546,"2026-07-11T17:43:44",11,"// но против лома нет приёма 😁",101220,null],[107558,"2026-07-11T17:44:42",53,"//просто внезапнач мычль пришла что возможно 00:00 на часах что то да даст, когда до него оставалось две минуты :3",107543,null],[107560,"2026-07-11T17:45:00",11,"// если бы вы осмотрели стол то нашли бы зацепку",101220,null],[107564,"2026-07-11T17:45:26",11,"// впрочем это не рельсы, так что вариативность это хорошо:3",101220,null],[107566,"2026-07-11T17:45:33",53,"//что то кидать?",107520,null],[107568,"2026-07-11T17:45:42",11,"//",107541,null],[107574,"2026-07-11T17:46:02",5,"— Нить. Думаю, её надо потянуть. Так ведь?",107541,null],[107575,"2026-07-11T17:46:12",53,"//а, я прост слегка слепой",107541,null],[107578,"2026-07-11T17:46:20",11,"// я не сразу исправила просто",101220,null],[107579,"2026-07-11T17:46:53",11,"— Попробуй — Луна подымается и отряхивает свой плащ, а затем протягивает лапу Джонатану",101220,null],[107582,"2026-07-11T17:47:23",5,"Беру нитку в когти и тяну осторожно, прислушиваясь",101220,null],[107583,"2026-07-11T17:47:49",53,"//ладонью вверх, ладонью вниз или боком?",107579,null],[107584,"2026-07-11T17:48:27",11,"// боком если тебе это важно",101220,null],[107585,"2026-07-11T17:48:38",53,"*подаю ей руку*",107579,null],[107586,"2026-07-11T17:48:44",11,"*звук шуршания за стеной*",107582,null],[107591,"2026-07-11T17:49:28",11,"Крепкая кошка помогает тебе подняться\n\n// Щас прогуглила рост табакси, 180-210, она тебя выше, мальчик",107585,null],[107593,"2026-07-11T17:49:58",5,"// теперь я знаю как представлять эту пару",107591,null],[107594,"2026-07-11T17:50:18",5,"Тяну дальше, смотрю на шкаф",107586,null],[107595,"2026-07-11T17:50:26",11,"Звук становится отдаленнее и спустя какое-то время шкаф вместе со стеной отодвигается как дверь",101220,null],[107597,"2026-07-11T17:50:44",53,"//да я вроде не падал, но спасибо :D\n\n\n\n*поднимаюсь и вырвав стрелку из часов убираю ее в карман*",107591,null],[107598,"2026-07-11T17:51:02",11,"// ты на полу осматривал разбитые часы, она тоже",107597,null],[107601,"2026-07-11T17:51:30",5,"Зоркий глаз Гвиндшарха заметил это.\n\n— Воровать нехорошо! — сказал с укоризной",107597,null],[107604,"2026-07-11T17:51:44",11,"— Сила есть ума не надо",107595,null],[107605,"2026-07-11T17:51:44",53,"//XD",107601,null],[107606,"2026-07-11T17:52:16",11,"// кстати у вас +- одни мотивы на самом деле путешествовать",101220,null],[107607,"2026-07-11T17:52:34",5,"— Ну, я знал, что у механизма есть внешняя связь. Так что это не только сила",107604,null],[107608,"2026-07-11T17:52:45",53,"стрелка может нам еще пригодится. а ломать чужие вещи тоже не самое хорошее дело.\n*слегка улыбаясь смотрю на дракошу*\n\nмагия исчезла? или она еще там?",107601,null],[107609,"2026-07-11T17:53:43",5,"*проверяя магию*\n\n— Это я шутил. Ты только что целый склад поджог.",107608,null],[107610,"2026-07-11T17:53:46",11,"Драконорожденный чувствует что магия вместе с дверью отодвинулась",101220,null],[107611,"2026-07-11T17:54:12",5,"— Магия отошла. Можно идти!",101220,null],[107612,"2026-07-11T17:54:24",11,"— Вообще-то он прав, отвлечение то отличное, но последствия могут быть..",107609,null],[107616,"2026-07-11T17:55:13",11,"— Только осторожнее",107611,null],[107619,"2026-07-11T17:55:25",11,"// кто первый пойдет?)",101220,null],[107620,"2026-07-11T17:55:25",53,"а еще вырвал стрелку часов из разбитых часов. :3\n*улыбаясь смотрю в проход*\n\nа что за глава стражи? его заместителя я видел, а вот самого его не примечал?",107609,null],[107621,"2026-07-11T17:55:32",11,"// и опишите как идём",101220,null],[107623,"2026-07-11T17:56:05",11,"— Там было написано \"ветеран\" — отвечает Луна вспоминая надписи из дневника",107620,null],[107625,"2026-07-11T17:56:40",53,"вы не видели его наверху? быть может он тоже где то здесь?",107623,null],[107626,"2026-07-11T17:56:48",5,"— Даже не знаю. И он не в ладах с магом",107620,null],[107627,"2026-07-11T17:56:54",5,"— Давайте двигаться скрытно",101220,null],[107628,"2026-07-11T17:57:01",11,"— Вполне вероятно — она старается говорить тише и вам показывает пальцем \"тсс\"",101220,null],[107631,"2026-07-11T17:57:35",11,"// кто заходит опишите как пожалуйста",101220,null],[107640,"2026-07-11T17:58:21",53,"*тихо, стараясь не издавать шагов иду последним, руки заняты взятой со столика киркой*",107628,null],[107645,"2026-07-11T17:59:02",11,"— Ты клептоман?",101220,null],[107646,"2026-07-11T17:59:25",5,"*иду тихо, вытащил сеть и готов кинуть в случае чего*",101220,null],[107647,"2026-07-11T17:59:35",53,"нет. но кирка будет полезной если нас завалит.",107645,null],[107648,"2026-07-11T17:59:48",53,"(шепотом)",107647,null],[107651,"2026-07-11T18:00:16",5,"Дракон незаметно выглядывает в комнату дальше",101220,null],[107652,"2026-07-11T18:00:28",11,"// и в чем он не прав, щас соберёт хлам, а затем этим хламом одолеет тараска",107647,null],[107653,"2026-07-11T18:00:50",11,"// бля",107651,null],[107654,"2026-07-11T18:01:41",53,"//и это я еще не говорю о том что киркой можно снести замок или хлебало.",107652,null],[107655,"2026-07-11T18:01:53",53,"//с любым ударением",107654,null],[107657,"2026-07-11T18:03:45",11,"Драконорожденный чувствует тонкую нить паутины на его лице и застывает на месте. (Что видит Джонатан)\n\nВ это мгновение ему кажется что впереди его уже заметили. Чувство страха сковывает его, кажется будто на него смотрит что-то что читает его на сквозь.. но наводнение вскоре отпускает",101220,null],[107659,"2026-07-11T18:04:36",53,"кого?//",107657,null],[107660,"2026-07-11T18:04:58",11,"Гвиндшарх даже не заметил что задержал дыхание и теперь ему не хватало воздуха, а сердце будто кто-то сдавил..",101220,null],[107661,"2026-07-11T18:05:15",5,"Гвинди пытается понять, что происходит",101220,null],[107662,"2026-07-11T18:05:33",5,"И обращается к обнаружению магии всё ещё",101220,null],[107663,"2026-07-11T18:05:38",53,"*покрепче сжимаю кирку а после слегка бесшумно выдыхаю, смотря на действия кошки*",101220,null],[107667,"2026-07-11T18:06:37",11,"Ничего.. \n\n// Серёга ведь научил что не всегда магию найти можно",107662,null],[107669,"2026-07-11T18:07:01",11,"Впрочем Джонатан и Луна слышат разговор двоих голосов",101220,null],[107670,"2026-07-11T18:07:18",53,"*пытаюсь понять откуда идет голос и что говорят голоса*",107669,null],[107671,"2026-07-11T18:07:35",11,"// проницательность с помощью от луны",101220,null],[107673,"2026-07-11T18:07:54",53,"//+2",101220,null],[107674,"2026-07-11T18:07:57",53,"//XD",101220,null],[107675,"2026-07-11T18:08:54",11,"Слова Джонатану различить не удаётся, но интонации и голоса да — они о чём-то спорят. Один голос принадлежит женщине и звучит молодо, другой же пожилому мужчине",101220,null],[107676,"2026-07-11T18:09:06",53,"*шепчу луне*\n\nможешь слышать то что слышит филин?",107675,null],[107677,"2026-07-11T18:09:20",11,"// Гвинди, дыши и попустит, но в след раз ловушки проверяй",101220,null],[107678,"2026-07-11T18:09:35",5,"// это паралич был?",101220,null],[107679,"2026-07-11T18:09:44",11,"// не совсем",101220,null],[107680,"2026-07-11T18:09:55",11,"// тебя обнаружили",101220,null],[107681,"2026-07-11T18:10:14",11,"// Но судя по тому что голоса продолжают спорить, то не они",101220,null],[107682,"2026-07-11T18:10:26",5,"Гвинди вдыхает и слушает, что они говорят",101220,null],[107683,"2026-07-11T18:10:41",11,"// скрытность и продолжаем двигаться",101220,null],[107684,"2026-07-11T18:10:49",11,"// тут уже попробовали послушать и не вышло)",101220,null],[107685,"2026-07-11T18:10:55",5,"// ладно",101220,null],[107686,"2026-07-11T18:10:58",5,"/r +6",101220,null],[107688,"2026-07-11T18:11:10",11,"Гвиндшарх продвигается вперёд",101220,null],[107691,"2026-07-11T18:11:14",5,"— Отпустило. Не знаю, что это было",101220,null],[107693,"2026-07-11T18:11:29",53,"+2//",101220,null],[107694,"2026-07-11T18:12:05",11,"Здесь очень темно, только свечи слабо освещают помещение",101220,null],[107697,"2026-07-11T18:12:54",5,"// кого вижу?",101220,null],[107700,"2026-07-11T18:13:26",11,"Никого, но слышишь что голоса идут сверху. Помещение похоже на темницу",101220,null],[107701,"2026-07-11T18:13:40",11,"// слушаем?",101220,null],[107702,"2026-07-11T18:13:44",11,"/r d20",101220,null],[107704,"2026-07-11T18:13:54",5,"/r +4",101220,null],[107706,"2026-07-11T18:14:07",5,"Ищу взглядом клетку",101220,null],[107707,"2026-07-11T18:14:29",11,"// не поверите, но ее не заметили:3",107703,null],[107708,"2026-07-11T18:14:54",11,"Она напротив тебя, но полностью темная. Слишком. Темная.",107706,null],[107709,"2026-07-11T18:15:10",11,"Кошка продвигается за тобой и тоже выходит в коридор",101220,null],[107710,"2026-07-11T18:15:28",11,"// на тоненького",107692,null],[107711,"2026-07-11T18:15:36",11,"Никто вас не заметил",101220,null],[107712,"2026-07-11T18:15:51",5,"— Я чувствую, в клетке кто-то есть. *шёпотом*\n\nТелепатией сигнал прямо во тьму.\n\"Кто ты? Я не желаю зла. Хочешь, выпущу тебя?\"",107708,null],[107713,"2026-07-11T18:16:29",11,"— Твоя задача только охранять это пока не заберут — говорит мужчина \n\n— Старый дурак, ты не понимаешь как редко открывается такая возможность?!",101220,null],[107714,"2026-07-11T18:17:26",5,"// голоса наверху, то есть этажом выше?",107713,null],[107715,"2026-07-11T18:17:37",11,"// Ты посмотрел в бездну и бездна взглянула на тебя в ответ",107712,null],[107716,"2026-07-11T18:17:45",11,"// наверху по карте",107714,null],[107717,"2026-07-11T18:18:29",5,"// обнаружение магии видит что в клетке?",107715,null],[107718,"2026-07-11T18:19:01",53,"*продолжаю слушать разговор*",107713,null],[107719,"2026-07-11T18:19:20",5,"*тихо*\n\n— Они обсуждаю артефакт. Должно быть глава стражи и маг. Но где сама вещь?",107713,null],[107723,"2026-07-11T18:25:06",5,"/r +2",101220,null],[107726,"2026-07-11T18:25:51",11,"Голоса стараются звучать жалобно, но ты понимаешь что они не принадлежит чему-то хорошему",101220,null],[107728,"2026-07-11T18:26:12",11,"Твой отец говорил тебе о демонах и о том как они уговаривают на договор жертв..",101220,null],[107732,"2026-07-11T18:28:15",11,"Ветеран:\n— Я уже говорил тебе... это плохая идея.\n\nУченица мага:\n— Потому что тебе страшно?\n\nВетеран:\n— Потому что я прожил достаточно долго, чтобы отличать опасность от глупости.",107718,null],[107733,"2026-07-11T18:28:40",5,"Спутникам:\n\"Какой-то демон в клетке говорит со мной\"\n\nЭтому нечто:\n\"Сначала помоги мне. Где артефакт?\"",107728,null],[107734,"2026-07-11T18:29:01",11,"Ученица:\n— Опасность? Это величайший шанс! Представляешь, сколько можно узнать, если всё получится?",101220,null],[107735,"2026-07-11T18:29:56",53,"*пока что просто стою на готовле ожидая подхожящего момента и шепотом передаю кошке*\nвозможно с ними удастся договорится. ты все еще можешь изменить своб внешность?",107734,null],[107737,"2026-07-11T18:30:45",11,"*кивок*\n\n— Какой план?",107735,null],[107739,"2026-07-11T18:31:06",11,"— Гвинди говорит что здесь демон.. они говорят о демоне..?",101220,null],[107740,"2026-07-11T18:31:33",11,"\"Я дам тебе артефакт и не один, только согласись\"",107733,null],[107741,"2026-07-11T18:31:59",5,"— Договориться? Что ты им предложишь?",107735,null],[107742,"2026-07-11T18:32:08",11,"Гвиндшарх начинает видеть лиловые глаза в темноте что смотрят ему прямо в душу",101220,null],[107743,"2026-07-11T18:32:26",11,"Чувствует это даже если отвернётся",101220,null],[107744,"2026-07-11T18:32:32",11,"// Луна и Джон нет",101220,null],[107745,"2026-07-11T18:33:06",5,"*не отвечаю*\n\nТелепатией спутникам:\n\"Демон обещает артефакты. И смотрит на меня. Надо торопится\"",107740,null],[107746,"2026-07-11T18:34:20",11,"В твоей голове звучит смех что отдаётся головной болью\n// На счёт псих урона хз так что просто помеха на след действие",101220,null],[107747,"2026-07-11T18:34:47",11,"// Серёга, озвучивай план",101220,null],[107748,"2026-07-11T18:34:58",5,"Дракон пока идёт проверять комнату справа.",101220,null],[107749,"2026-07-11T18:35:09",53,"//на секунду отошел XD",107747,null],[107750,"2026-07-11T18:35:23",11,"— Не неси глупости, я здесь что бы сторожить это пока его не заберут — отвечает мужчина, а женщина лишь цокает языком",101220,null],[107751,"2026-07-11T18:35:46",11,"Шаги приближаются к вам \n\n— Куда ты пошла? — встревоженный мужской голос",101220,null],[107752,"2026-07-11T18:35:55",11,"// она идёт к вам",101220,null],[107753,"2026-07-11T18:35:58",5,"— Они и правда говорят о демоне. Что твоя госпожа Ди может хотеть от него, Луна?",107750,null],[107755,"2026-07-11T18:36:16",5,"\"Прячьтесь\"",107752,null],[107756,"2026-07-11T18:36:23",11,"// Ди это имя госпожи",101220,null],[107757,"2026-07-11T18:36:29",53,"шепчу: измени внешность, а дальше мы с ними договримся",107737,null],[107759,"2026-07-11T18:36:32",5,"// перепутал",107756,null],[107760,"2026-07-11T18:36:46",5,"Дракон ускользает туда",107748,null],[107761,"2026-07-11T18:36:55",11,"— Я не знаю, но уверена что это именно то чего искал Дин — шепчет она",101220,null],[107762,"2026-07-11T18:37:24",11,"// скрытность тогда",107760,null],[107763,"2026-07-11T18:37:25",53,"*отхожу за стену так что бы туда могла пройти и кошка*",101220,null],[107765,"2026-07-11T18:37:35",11,"Табакси слушает Джонатана и принимает человеческий облик",101220,null],[107766,"2026-07-11T18:37:39",5,"/r +6 интересно от кого",107762,null],[107770,"2026-07-11T18:38:00",11,"// так прячемся или встречаем мага?",107763,null],[107773,"2026-07-11T18:38:17",53,"//сначала прячемся а потом изза угла встречаем мага",107770,null],[107774,"2026-07-11T18:38:31",11,"/r d20",101220,null],[107777,"2026-07-11T18:38:39",5,"// я заготовил бросок сети",101220,null],[107778,"2026-07-11T18:38:41",11,"// луна прячется ещё лучше чем Гвинди",101220,null],[107779,"2026-07-11T18:39:49",11,"// тебе тоже надо скрытность если мы прячемся:3",101220,null],[107780,"2026-07-11T18:40:06",53,"//а, точно. мне ж тоже надо скрытность прокинуть (так и не нашел нужное эможзи)",107778,null],[107782,"2026-07-11T18:40:23",53,"+2. 19//",101220,null],[107785,"2026-07-11T18:41:08",53,"//звуки дождя на фон :3",101220,null],[107786,"2026-07-11T18:41:23",11,"Все успешно скрываются в следующей в другой тюремной клетке",101220,null],[107787,"2026-07-11T18:41:58",11,"Женщина подходит. Вы видите на ней одеяние мага, она направляется к соседней клетке",101220,null],[107788,"2026-07-11T18:42:08",11,"// что-то делаем или ждём?",101220,null],[107789,"2026-07-11T18:42:19",11,"// жду от Эла ответку",107785,null],[107792,"2026-07-11T18:43:01",53,"*киваю луне что бы она схватила мага и не дала ей закричать*",101220,null],[107794,"2026-07-11T18:43:39",11,"// неа, вы действуете)",101220,null],[107795,"2026-07-11T18:43:43",11,"// у дракона вон сеть",101220,null],[107796,"2026-07-11T18:44:03",5,"Внимательно слежу за движениями. Если протянет руку к клетке, то бросаю сеть.",107787,null],[107797,"2026-07-11T18:44:25",11,"// к какой клетке, нашей или соседней? Нашу не тронет, соседнюю да, намеревается открыть",101220,null],[107798,"2026-07-11T18:44:31",5,"// к демону",101220,null],[107799,"2026-07-11T18:44:40",11,"// тогда кидай :3",101220,null],[107800,"2026-07-11T18:44:48",5,"/r +d20+8",101220,null],[107801,"2026-07-11T18:44:56",11,"// а теперь вспомни что у тебя помеха была",101220,null],[107802,"2026-07-11T18:45:08",5,"/roll +8",101220,null],[107805,"2026-07-11T18:46:17",53,"*аккуратно закрываю ей рот и тихо шепчу: \"отвечай на наши вопросы и не шуми и мы можем закончить эту встречу.. довольно выгодно для нас всех.\" *говорю это голосом ожного из стражников чьи голоса мы слышали на улице до входа на склад*ч",101220,null],[107807,"2026-07-11T18:46:25",11,"— Аарон! Здесь кто-то есть! — визжит женщина попавшись в сеть \n\nНа ее крики выбегает пожилой мужчина-воин",101220,null],[107809,"2026-07-11T18:46:51",11,"// не, не успел подойти) она сразу заорала",101220,null],[107810,"2026-07-11T18:47:00",5,"// если это поздно, то бросаюьс с кандалами и действием замыкаю на ней",107805,null],[107811,"2026-07-11T18:47:02",11,"// так что иня",101220,null],[107812,"2026-07-11T18:47:14",5,"/r +4",101220,null],[107815,"2026-07-11T18:47:49",53,"+2//",101220,null],[107816,"2026-07-11T18:49:30",11,"/r d20+2\n/r d20+1\n/r d20+5",101220,null],[107818,"2026-07-11T18:49:58",11,"Ветеран\nЛуна\nГвиндшарх \nДжонатан \nМаг",101220,null],[107820,"2026-07-11T18:50:23",5,"— Кандалы! Сковайте мага!",101220,null],[107821,"2026-07-11T18:51:17",53,"может все таки договоримся?\nнас явно больше чем вас.\n(противникам)",101220,null],[107822,"2026-07-11T18:52:02",11,"Ветеран с 20 инициативы тратит действие на то что бы освободить мага",101220,null],[107823,"2026-07-11T18:52:07",11,"/r d20",101220,null],[107825,"2026-07-11T18:52:16",11,"// Успешно, ход",101220,null],[107826,"2026-07-11T18:52:49",11,"— Вы влезли на частную территорию и атаковали работника! — гневно отвечает Аарон",107821,null],[107827,"2026-07-11T18:53:06",11,"— Даже не смей их слушать — освобождаясь от пут отвечает девушка",101220,null],[107829,"2026-07-11T18:53:29",11,"// командуйте луне или мне атаковать?",101220,null],[107830,"2026-07-11T18:53:42",5,"— Нельзя выпускать этого демона на волю! Это безумие! Извиняюсь за сеть, но так было нужно",107826,null],[107831,"2026-07-11T18:54:58",11,"— А вы здесь зачем? Вам ведь тоже нужен он! — маг настроена крайне негативно, ветеран колеблется после слов о демоне",101220,null],[107832,"2026-07-11T18:55:06",53,"//команда из 3 плутов против война и мага 🤔",101220,null],[107833,"2026-07-11T18:55:49",53,"//могу кинуть проницательность чтоб понять а зачем ей этот демон?",101220,null],[107834,"2026-07-11T18:56:07",11,"// ты и без нее понимаешь что она хочет знаний как и наш Юра",101220,null],[107835,"2026-07-11T18:56:08",5,"— Нам нужно, чтобы демон сидел взаперти. А ты собираешься его выпустить!",107831,null],[107836,"2026-07-11T18:56:15",11,"// и не только знаний",101220,null],[107837,"2026-07-11T18:56:34",11,"— Аарон, кому ты поверишь?!",107835,null],[107838,"2026-07-11T18:56:52",11,"// давайте убеждение кто-то один с заявкой, но спас высокий будет ибо камон вы свое положение видели)",101220,null],[107839,"2026-07-11T18:57:08",5,"// лучше джонни",101220,null],[107840,"2026-07-11T18:57:09",53,"неужели это демоническое отродье смогло обмануть тебя, маг? неужели ты поддалась сладким речам демона?",107831,null],[107842,"2026-07-11T18:57:24",11,"// ты кого убеждаешь, мага или ветерана?",107840,null],[107843,"2026-07-11T18:57:42",53,"//желательно обоих. но вообще больше ветерана.",107842,null],[107844,"2026-07-11T18:58:10",53,"//оке",107839,null],[107846,"2026-07-11T18:58:15",53,"+7//",101220,null],[107847,"2026-07-11T18:58:35",53,"//вот она сила плута черес харизму :3",101220,null],[107849,"2026-07-11T18:59:03",11,"— Неужели эти двое говорят правду и ты правда пыталась открыть клетку?! — Отвечает мужчина",101220,null],[107851,"2026-07-11T18:59:37",53,"//на 4 лвле обязательно надо будет взять телепатию..",101220,null],[107852,"2026-07-11T18:59:40",11,"// считайте вы свои ходы на болтовню потратили:3 Луну вы скипнули и она просто в инвизе сидит пердит",101220,null],[107853,"2026-07-11T18:59:45",11,"/r d20",101220,null],[107855,"2026-07-11T18:59:56",11,"// да ее не заметили",101220,null],[107856,"2026-07-11T19:00:14",5,"// вроде не надо кидать ещё раз, если не открывался действиями",101220,null],[107857,"2026-07-11T19:00:52",11,"// да похер, ее почти анрил заметить",101220,null],[107858,"2026-07-11T19:01:31",11,"/r -d20",101220,null],[107860,"2026-07-11T19:02:07",11,"// ну даже с минусом",101220,null],[107861,"2026-07-11T19:02:19",11,"/r d20",101220,null],[107863,"2026-07-11T19:02:24",53,"//?",107859,null],[107864,"2026-07-11T19:02:26",53,"//?",107862,null],[107865,"2026-07-11T19:02:48",11,"Маг читает свиток, но удержать ветерана ей не удаётся",101220,null],[107866,"2026-07-11T19:03:14",53,"//она на него пыталась свиток применить?",107865,null],[107867,"2026-07-11T19:03:16",5,"// аххха это паралич на союхника?",101220,null],[107868,"2026-07-11T19:03:21",11,"Понимая что помогать он ей не собирается, она пыталась обездвижить его и драться с двумя слабаками сама",101220,null],[107870,"2026-07-11T19:03:50",53,"неужели ты не видишь? она продалась демону. надо срочно остановить ее. (ветерану)",107865,null],[107872,"2026-07-11T19:04:05",11,"// что с кубами боже где бой",101220,null],[107873,"2026-07-11T19:04:36",53,"//мы мирные решатели из ордена щита божьего с очень длинными и извилистыми языками :3",107872,null],[107874,"2026-07-11T19:05:18",5,"// умелые язычки",107873,null],[107875,"2026-07-11T19:05:20",11,"Ветеран веря вам и понимая что только что пыталась сделать магичка пытается схватить её",101220,null],[107876,"2026-07-11T19:05:24",11,"/r d20+3",101220,null],[107878,"2026-07-11T19:05:33",11,"/r d20+2",101220,null],[107880,"2026-07-11T19:05:41",53,"//слышали бы вы мой злобный смех сейчас :3",101220,null],[107881,"2026-07-11T19:05:47",5,"Дракон щёлкает зубами, руки тянутся к кандалам",101220,null],[107882,"2026-07-11T19:05:48",11,"// ладно делайте что хотите дальше сами я сама себе ногу прострелила трэш",101220,null],[107883,"2026-07-11T19:06:11",11,"— Свяжите эту психопатку пока я ее держу — говорит он вам",101220,null],[107884,"2026-07-11T19:06:29",53,"//а веревки у кого то из нас есть?",101220,null],[107885,"2026-07-11T19:06:31",5,"Гвиндшарх бросается к ней и надевает кандалы.\n\n— Не рыпайся!",101220,null],[107886,"2026-07-11T19:06:59",53,"наконец мы поймали эту демонопоклонницу.",101220,null],[107887,"2026-07-11T19:07:14",5,"// там в зависимости от редакции нужна проверка ловкости рука для надевания",101220,null],[107889,"2026-07-11T19:07:41",11,"// да не надо, ее держат и она 1 выкинула",101220,null],[107890,"2026-07-11T19:07:42",5,"// конечно)",107884,null],[107891,"2026-07-11T19:07:59",53,"//а потом еще и сетью покроем ее :3",107890,null],[107892,"2026-07-11T19:08:15",11,"— А теперь вы, кто вы такие и что здесь забыли? — Аарон обращается к вам",101220,null],[107893,"2026-07-11T19:08:47",5,"Дракон подходит к скинутой ранее сети и засовывает обратно в рюкзак",107892,null],[107895,"2026-07-11T19:09:28",11,"— Без лишних телодвижений — ветеран хватает тебя за руку",101220,null],[107897,"2026-07-11T19:09:40",5,"— Ладно, хорошо — поднимает руки",107895,null],[107898,"2026-07-11T19:09:45",53,"мы прибыли что бы разобратся с демонопоклонниками. до нас дошла информация о том что кто то ккрывает демона. расследование показало что этот демон находится здесь.",107892,null],[107899,"2026-07-11T19:09:46",11,"// он поверил вам только про мага",101220,null],[107900,"2026-07-11T19:09:59",5,"*киваю на каждое слово*",107898,null],[107901,"2026-07-11T19:10:07",11,"// убеждение с помехой",107898,null],[107903,"2026-07-11T19:10:17",53,"+7//",101220,null],[107904,"2026-07-11T19:10:17",11,"// ты не выглядишь как паладин",101220,null],[107907,"2026-07-11T19:10:26",53,"///а, если притворится кем то то без помехи :3",101220,null],[107908,"2026-07-11T19:10:35",53,"//ибо у меня преимущество на такие штуки :3",101220,null],[107911,"2026-07-11T19:10:39",5,"// трушный паладин",101220,null],[107912,"2026-07-11T19:10:52",11,"// дракон тоже таковым не выглядит",101220,null],[107913,"2026-07-11T19:11:00",11,"/r d20+2",101220,null],[107920,"2026-07-11T19:12:01",5,"// зато костюм стильный",101220,null],[107921,"2026-07-11T19:12:10",11,"— Нет тут демонопоклонников, это всего лишь бизнес и \"товар\" скоро заберут отсюда — отвечает он",107898,null],[107922,"2026-07-11T19:12:38",5,"Гвиндшарх кивает на мага, но ничего не говорит",107921,null],[107923,"2026-07-11T19:12:52",11,"— С какой стати я должен отпустить вас, а не заставить замолчать раз вам известно о наших делах?",101220,null],[107924,"2026-07-11T19:13:08",53,"и кто же заберет этот товар? нашему ордену крайне интересно кто является заказчиком этого мерзкого отродья.",107921,null],[107926,"2026-07-11T19:13:36",53,"неужели вы желаете иметь плохие отношения с орденом щита божьего?",107923,null],[107927,"2026-07-11T19:13:49",11,"— Мне это знать не положено, как и вам.",101220,null],[107928,"2026-07-11T19:14:07",11,"/r d20",101220,null],[107930,"2026-07-11T19:14:11",5,"*бормочу невнятно про суд инквизиции*",101220,null],[107931,"2026-07-11T19:15:01",11,"/r d20",101220,null],[107933,"2026-07-11T19:15:16",11,"// а эти кубы уже не вам везут",101220,null],[107934,"2026-07-11T19:15:18",5,"// что ты кидаешь такое",101220,null],[107936,"2026-07-11T19:15:47",11,"Ветеран отлично помнит названия столичных и окружных орденов, что-то ты заврался..",101220,null],[107937,"2026-07-11T19:16:07",53,"//а я и не о столичном ордене :3",107936,null],[107941,"2026-07-11T19:16:28",5,"Вижу по его лицу, что он не верит.\n\n— У меня при себе перстень ордена. Показать?",107936,null],[107942,"2026-07-11T19:16:29",11,"// в столице действуют столичные, так что давай тут не Тойво, не верят тебе",101220,null],[107944,"2026-07-11T19:16:47",11,"// показывай, но тоже убеждение",107941,null],[107946,"2026-07-11T19:16:50",53,"//просто я в душе не ебу названия столичных орденов :3",107942,null],[107947,"2026-07-11T19:17:11",5,"На пальце дракона действительно красуется большое Кольцо-печатка с драконьей головой.\n\n/r +0",101220,null],[107948,"2026-07-11T19:17:12",53,"//я могу скрытно подать кошке знак вырубить мужика?",101220,null],[107949,"2026-07-11T19:17:15",5,"/roll@roll_bot",101220,null],[107951,"2026-07-11T19:17:26",11,"Пока вы болтали маг высвободилась из кандалов и открыла клетку :3",107929,null],[107952,"2026-07-11T19:17:39",5,"// ммм...",107951,null],[107955,"2026-07-11T19:18:03",11,"// там ведь сложность 15 и наличие инструментов?",101220,null],[107956,"2026-07-11T19:18:37",5,"// инструментами да",107955,null],[107957,"2026-07-11T19:19:02",5,"// иначе 20",101220,null],[107959,"2026-07-11T19:19:29",53,"*голос полон стали и гнева*\nчертовы демонопоклонники.\nда предстанете же вы пред судом божьим. именем святого ордена - ордена щита божьего я приказываю вам сдатся и предстать на суде пред господом нашим.",101220,null],[107960,"2026-07-11T19:19:34",5,"— Демон! Она выпустила демона! К оружию!",101220,null],[107961,"2026-07-11T19:19:36",11,"// допустим есть, бросок был 17+2",101220,null],[107964,"2026-07-11T19:19:56",5,"// окей, допустим",107961,null],[107969,"2026-07-11T19:20:38",11,"— Идиотка! — воскликнул мужик и достал оружие из ножен",101220,null],[107970,"2026-07-11T19:20:40",53,"*повернулся к дракоше*\n\nсхватить демона.",101220,null],[107972,"2026-07-11T19:20:44",53,"*достаю меч*",101220,null],[107975,"2026-07-11T19:21:15",5,"— Так точно, капитан!",107970,null],[107976,"2026-07-11T19:21:22",5,"*достал сеть*",101220,null],[107977,"2026-07-11T19:21:30",5,"*кидаю на демона если можно*",101220,null],[107979,"2026-07-11T19:21:57",11,"Все видят как черная тень выбирается из клетки и тело мага начинает мерцать на месте",101220,null],[107987,"2026-07-11T19:23:14",53,"//вот вам даже озвучка",107985,null],[107988,"2026-07-11T19:23:39",11,"/r d20+2",101220,null],[107989,"2026-07-11T19:23:55",11,"//иня короче снова",101220,null],[107991,"2026-07-11T19:24:04",53,"+2//",101220,null],[107992,"2026-07-11T19:24:20",11,"/roll d20+2\n/roll d20+5",101220,null],[107994,"2026-07-11T19:24:33",11,"// два Крита жесть",101220,null],[107995,"2026-07-11T19:24:52",5,"/r +4",101220,null],[107997,"2026-07-11T19:25:25",11,"// в статы лезть не буду, но весь физ урон по магу режется в половину",101220,null],[107998,"2026-07-11T19:25:32",11,"/r d20+1",101220,null],[108000,"2026-07-11T19:26:51",53,"//даже от магического оружия?",107997,null],[108001,"2026-07-11T19:27:18",11,"// нет, это маг урон",101220,null],[108006,"2026-07-11T19:28:04",11,"Вокруг мага собираются разряды, а затем громовая Волна устремляется к вам",101220,null],[108007,"2026-07-11T19:28:07",11,"// спас тела",101220,null],[108010,"2026-07-11T19:28:16",5,"// можно список ини новый?",101220,null],[108011,"2026-07-11T19:28:22",5,"/r +2",101220,null],[108018,"2026-07-11T19:29:35",11,"Маг \nГвинди\nДед(колеблется)\nДжон\nЛуна",101220,null],[108019,"2026-07-11T19:29:45",11,"/r d20",101220,null],[108022,"2026-07-11T19:30:10",53,"//ветеран?",108018,null],[108025,"2026-07-11T19:30:48",11,"/r d8 Гвин\n/r d8 Джон\n/r 2d8 Дед",101220,null],[108027,"2026-07-11T19:30:54",11,"// урон фиксируем",101220,null],[108029,"2026-07-11T19:31:28",53,"//да я прям притягиваю молнии.  можно от разряда у меня с волос маскировка слетит?",108026,null],[108030,"2026-07-11T19:31:52",11,"Маг оглядывается и выбирает путь отхода. Маленький тоннель в котором ее точно не смогут окружить отлично подходит и она отступает туда",101220,null],[108032,"2026-07-11T19:32:03",5,"// провокации?",108030,null],[108033,"2026-07-11T19:32:31",11,"// а она не была в мили с вами",101220,null],[108034,"2026-07-11T19:32:44",11,"// как бы то ни было ход",101220,null],[108035,"2026-07-11T19:32:47",5,"// ладно, всё равно у меня в руках сеть, бить нечем",108033,null],[108041,"2026-07-11T19:33:27",5,"// свободное действие осталось, типа сеть заранее взял?",101220,null],[108043,"2026-07-11T19:33:38",11,"— В нее что ли демон вселился? — Дед отлетел обратно откуда пришел и отряхивается",101220,null],[108044,"2026-07-11T19:33:50",11,"// заранее да",108041,null],[108045,"2026-07-11T19:33:52",5,"— Она одержима! Задержать!",101220,null],[108049,"2026-07-11T19:34:20",5,"/r +8 подхожу ближе и кидаю сеть",101220,null],[108051,"2026-07-11T19:34:38",53,"*мои волосы принимают седой окрас а глаза слегка поблескивают в темноте от удара молнии*",101220,null],[108053,"2026-07-11T19:35:11",5,"// свободным достал щит, и бегу к ней вплотную становлюсь",101220,null],[108054,"2026-07-11T19:35:19",11,"// с помехой",108050,null],[108055,"2026-07-11T19:35:32",11,"// я говорила про физ урон и про тень",101220,null],[108056,"2026-07-11T19:35:47",5,"// сеть без урона",101220,null],[108057,"2026-07-11T19:35:49",53,"кхык!.. проклятый жемонопоклонник!\n\n*направляю меч в сторону врага*\n\nтебе не удастстя сбежать!\n\n\n//мне этим ударом снесли половину хп :D",101220,null],[108059,"2026-07-11T19:36:02",5,"// все броски по ней с помехой? типа мерцания?",101220,null],[108060,"2026-07-11T19:36:03",11,"// я знаю, но ты бросаешь сеть в тень",108056,null],[108062,"2026-07-11T19:36:21",11,"// ладно Лакер окей",101220,null],[108063,"2026-07-11T19:36:30",5,"// она опутана",101220,null],[108065,"2026-07-11T19:37:04",11,"// ну я хотела упросить, если есть урон только -физ урон, если физ действия без урона помеха",108059,null],[108066,"2026-07-11T19:37:20",11,"// окей",108053,null],[108067,"2026-07-11T19:37:25",11,"// ход Джона",101220,null],[108068,"2026-07-11T19:37:26",5,"// ход",101220,null],[108069,"2026-07-11T19:37:39",11,"Дед растерян и ты в целом ход ему загородил",101220,null],[108070,"2026-07-11T19:38:16",53,"//демон вселился в мага или он еще в комнате?",101220,null],[108071,"2026-07-11T19:38:29",11,"// вопрос сразу, мне нужно помогать кошкой или не стоит? Я вам опыт вычту за это очевидно",101220,null],[108072,"2026-07-11T19:38:44",11,"// ты видел что вселился",108070,null],[108074,"2026-07-11T19:38:45",5,"// да можешь посидеть на шкафе впринципе",108071,null],[108075,"2026-07-11T19:39:30",11,"// чисто Джонатан \n\nhttps://youtube.com/shorts/-qY_IE5OeUg?si=FIRBlLwCTkQRpOAN",108074,null],[108076,"2026-07-11T19:39:53",53,"отродье, лежи смирно! \n(запугивание на демонюку :D)",108072,null],[108078,"2026-07-11T19:40:00",53,"//могу кинуть?",101220,null],[108079,"2026-07-11T19:40:11",11,"// чем пугаешь?",101220,null],[108081,"2026-07-11T19:40:56",11,"// ну ты демона пугаешь, это 20 будет я хз",101220,null],[108084,"2026-07-11T19:41:31",53,"// мечем, словами и деревянным священным символом (предположительно крестом :D)  \nну и паладинистой мордой",101220,null],[108085,"2026-07-11T19:41:54",53,"ну с +7 это не слишком сложно :3//",108081,null],[108086,"2026-07-11T19:41:59",53,"//преимущества/помехи?",101220,null],[108087,"2026-07-11T19:41:59",11,"// пробуй",101220,null],[108089,"2026-07-11T19:42:18",11,"// ой ладно идите в баню",101220,null],[108090,"2026-07-11T19:42:30",53,"//ебать, да вы батюшка паладин",108088,null],[108092,"2026-07-11T19:43:00",11,"Луна просто сидит на шконке и машет ножками",101220,null],[108093,"2026-07-11T19:43:31",11,"// сколько у вас хп?",101220,null],[108094,"2026-07-11T19:43:41",5,"// 23",101220,null],[108095,"2026-07-11T19:43:47",53,"//8 из 15",108093,null],[108096,"2026-07-11T19:43:59",53,"//я фанера :D",108095,null],[108097,"2026-07-11T19:44:45",11,"Джонатан бомж выглядит слишком убедительно, даже тень демона боится его // помехи по нему",101220,null],[108098,"2026-07-11T19:45:38",11,"/r -d20+5",101220,null],[108100,"2026-07-11T19:45:50",11,"// помеха за сеть",101220,null],[108101,"2026-07-11T19:45:55",53,"//мои серебристые волосы и светящиеся глаза ояень убедительны :3",108097,null],[108102,"2026-07-11T19:46:10",11,"Маг пытается замахнуться кинжалом на драконорожденного, но сеть сковывает движения",101220,null],[108104,"2026-07-11T19:46:59",53,"*голос мой звучит словно гром от молота божьего на суде его, а глаза пронзают демона пробирая его до самых костей*",108097,null],[108108,"2026-07-11T19:47:58",5,"// мне ходить?",101220,null],[108112,"2026-07-11T19:48:41",11,"// паладин фанерный",108104,null],[108115,"2026-07-11T19:48:53",5,"— Покайся, грешника!\n\nСковываю кандалами.",101220,null],[108116,"2026-07-11T19:48:59",5,"/r +4 ловкость рук",101220,null],[108118,"2026-07-11T19:49:06",11,"// встречный бросок?",101220,null],[108119,"2026-07-11T19:49:13",5,"// там сложность 13",101220,null],[108120,"2026-07-11T19:49:18",5,"// я не прошёл",101220,null],[108121,"2026-07-11T19:49:56",5,"// могу проскользнуть мимом опутанной сетью грешницы и зайти в спину?",101220,null],[108122,"2026-07-11T19:50:02",11,"Руки как тень просачиваются сквозь кандалы",101220,null],[108123,"2026-07-11T19:50:21",11,"// нет, спутанный даёт только помеху, провокация останется",101220,null],[108124,"2026-07-11T19:50:30",5,"// с провокацией",101220,null],[108125,"2026-07-11T19:50:35",11,"// да",101220,null],[108126,"2026-07-11T19:50:38",5,"// но я юзну отход хд",101220,null],[108127,"2026-07-11T19:50:42",5,"// бонусным плута",101220,null],[108128,"2026-07-11T19:51:12",5,"Дракон проскочил мимо мага и стоит сзади, отрезая путь к бегству.",101220,null],[108129,"2026-07-11T19:51:13",5,"// ход",101220,null],[108130,"2026-07-11T19:51:14",11,"// опиши это блин как ты в узком тоннеле проходишь ей по голове избегая провкации",101220,null],[108131,"2026-07-11T19:51:24",5,"// оке",101220,null],[108132,"2026-07-11T19:51:30",11,"// ржу",101220,null],[108136,"2026-07-11T19:52:46",53,"//у меня кстати с собою самовар😂  можем приложить хорошенько им по ипалу 😄",108132,null],[108137,"2026-07-11T19:52:48",5,"По пути дракон замечает вскинутую руку с кинжалом, но всем телом жмётся к магу. Рука поднята наверх, а она зажата у стены. Дракон смотрит ей в глаза, подмигивает и отходит в проход.\n\nТелепатией:\n\"Отринь демона! И мы поговорим по-другому!\"",101220,null],[108138,"2026-07-11T19:53:31",53,"//ах ты ж чьëртов демонопоклоннек",108137,null],[108140,"2026-07-11T19:53:46",5,"// демон опорочил невинную волшебницу",101220,null],[108141,"2026-07-11T19:54:09",53,"//а вообще надо бы деда и мага приложить самоваром 😀",101220,null],[108142,"2026-07-11T19:54:10",11,"Маг будто не слышит тебя, ноль реакции",101220,null],[108143,"2026-07-11T19:54:14",11,"// ход Сереги",101220,null],[108145,"2026-07-11T19:54:39",11,"// мирного решения с магом не будет",101220,null],[108147,"2026-07-11T19:55:58",11,"// стоп, Эл, у тебя сколько сетей было?",101220,null],[108148,"2026-07-11T19:56:00",53,"*кричу деду*\nчего стоишь! хватай колдунью и отродье что в нее вселилось! иль подохнуть здесь возжелал ты?\n\n(пытаюсь вывести из ступора и заодно направить в бой. по возможности дать действие помощь)",101220,null],[108149,"2026-07-11T19:56:08",5,"// 5. Ещё 3 осталось",108147,null],[108151,"2026-07-11T19:56:35",11,"// заставляешь работать за вас?",108148,null],[108152,"2026-07-11T19:56:38",5,"// я потратил всё золото на расходники. И предпоследний золотой отдал троглодиту на выпивку",101220,null],[108153,"2026-07-11T19:56:53",11,"// я могу и луной помочь просто попроси:3",101220,null],[108154,"2026-07-11T19:57:02",53,"//ну а хули он стоит. пусть хватает демона под моим руководством :3",108151,null],[108156,"2026-07-11T19:57:06",11,"— Что же мне скажет мастер если я сам мага убью?",101220,null],[108157,"2026-07-11T19:57:09",53,"//не, я именно деда запрячь хочу",108153,null],[108159,"2026-07-11T19:57:39",5,"// можешь ещё кандалы ему передать. Пусть делает арест",101220,null],[108160,"2026-07-11T19:57:53",53,"а что он тебе скажет коли ты умрешь здесь сам! живо хватай отродье пока оно не сбежало! я проведу ритуал изгнания твари!",108156,null],[108161,"2026-07-11T19:58:07",11,"// говори как перс",108159,null],[108162,"2026-07-11T19:58:20",53,"//я бедный чорт, кандалы есть ток у тебя :3",108159,null],[108163,"2026-07-11T19:58:29",11,"// он тебе дал одни",108162,null],[108165,"2026-07-11T19:58:34",5,"— Дай ему кандалы! Не зря же вам раздал!",101220,null],[108166,"2026-07-11T19:58:42",53,"//хмм.. я как то и забыл",108163,null],[108167,"2026-07-11T19:59:34",53,"ты прав. кандалы ему не помешают. \n*даю деду кандалы чтоб он схватил мага*",108165,null],[108168,"2026-07-11T20:00:08",11,"— Я помогу — Дед берет кандалы из твоих рук и идёт к магу",101220,null],[108169,"2026-07-11T20:00:12",11,"// что там кидать?",101220,null],[108170,"2026-07-11T20:00:18",5,"// ловкость рук сл 13",101220,null],[108171,"2026-07-11T20:00:23",11,"/r d20+1",101220,null],[108174,"2026-07-11T20:00:48",11,"Старые руки мастера сковывают тень как бы та не брыкалась",101220,null],[108175,"2026-07-11T20:01:10",11,"— Как вы с нее демона изгонять собираетесь? — спрашивает он",101220,null],[108176,"2026-07-11T20:01:51",53,"словом божьим. \n(он к нам повернут?)",108175,null],[108177,"2026-07-11T20:01:52",11,"Магическая тьма из клетки в которой был заперт демон исчезла ещё когда маг открыла ее",101220,null],[108178,"2026-07-11T20:02:03",11,"// к тебе спиной",108176,null],[108179,"2026-07-11T20:02:26",53,"*подаю знак кошке что бы та ловила демона, а сам пытаюсь вырубить мужмка самоваром*",101220,null],[108181,"2026-07-11T20:02:42",11,"// демон скован и в сети",101220,null],[108183,"2026-07-11T20:03:00",11,"// но всё ещё демон, маг таковой останется если ничего не сделать",101220,null],[108185,"2026-07-11T20:03:25",53,"//для начала хочу усыпить лишнего свидетеля :3",108183,null],[108186,"2026-07-11T20:03:40",53,"//а дальше вместе с кошкой и ящером решить проблему мага",101220,null],[108187,"2026-07-11T20:03:51",11,"// валяй",101220,null],[108189,"2026-07-11T20:04:03",53,"//что кидат на усыпление самоваром в затылок?",108187,null],[108190,"2026-07-11T20:04:10",11,"// спас силы на силу будет",101220,null],[108192,"2026-07-11T20:04:22",11,"// можешь с преимуществом за скрытность",101220,null],[108194,"2026-07-11T20:04:50",53,"//тоесть я спас силы кидаю?",108190,null],[108195,"2026-07-11T20:04:53",11,"// ну ты пытаешься оглушить крепкого мужика, он возможно спокойно перенесет это",101220,null],[108198,"2026-07-11T20:05:16",11,"// опиши",101220,null],[108199,"2026-07-11T20:05:28",11,"/r d20",101220,null],[108201,"2026-07-11T20:05:34",11,"//успех",101220,null],[108202,"2026-07-11T20:06:09",53,"*я незаметно достаю из мешка самовар и подняв его над головой размашистым ударом опускаю тот на голову деда пытаясь усыпить того. (но стараюсь при этом не насмерть)*",101220,null],[108203,"2026-07-11T20:07:27",11,"В проходе сидит скованный проклятый маг в сетях, за ним стоит драконорожденный. На мага сверху падает оглушенный самоваром Ветеран. Он явно не ожидал такой подляны от балабола из-за спины. А позади деда стоит Джонатан с самоваром",101220,null],[108204,"2026-07-11T20:07:33",11,"Луна аплодирует",101220,null],[108205,"2026-07-11T20:07:52",53,"что дальше делаем, мэри?",101220,null],[108206,"2026-07-11T20:07:55",11,"— Ну и цирк — она выходит из тени — а что с этой делать будете?",101220,null],[108207,"2026-07-11T20:08:12",53,"нам же демона надо доставить? можем и ее усыпить.",108206,null],[108208,"2026-07-11T20:08:15",5,"— Демона изгнать надо! Знаете как?",101220,null],[108209,"2026-07-11T20:08:37",5,"— Хорошая мысль. Её и привезём. Только кляпа не хватает",108207,null],[108210,"2026-07-11T20:08:51",53,"//думаю джонатан с самоваром выглядит даде страшнее чем джонатан притворяющийся паладином :D",101220,null],[108211,"2026-07-11T20:08:57",11,"— Артефакт там где они были, я уже проверила — она указывает на комнату откуда вышли маг с ветераном",101220,null],[108212,"2026-07-11T20:09:10",5,"— Другой артефакт?",108211,null],[108213,"2026-07-11T20:09:13",11,"// не забывай про свою снарягу",108208,null],[108216,"2026-07-11T20:09:30",5,"// помню, тогда занимаюсь",108213,null],[108217,"2026-07-11T20:09:37",11,"// чем?",101220,null],[108218,"2026-07-11T20:09:51",5,"Дракон полапал мага и конфисковал воровские инструменты у демона",101220,null],[108219,"2026-07-11T20:09:55",53,"хмм..\nзначит демон нам не нужен?",108211,null],[108221,"2026-07-11T20:10:07",53,"или все таки заберем?...",101220,null],[108222,"2026-07-11T20:10:16",53,"*звуки интенсивной мыслительной деятельности*",101220,null],[108224,"2026-07-11T20:10:41",5,"Дальше затащил мага в комнату, сделал кляп из рукава её одежды",101220,null],[108225,"2026-07-11T20:10:51",11,"Маг брыкается и дёргается\n\n— Возможно Дин и правда хотел что-то узнать об этом, стоит ее взять — Отвечает Луна",101220,null],[108226,"2026-07-11T20:11:01",53,"*согласно киваю*",108225,null],[108227,"2026-07-11T20:11:18",5,"— Свяжите ещё для надёжности. А я заберу сеть",101220,null],[108228,"2026-07-11T20:11:25",53,"если я ее усыплю, демон останется в ней?\n*держу самовар наготове*",108225,null],[108231,"2026-07-11T20:12:00",11,"— Да куда уже больше, она и так в сетях и кандалах..",101220,null],[108232,"2026-07-11T20:12:30",5,"— Тогда она на тебе. Ты уже осмотрела всё тут?",108231,null],[108233,"2026-07-11T20:12:43",11,"Луна связывает мага дополнительно \n\n— Кто понесет? — кокетливым тоном спрашивает она",101220,null],[108234,"2026-07-11T20:12:43",5,"*вернул 1 сеть с пола пока*",101220,null],[108235,"2026-07-11T20:12:50",11,"// порвана, дед порезал",108234,null],[108236,"2026-07-11T20:12:53",5,"*и с мага тоже*",108233,null],[108237,"2026-07-11T20:13:01",5,"// окей",108235,null],[108238,"2026-07-11T20:13:10",53,"*пытаюсь связать демона чем нибудь похожим на веревку*",108232,null],[108240,"2026-07-11T20:13:29",11,"— Нет, вышла когда ветеран пошел за \"паладином\"",108232,null],[108241,"2026-07-11T20:13:42",11,"От слова паладин скрученный маг задергалась",101220,null],[108242,"2026-07-11T20:13:55",53,"и все же брыкатся будет меньше если будет спать.",101220,null],[108243,"2026-07-11T20:14:41",5,"— Я понесу. Пушинка!",108233,null],[108244,"2026-07-11T20:14:58",11,"*кивок* \n\n— уходим?",101220,null],[108245,"2026-07-11T20:15:04",5,"// это да? надо искать тут что-то?",108240,null],[108246,"2026-07-11T20:15:20",11,"// от вас зависит",101220,null],[108247,"2026-07-11T20:15:23",53,"*беру на себя мужика*",101220,null],[108248,"2026-07-11T20:15:43",11,"// что с дедом делаешь? Он рано или поздно очнётся и скинет всё на вас",101220,null],[108249,"2026-07-11T20:15:49",5,"— А он тебе зачем? Луна, ты говорила про зелье стирания памяти",108247,null],[108250,"2026-07-11T20:15:56",53,"*связываю и утаскиваю с нами*",108248,null],[108251,"2026-07-11T20:16:10",53,"да?\nнет еще такого?",108249,null],[108254,"2026-07-11T20:16:38",11,"— Хуху, ты помнишь — она улыбается и достает бутылек из сумки, а затем протягивает тебе",101220,null],[108255,"2026-07-11T20:16:38",5,"Дракон всё же заходит в комнату, где сидела эта пара и смотрит, что там есть.",101220,null],[108256,"2026-07-11T20:16:43",5,"/r +4 восприятие",101220,null],[108258,"2026-07-11T20:17:02",53,"*ложу деда на место*",108254,null],[108259,"2026-07-11T20:17:16",11,"До дракона наконец-то доходит что взгляд который палил ему в спину и был настоящим демоном, а маг просто проклята",101220,null],[108261,"2026-07-11T20:17:51",11,"— Напоите деда что бы забыл сегодняшний денёк и вы чисты",101220,null],[108263,"2026-07-11T20:18:32",5,"— Погодите! Демон не в маге! Он где-то здесь, смотрит на меня!\n\nОглядываюсь, ищу его",108259,null],[108264,"2026-07-11T20:18:36",11,"// за Крит можешь без бросков расследовать дальше",101220,null],[108266,"2026-07-11T20:18:57",5,"// а  вещичек в их комнате нет?",108264,null],[108267,"2026-07-11T20:19:24",53,"*забираю оружие деда*\nлишним не будет.",108261,null],[108268,"2026-07-11T20:19:43",11,"Ты идёшь туда откуда тебе смотрели в спину. Твое внимание сразу же привлекает странный черный камушек витающий в стеклянной колбе, на столе, посреди комнаты.",101220,null],[108270,"2026-07-11T20:20:24",11,"// + длинный, + короткий мечи и + тяж арбалет, обычные все",108267,null],[108271,"2026-07-11T20:20:34",5,"— Что это такое? \n\nДракон напрягается и вспоминает всё, что знает об артефактах с демонами.",101220,null],[108272,"2026-07-11T20:20:46",53,"//ура! я больше не бедный :3",101220,null],[108273,"2026-07-11T20:20:57",53,"*и денежки тоже*",108270,null],[108274,"2026-07-11T20:21:02",11,"Свиток позволяет тебе почувствовать магию телепортации что доноситься от камушка",101220,null],[108275,"2026-07-11T20:21:12",11,"// ещё и зп отобрали..",108273,null],[108276,"2026-07-11T20:21:13",53,"*и вообще ищу что ценного и полезного у него есть*",108273,null],[108277,"2026-07-11T20:21:31",53,"ну не зря ж я смену отработал :3//",108275,null],[108278,"2026-07-11T20:21:35",11,"// ты обобрал его до липки",101220,null],[108279,"2026-07-11T20:21:58",11,"// следы",108274,null],[108280,"2026-07-11T20:22:01",53,"а это у нас оплата бесплатной рабочей силы.",108275,null],[108281,"2026-07-11T20:22:18",11,"// поджёг склад и просит платы",101220,null],[108282,"2026-07-11T20:22:21",5,"— Чувствую магию, он меня телепортирует, если коснусь?  Кто-нибудь знает, как его безопасно взять с собой?",108274,null],[108283,"2026-07-11T20:23:10",11,"— Это и есть артефакт полагаю, говоришь след магии телепортации? — Луна с гордостью погладила Джонатана за воровские привычки и пошла к тебе смотреть на камушек",101220,null],[108284,"2026-07-11T20:23:33",5,"— Да. Бери на свой риск!",108283,null],[108285,"2026-07-11T20:24:09",11,"// что Джонатан делает?",101220,null],[108286,"2026-07-11T20:24:46",11,"Вдохновлённая Джонатаном она обобрала мага прежде чем подойти к дракону",101220,null],[108287,"2026-07-11T20:25:20",53,"//уборку дома делает",108285,null],[108288,"2026-07-11T20:25:31",53,"*помогаю товарищам чем смогу*",101220,null],[108289,"2026-07-11T20:26:39",53,"*остаюсь максимально невозмутимым, от меня все еще исходит паладинистая аура*",101220,null],[108290,"2026-07-11T20:27:14",11,"// спас тела от всех",101220,null],[108291,"2026-07-11T20:27:21",5,"/r +2",101220,null],[108293,"2026-07-11T20:27:27",11,"/r d20",101220,null],[108295,"2026-07-11T20:30:01",11,"// от Сереги тоже",101220,null],[108297,"2026-07-11T20:31:21",53,"подметаю пол//",108295,null],[108298,"2026-07-11T20:31:25",53,"//могу исчезать",101220,null],[108299,"2026-07-11T20:33:38",11,"— Если демон ушел, а от камня исходит магия телепортации полагаю это может быть связано — табакси говорила это всматриваясь в темный минерал.\n\nЕе алые глаза расширились, в них расползались прожилки черного. Кошачьи ушки прижались к затылку и она протянула руки к стеклу. Стекло было единственной преградой между вами и артефактом и теперь вы чувствуете слабые порывы ветра и последождевую свежесть от него..",101220,null],[108300,"2026-07-11T20:34:50",53,"*подхожу к кошке и пытаюсь привести ее в сознание*\n\nшепчу на ухо: луна? ты в порядке?",108299,null],[108303,"2026-07-11T20:40:13",11,"Луна убирает крышку и наклоняется над тёмным камнем, что так и остался витать в воздухе. Не оглядываясь она осторожно касается поверхности камня. \n\nНа первый взгляд ничего не происходит. Затем из глубины чёрного минерала начинают проступать тонкие лиловые прожилки, похожие на раскалённые трещины. Они медленно расползаются по всей поверхности. Дышать становится тяжело всем, словно в комнате не хватает воздуха. \n\nВ следующее мгновение тени вокруг вас начинают двигаться... но не вслед за светом. Они тянутся к камню, словно живые, и сплетаются в чёрную воронку. Мир вокруг будто сминается.\nСтены изгибаются, пол исчезает из-под ног, а пространство превращается в бесконечный тоннель из лилового дыма и извивающихся теней. На короткое мгновение вам кажется что за вами кто-то наблюдает.",101220,null],[108304,"2026-07-11T20:41:02",11,"А затем снова озоновая свежесть, ветер и шелест листвы, дышать становится проще. В ушах звучит едва различимый шёпот на незнакомом языке. Стоит попытаться вслушаться, как слова тут же ускользают из памяти.",101220,null],[108305,"2026-07-11T20:41:03",5,"— Луна, запри его! Пускай Дин разбирается с демоном!",108303,null],[108306,"2026-07-11T20:41:16",11,"// ты спас не прошел, чилл",101220,null],[108307,"2026-07-11T20:41:29",5,"// а, там выключает?",101220,null],[108308,"2026-07-11T20:41:43",11,"// это демонический арт",101220,null],[108311,"2026-07-11T20:43:40",53,"*смотрю на глаза луны, если с ними что то не так закрываю крышку и оттягиваю луну от артефакта*",108303,null],[108313,"2026-07-11T20:44:37",5,"// чиллю",101220,null],[108314,"2026-07-11T20:44:38",11,"Мир вернулся так же внезапно, как исчез. Вы обнаруживаете себя в лесу недалеко от города. Под ногами вновь оказывается твёрдая земля.\n\nОднако голова тяжелеет, желудок словно переворачивается, а руки на долю секунды перестают слушаться. Во рту остаётся слабый металлический привкус крови.\n\nДжонатан и Луна чувствуют себя неважно, но стоят на ногах, а Гвиндшарх падает на землю [лежащий ничком]",101220,null],[108316,"2026-07-11T20:45:13",5,"// можно действовать?",101220,null],[108317,"2026-07-11T20:45:34",53,"кхх.. ты как?...",108314,null],[108319,"2026-07-11T20:45:49",11,"Луна первой делает глубокий вдох и, слегка поморщившись, произносит:\n\n— В порядке, но купилась на демоническую шутку\n\nОна разжимает руку в которой все ещё находится черный камушек. Под вашими ногами лежит второй такой же",108300,null],[108320,"2026-07-11T20:45:53",53,"//артефакт с нами?",108314,null],[108321,"2026-07-11T20:45:55",5,"— Не очень. Спасибо за заботу!",108317,null],[108323,"2026-07-11T20:46:23",5,"Гвиндшарх встаёт и отряхивается от пыли.\n\n— Такой костюм испачкал!",101220,null],[108324,"2026-07-11T20:46:51",11,"— Этот демон.. сбежал полагаю.. в таком состояние нам за ним не угнаться точно — Она подымает второй камушек — камни телепортации с настройкой на местность",101220,null],[108325,"2026-07-11T20:47:09",5,"— Удобная вещь. Очень удобная!",108324,null],[108326,"2026-07-11T20:47:10",11,"— Нужно доложить все Дин'Рилу",101220,null],[108327,"2026-07-11T20:47:11",53,"что это было? \n*потелу начинает идти дрожь, а паладинистая аура проходит* \nухх... думал помру когда в нас зарядили молнией.. \n*осматриваю отметины оставшиеся от удара молнии*",108319,null],[108328,"2026-07-11T20:47:33",5,"— А где волшебница?",101220,null],[108329,"2026-07-11T20:47:51",53,"*киваю*",108326,null],[108330,"2026-07-11T20:48:03",11,"Кошка прячет камушки в карман, а затем смотрит на тебя и улыбается\n\n— Я тоже так умею — она достает рапиру по которой ходят разряды тока",108327,null],[108333,"2026-07-11T20:48:30",53,"//ля, так и хочется погладить",108330,null],[108334,"2026-07-11T20:48:34",11,"— Полагаю все там же",108328,null],[108335,"2026-07-11T20:48:47",53,"а демон?",101220,null],[108336,"2026-07-11T20:48:51",11,"// дотянись, коротышка",108333,null],[108337,"2026-07-11T20:48:59",5,"— Чёрт, она запомнила меня!",108334,null],[108338,"2026-07-11T20:49:00",11,"//",108324,null],[108340,"2026-07-11T20:49:20",53,"бить молниями?",108330,null],[108341,"2026-07-11T20:49:26",11,"// ей демон проклятием память исказил, последствий не будет",108337,null],[108343,"2026-07-11T20:50:00",5,"— Да, тогда будем возвращаться?",108326,null],[108344,"2026-07-11T20:50:06",5,"*осмотрелся вокруг*",101220,null],[108345,"2026-07-11T20:50:18",11,"— Типа того — она прячет рапиру обратно в ножны",108340,null],[108347,"2026-07-11T20:50:34",11,"*кивает*",108343,null],[108350,"2026-07-11T20:51:39",5,"— Кстати, Джон! Видел, ты взял у деда тяжёлый арбалет. Можно мне его взять? Дротики это хорошо, но на большой дистанции нужно что-то мощнее",101220,null],[108351,"2026-07-11T20:51:43",11,"// у кошки с Джоном -д4 на броски на час, у Гвинди помеха на первый бросок и -д4 на 4 часа",101220,null],[108355,"2026-07-11T20:52:16",53,"хорошо.",108350,null],[108356,"2026-07-11T20:52:21",53,"*даю ему арбалет*",101220,null],[108358,"2026-07-11T20:52:32",5,"— Спасибо",101220,null],[108362,"2026-07-11T20:52:49",53,"*хрустю спиною и остальными костями* \nпосле такого тяжелого похода не обойтись без какого-нибудь хорошего события.  (кошке)",108347,null],[108363,"2026-07-11T20:52:56",11,"— Не беспокойся о костюме — табакси делает жест рукой и ты вновь чистый и сухой",101220,null],[108364,"2026-07-11T20:53:41",53,"//если получу ап после этого квеста, возьму класс чародея :3  ибо не зря ж меня молния ебанула",101220,null],[108365,"2026-07-11T20:53:41",5,"— Удобно\n\nВерчусь на месте и красуюсь.\n\n— Отличный костюм, не так ли?",108363,null],[108366,"2026-07-11T20:53:50",11,"— Хорошо будет если Дина устроит то что мы устроили — отвечает она, пошли",108362,null],[108367,"2026-07-11T20:54:02",11,"// конечно, я же за него заплатила",108365,null],[108368,"2026-07-11T20:54:17",53,"*киваю и иду за ней наблюдая за намокающей(намокающей же?) шорсткой*",101220,null],[108370,"2026-07-11T20:54:26",11,"— Откуда у тебя этот костюм, Гвинди?",101220,null],[108371,"2026-07-11T20:54:39",11,"// дождь закончился",108368,null],[108373,"2026-07-11T20:54:49",53,"//а.. быстро он..",108371,null],[108374,"2026-07-11T20:54:54",53,"//пизда складу",101220,null],[108375,"2026-07-11T20:55:08",11,"// гроза была для того что бы добавить вам плюс к скрытности кстати",101220,null],[108378,"2026-07-11T20:55:34",5,"— Недавно меня пригласили на почти что королевский приём в городе жрецов, Гелиокроне. Вот для этого и прикупил костюм. С помощью друга.",108370,null],[108383,"2026-07-11T20:56:18",11,"— А, кажется в новостях о тебе и ещё каком-то кентавре писали.. и про суд дварфов..",101220,null],[108387,"2026-07-11T20:56:55",5,"— Да-да, это были мы. Раскрыли одну банду преступников",108383,null],[108388,"2026-07-11T20:57:02",53,"новости?",108383,null],[108390,"2026-07-11T20:57:30",11,"— Да, в газетах писали, и не недооценивайте наши источники",108388,null],[108391,"2026-07-11T20:57:38",53,"//не думаю что джонатан видел такие чудеса общественной инженерии  :3",101220,null],[108392,"2026-07-11T20:57:41",11,"На последних словах она махнула хвостом перед тобой",101220,null],[108393,"2026-07-11T20:58:26",53,"*взгляд ушел за концом хвоста*\n\nчто за газеты? я не так давно путешествую. впервые о таком слышу.",108390,null],[108394,"2026-07-11T20:58:40",5,"— Да. Джон, поищи газеты из Северной Элазии. В них точно будет о нас!",108390,null],[108395,"2026-07-11T20:59:09",11,"— А откуда ты узнаешь о том что в мире происходит? Совсем во тьме живёшь что ли? — кошка прям озадачились",101220,null],[108399,"2026-07-11T21:01:20",53,"от людей вокруг.",108395,null],[108400,"2026-07-11T21:02:02",11,"— Ну вот от нас тоже услышал",101220,null],[108403,"2026-07-11T21:02:42",53,"верно.\nтак что такое эти ваши газеты?",108400,null],[108404,"2026-07-11T21:03:58",11,"Табакси осмотрела вас сверху до ног, а затем озвучила мысли:\n\n— Выглядите потрёпано, лучше отдохните в таверне, а я приду ночью как поговорю с Дином",101220,null],[108405,"2026-07-11T21:04:10",11,"— И, Гвинди, мне ещё нужно достать то что я обещала тебе ранее",101220,null],[108406,"2026-07-11T21:04:16",53,"*подошел чуть ближе к кошке задуичиво добавляю* \nи где их искать?",108403,null],[108408,"2026-07-11T21:04:33",53,"ты тоже выглядишь уставшей. \nточно не нужна помощь?",108404,null],[108409,"2026-07-11T21:04:39",5,"— Хорошо. Я жду!\n\nГвинди улыбнулся в предвкушении.",108405,null],[108410,"2026-07-11T21:05:14",11,"// я думаю от того напишу я вам разговор с дроу или нет ничего не поменяется, только время потрачу, лучше поиграем в таверне и набухаемся а?",101220,null],[108411,"2026-07-11T21:05:35",5,"// давай",101220,null],[108412,"2026-07-11T21:06:01",5,"// кстати получил чуть-чуть болтов к арбалету?",101220,null],[108414,"2026-07-11T21:06:30",11,"— Все в порядке, вот ловите — она достает 10 золотых из нагрудного кармана и кидает вам — оплатите этим, газету себе тоже купи, просвятись",108408,null],[108415,"2026-07-11T21:07:02",53,"*ловлю деньги*",101220,null],[108416,"2026-07-11T21:07:03",11,"Когда ты встал к кошке поближе, то понял что она порядком выше тебя и говорит это смотря сверху вниз",108414,null],[108417,"2026-07-11T21:07:08",53,"//10 на двоих или каждому?",108414,null],[108418,"2026-07-11T21:07:20",11,"// сори я хаваю",101220,null],[108419,"2026-07-11T21:07:33",53,"//мне щас бургеры дадут :3",108418,null],[108420,"2026-07-11T21:07:37",11,"// это только чтоб вы про бухали, так что на двоих, потом норм награды посчитаю",108417,null],[108421,"2026-07-11T21:07:43",53,"приятного аппетита//",108418,null],[108422,"2026-07-11T21:07:52",11,"// шпашибо, тебе тоже заранее",108421,null],[108423,"2026-07-11T21:08:09",53,"//нам дадут больше 300 опыта?",108420,null],[108424,"2026-07-11T21:08:24",11,"// в общем дуйте в таверну, а я посчитаю награды и спрошу у Харда на счёт опыта",101220,null],[108425,"2026-07-11T21:08:26",53,"//хочу сразу до чара повысится чтоб в таверне начать магичить :3",101220,null],[108426,"2026-07-11T21:08:42",5,"// идём в таверну",101220,null],[108427,"2026-07-11T21:08:58",5,"По пути дракон спросил Джона\n\n— Хочешь, заставлю тебя улыбнуться?",101220,null],[108428,"2026-07-11T21:09:05",11,"// ты все классы хочешь?",108425,null],[108430,"2026-07-11T21:11:09",53,"//не, чисто по пути собераю те что подходят",108428,null],[108431,"2026-07-11T21:11:35",53,"как? *полнял бровь*",108427,null],[108433,"2026-07-11T21:11:53",53,"//в меня ебанула молния, стал чародеем :3",101220,null],[108434,"2026-07-11T21:12:02",11,"// а чё не паладином?",101220,null],[108435,"2026-07-11T21:12:18",53,"//а паладин он от бога а не от молнии :3",108434,null],[108436,"2026-07-11T21:12:32",5,"Гвиндшарх достал волшебную палочку и улыбнулся. Затем торжественно сказал:\n\n— Улыбнись!\n\nТы не чувствуешь никакого эффекта, но дракон выглядит комично.",108431,null],[108438,"2026-07-11T21:14:24",53,"*лицо стало выглядет бледнее, глаза закатились, я падаю на спину*",108436,null],[108441,"2026-07-11T21:15:01",11,"// несите оскар",101220,null],[108445,"2026-07-11T21:15:59",5,"— Эй! Ты в порядке?\n\nДракон обеспокенно наклонился над тобой",108438,null],[108448,"2026-07-11T21:16:15",53,"*хватаю дракошу за плечи и поднимаюсь к его лицу издавая страшный звук*\n\n*спустя пару секунд начинаю ржать*",101220,null],[108449,"2026-07-11T21:18:03",5,"Гвиндшарх удивлённо смотрит на тебя, а потом начинает смеятся тоже",101220,null],[108451,"2026-07-11T21:18:54",53,"*вытираю смехуяшную слезу с глаза и поднимаюсь*\n\nну как, полегчало?",101220,null],[108452,"2026-07-11T21:19:39",5,"— Да. Это лучше, чем магическая палочка, Джон!\n\nДракон улыбается во весь рот",101220,null],[108453,"2026-07-11T21:20:44",53,"ага. пожтому я и актер (:\n\nхорошо взламываешь замки. как тебе мое актерское мастерство? хорошо же паладина сыграл?",108452,null],[108455,"2026-07-11T21:21:33",5,"— Весьма натурально. Я даже сам поверил.",101220,null],[108457,"2026-07-11T21:22:32",53,"и все же жаль что упустили демона.",101220,null],[108458,"2026-07-11T21:22:55",5,"— Всё же мы не паладины. Может, ещё будет шанс",101220,null],[108459,"2026-07-11T21:23:18",5,"— Хочешь, подарю тебе мой дротик? На память",101220,null],[108460,"2026-07-11T21:23:22",53,"ага. не желаешь чаю?",108458,null],[108461,"2026-07-11T21:23:42",5,"— Давай. А молоко есть? Хочу смешать",108460,null],[108462,"2026-07-11T21:23:56",53,"тогда я тебе сделаю фигурки выглядящие как мы трое. да и луне и себе такие же. тоже на память.",108459,null],[108463,"2026-07-11T21:24:06",53,"нет. только самовар и чай.",108461,null],[108464,"2026-07-11T21:24:35",5,"— Ого, я бы поглядел! Ты умеешь вырезать из дерева?",108462,null],[108465,"2026-07-11T21:24:58",5,"— Тогда идём в таверну лучше.",108463,null],[108466,"2026-07-11T21:25:08",53,"*киваю и по пути начинаю вырезать фигурки из бруска дерева*",108464,null],[108467,"2026-07-11T21:25:51",5,"— У меня есть инструменты, но я сам умею только базовые вещи. Поучи меня немного, хорошо?\n\nГвиндшарх любознательно смотрит на движения Джона",108466,null],[108468,"2026-07-11T21:26:37",53,"*киваю и продолжаю, обьясняя что да как делаю*",108467,null],[108469,"2026-07-11T21:27:01",5,"*Слушает, достал свой резак и пробует на бруске повторять*",108468,null],[108471,"2026-07-11T21:31:50",53,"//обед пообедан :3",101220,null],[108472,"2026-07-11T21:33:04",53,"//а теперь пологаю в таверну?",101220,null],[108500,"2026-07-11T21:53:15",11,"@elsio28 Сергей",101220,null],[108501,"2026-07-11T21:53:15",11,"Джонатан (480 опыта): ограбил и избил сразу двоих работяг (головореза и ветерана) +100зм. Так же нашел: \n- ручной топор;\n- двуручный меч;\n- тяжёлый арбалет и 20 болтов;\n- короткий меч\n- кирка \n\nГвиндшарх (450 опыта):\nВ награду от Луны получает 90 зм (зп мага) и \n- свиток обнаружения магии;\n- тяжёлый арбалет с 20 болтами (с лута Джона);\n- инструменты взломщика;\n- необычный дротик +1 с свойством возвращения;",101220,null],[108503,"2026-07-11T21:53:49",5,"// свиток потрачен?",101220,null],[108504,"2026-07-11T21:54:07",11,"// я писала что их было два",101220,null],[108505,"2026-07-11T21:54:12",11,"// тебе повезло один остался",101220,null],[108603,"2026-07-11T22:19:45",53,"//кстати, какой дротик ты мне передать хотел?",108503,null],[108611,"2026-07-11T22:20:37",5,"Дракон достал самый обычный дротик. На нём резаком было выцарапано. \"От Н. Г.\"",108603,null],[108612,"2026-07-11T22:21:42",11,"// не когтями?",108611,null],[108621,"2026-07-11T22:23:09",5,"// нет, инструменты резчика есть",101220,null],[108624,"2026-07-11T22:23:25",5,"// просто дротик на память)",108603,null],[109363,"2026-07-11T23:55:27",53,"кстати\nчто я нашел в той комнате?//",108501,null],[109364,"2026-07-11T23:55:38",53,"//",107345,null],[109371,"2026-07-11T23:56:53",11,"// зп несчастного головореза",109363,null],[109374,"2026-07-11T23:57:25",11,"// ну и можешь ещё хилку обычную записать себе",109363,null],[109378,"2026-07-12T00:00:00",11,"Во",101220,null],[109379,"2026-07-12T00:00:00",11,"Камни Возвращения\nЧудесный предмет, необычный (не требует настройки)\n\nЭтот комплект состоит из двух гладких камней размером с ладонь. Один из них считается якорем, а второй — камнем перехода. На их поверхности видны едва заметные рунические линии, которые начинают светиться при активации.\n\nСущество, способное накладывать хотя бы одно заклинание, может действием активировать камень перехода. Раз в 7 дней камень перехода может переместиться к якорю, перенося с собой до четырёх согласных неперегруженных существ Среднего размера или меньше, находящихся в пределах 5 футов от него.\n\nПеремещение возможно только если расстояние между камнями не превышает 1 милю (1,6 км). Все перенесённые существа появляются в незанятых пространствах в пределах 5 футов от камня-якоря.\n\nМагия этих камней несовершенна и вызывает сильное недомогание. Каждое существо, перенесённое таким образом, должно совершить спасбросок Телосложения со Сл 16.\n\nУспех. В течение 1 минуты каждый раз, когда существо совершает бросок атаки, проверку характеристики или спасбросок, оно должно бросить к4 и вычесть выпавшее значение из результата.\n\nПровал. Существо падает ничком сразу после перемещения и получает помеху на следующий бросок к20, который совершит. Кроме того, эффект штрафа к4 длится 1 час.",101220,null],[114760,"2026-07-14T16:10:51",5,"Сергей камни твои",101220,null]]);
